package org.apache.flink.formats.avro.typeutils;

import org.apache.avro.Schema;
import org.apache.avro.SchemaParseException;
import org.apache.avro.generic.GenericDatumReader;
import org.apache.avro.generic.GenericDatumWriter;
import org.apache.avro.generic.GenericRecord;
import org.apache.avro.reflect.ReflectData;
import org.apache.avro.reflect.ReflectDatumReader;
import org.apache.avro.reflect.ReflectDatumWriter;
import org.apache.avro.specific.SpecificData;
import org.apache.avro.specific.SpecificDatumReader;
import org.apache.avro.specific.SpecificDatumWriter;
import org.junit.jupiter.api.Test;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

/** Tests for {@link AvroFactory}. */
class AvroFactoryTest {

    @Test
    void testParseSchemaString() {
        assertThat(AvroFactory.parseSchemaString(null)).isNull();
        assertThat(AvroFactory.parseSchemaString(AvroTestFixtures.GENERIC_SCHEMA.toString()))
                .isEqualTo(AvroTestFixtures.GENERIC_SCHEMA);

        assertThatThrownBy(() -> AvroFactory.parseSchemaString("{invalid"))
                .isInstanceOf(SchemaParseException.class);
    }

    @Test
    void testCreateGenericFactory() {
        AvroFactory<GenericRecord> factory =
                AvroFactory.create(GenericRecord.class, AvroTestFixtures.GENERIC_SCHEMA, null);

        assertThat(factory.getSchema()).isEqualTo(AvroTestFixtures.GENERIC_SCHEMA);
        assertThat(factory.getWriter()).isInstanceOf(GenericDatumWriter.class);
        assertThat(factory.getReader()).isInstanceOf(GenericDatumReader.class);
        assertThat(factory.getEncoder()).isNotNull();
        assertThat(factory.getDecoder()).isNotNull();
        assertThat(factory.getAvroData()).isNotNull();
    }

    @Test
    void testCreateReflectiveFactory() {
        AvroFactory<AvroTestFixtures.ReflectivePojo> factory =
                AvroFactory.create(AvroTestFixtures.ReflectivePojo.class, null, null);

        assertThat(factory.getSchema().getType()).isEqualTo(Schema.Type.RECORD);
        assertThat(factory.getSchema().getFields())
                .extracting(Schema.Field::name)
                .contains("name", "age");
        assertThat(factory.getWriter()).isInstanceOf(ReflectDatumWriter.class);
        assertThat(factory.getReader()).isInstanceOf(ReflectDatumReader.class);
        assertThat(factory.getAvroData()).isInstanceOf(ReflectData.class);
    }

    @Test
    void testCreateSpecificFactoryAndExtractSchema() {
        AvroFactory<SpecificPojo> factory = AvroFactory.create(SpecificPojo.class, null, null);

        assertThat(factory.getSchema()).isEqualTo(SpecificPojo.SCHEMA);
        assertThat(factory.getWriter()).isInstanceOf(SpecificDatumWriter.class);
        assertThat(factory.getReader()).isInstanceOf(SpecificDatumReader.class);
        assertThat(factory.getAvroData()).isInstanceOf(SpecificData.class);

        @SuppressWarnings("unchecked")
        Class<? extends SpecificData> specificDataType =
                (Class<? extends SpecificData>) (Class<?>) SpecificPojo.class;
        SpecificData specificData =
                AvroFactory.getSpecificDataForClass(
                        specificDataType, Thread.currentThread().getContextClassLoader());
        assertThat(specificData).isNotNull();
        assertThat(AvroFactory.extractAvroSpecificSchema(SpecificPojo.class, specificData))
                .isEqualTo(SpecificPojo.SCHEMA);
    }

    @Test
    void testGetSpecificDataUsesModelFieldWhenPresent() {
        Class<?> typeWithModel = ClassWithModel.class;
        @SuppressWarnings("unchecked")
        Class<? extends SpecificData> castType = (Class<? extends SpecificData>) typeWithModel;

        assertThat(
                        AvroFactory.getSpecificDataForClass(
                                castType, Thread.currentThread().getContextClassLoader()))
                .isSameAs(ClassWithModel.MODEL$);
    }

    private static final class ClassWithModel {
        private static final SpecificData MODEL$ = new SpecificData();
    }

    @Test
    void testGenericFactoryRequiresSchema() {
        assertThatThrownBy(() -> AvroFactory.create(GenericRecord.class, null, null))
                .isInstanceOf(NullPointerException.class)
                .hasMessageContaining("without a schema");
    }
}
