package org.apache.flink.formats.avro.typeutils;

import org.apache.flink.api.common.typeutils.TypeSerializer;
import org.apache.flink.api.common.typeutils.TypeSerializerSchemaCompatibility;
import org.apache.flink.api.common.typeutils.TypeSerializerSnapshot;
import org.apache.flink.core.memory.DataInputDeserializer;
import org.apache.flink.core.memory.DataInputView;
import org.apache.flink.core.memory.DataOutputSerializer;
import org.apache.flink.core.memory.DataOutputView;

import org.apache.avro.Schema;
import org.apache.avro.generic.GenericData;
import org.apache.avro.generic.GenericRecord;
import org.junit.jupiter.api.Test;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

/** Tests for {@link AvroSerializerSnapshot}. */
class AvroSerializerSnapshotTest {

    @Test
    void testCurrentVersionAndNullStateValidation() {
        AvroSerializerSnapshot<GenericRecord> snapshot = new AvroSerializerSnapshot<>();
        assertThat(snapshot.getCurrentVersion()).isEqualTo(3);

        assertThatThrownBy(() -> snapshot.writeSnapshot(new DataOutputSerializer(8)))
                .isInstanceOf(NullPointerException.class);
    }

    @Test
    void testVersionedSnapshotRoundTripRestoresUsableSerializer() throws Exception {
        AvroSerializer<GenericRecord> original =
                new AvroSerializer<>(GenericRecord.class, AvroTestFixtures.GENERIC_SCHEMA);
        TypeSerializerSnapshot<GenericRecord> originalSnapshot = original.snapshotConfiguration();

        DataOutputSerializer out = new DataOutputSerializer(32);
        TypeSerializerSnapshot.writeVersionedSnapshot(out, originalSnapshot);

        TypeSerializerSnapshot<GenericRecord> readSnapshot =
                TypeSerializerSnapshot.readVersionedSnapshot(
                        new DataInputDeserializer(out.getCopyOfBuffer()),
                        Thread.currentThread().getContextClassLoader());

        assertThat(readSnapshot).isInstanceOf(AvroSerializerSnapshot.class);
        AvroSerializerSnapshot<GenericRecord> avroSnapshot =
                (AvroSerializerSnapshot<GenericRecord>) readSnapshot;
        assertThat(avroSnapshot.getSchema()).isEqualTo(AvroTestFixtures.GENERIC_SCHEMA);

        TypeSerializer<GenericRecord> restored = readSnapshot.restoreSerializer();
        GenericData.Record value = AvroTestFixtures.genericRecord("henry", 21, 4.5d);
        assertThat(roundTrip(restored, value)).isEqualTo(value);
    }

    @Test
    void testCompatibilityResolution() {
        TypeSerializerSchemaCompatibility<GenericRecord> same =
                AvroSerializerSnapshot.resolveSchemaCompatibility(
                        AvroTestFixtures.GENERIC_SCHEMA, AvroTestFixtures.GENERIC_SCHEMA);
        assertThat(same.isCompatibleAsIs()).isTrue();

        TypeSerializerSchemaCompatibility<GenericRecord> additive =
                AvroSerializerSnapshot.resolveSchemaCompatibility(
                        AvroTestFixtures.GENERIC_SCHEMA,
                        AvroTestFixtures.GENERIC_SCHEMA_WITH_EXTRA_FIELD);
        assertThat(additive.isCompatibleAfterMigration()).isTrue();

        TypeSerializerSchemaCompatibility<GenericRecord> incompatible =
                AvroSerializerSnapshot.resolveSchemaCompatibility(
                        AvroTestFixtures.GENERIC_SCHEMA,
                        AvroTestFixtures.GENERIC_SCHEMA_INCOMPATIBLE);
        assertThat(incompatible.isIncompatible()).isTrue();
    }

    @Test
    void testSnapshotCompatibilityUsesStoredWriterSchema() throws Exception {
        AvroSerializerSnapshot<GenericRecord> oldSnapshot =
                snapshotOf(AvroTestFixtures.GENERIC_SCHEMA);
        AvroSerializerSnapshot<GenericRecord> newSnapshot =
                snapshotOf(AvroTestFixtures.GENERIC_SCHEMA_WITH_EXTRA_FIELD);

        assertThat(newSnapshot.resolveSchemaCompatibility(oldSnapshot).isCompatibleAfterMigration())
                .isTrue();
        assertThat(oldSnapshot.resolveSchemaCompatibility(newSnapshot).isCompatibleAfterMigration())
                .isTrue();

        AvroSerializerSnapshot<GenericRecord> incompatibleSnapshot =
                snapshotOf(AvroTestFixtures.GENERIC_SCHEMA_INCOMPATIBLE);
        assertThat(incompatibleSnapshot.resolveSchemaCompatibility(oldSnapshot).isIncompatible())
                .isTrue();
    }

    @Test
    void testNonAvroSnapshotIsIncompatible() throws Exception {
        AvroSerializerSnapshot<GenericRecord> snapshot =
                snapshotOf(AvroTestFixtures.GENERIC_SCHEMA);

        assertThat(snapshot.resolveSchemaCompatibility(nonAvroSnapshot()).isIncompatible())
                .isTrue();
    }

    @Test
    void testReadV1SnapshotFallsBackToGenericRecord() throws Exception {
        DataOutputSerializer out = new DataOutputSerializer(32);
        out.writeUTF(AvroTestFixtures.GENERIC_SCHEMA.toString());

        AvroSerializerSnapshot<GenericRecord> snapshot = new AvroSerializerSnapshot<>();
        snapshot.readSnapshot(
                1,
                new DataInputDeserializer(out.getCopyOfBuffer()),
                Thread.currentThread().getContextClassLoader());

        assertThat(snapshot.getSchema()).isEqualTo(AvroTestFixtures.GENERIC_SCHEMA);
        TypeSerializer<GenericRecord> restored = snapshot.restoreSerializer();
        assertThat(roundTrip(restored, AvroTestFixtures.genericRecord("irene", 31, null)))
                .isNotNull();
    }

    @Test
    void testReadV2Snapshot() throws Exception {
        DataOutputSerializer out = new DataOutputSerializer(32);
        out.writeUTF(GenericRecord.class.getName());
        out.writeUTF(AvroTestFixtures.GENERIC_SCHEMA.toString());

        AvroSerializerSnapshot<GenericRecord> snapshot = new AvroSerializerSnapshot<>();
        snapshot.readSnapshot(
                2,
                new DataInputDeserializer(out.getCopyOfBuffer()),
                Thread.currentThread().getContextClassLoader());

        assertThat(snapshot.getSchema()).isEqualTo(AvroTestFixtures.GENERIC_SCHEMA);
        assertThat(snapshot.restoreSerializer()).isInstanceOf(AvroSerializer.class);
    }

    @Test
    void testUnknownSnapshotVersionIsRejected() {
        AvroSerializerSnapshot<GenericRecord> snapshot = new AvroSerializerSnapshot<>();

        assertThatThrownBy(
                        () ->
                                snapshot.readSnapshot(
                                        99,
                                        new DataInputDeserializer(new byte[0]),
                                        getClass().getClassLoader()))
                .isInstanceOf(IllegalArgumentException.class)
                .hasMessageContaining("unknown snapshot version");
    }

    @Test
    void testSpecificRecordSnapshotRestoresSpecificSerializer() throws Exception {
        AvroSerializer<SpecificPojo> serializer = new AvroSerializer<>(SpecificPojo.class);
        AvroSerializerSnapshot<SpecificPojo> snapshot =
                (AvroSerializerSnapshot<SpecificPojo>) serializer.snapshotConfiguration();

        DataOutputSerializer out = new DataOutputSerializer(32);
        snapshot.writeSnapshot(out);

        AvroSerializerSnapshot<SpecificPojo> restoredSnapshot = new AvroSerializerSnapshot<>();
        restoredSnapshot.readSnapshot(
                3,
                new DataInputDeserializer(out.getCopyOfBuffer()),
                Thread.currentThread().getContextClassLoader());

        assertThat(restoredSnapshot.getSchema()).isEqualTo(SpecificPojo.SCHEMA);
        TypeSerializer<SpecificPojo> restored = restoredSnapshot.restoreSerializer();
        assertThat(restored).isInstanceOf(AvroSerializer.class);

        SpecificPojo value = new SpecificPojo("judy", 44);
        SpecificPojo result = roundTrip(restored, value);
        assertThat(result.name.toString()).isEqualTo("judy");
        assertThat(result.age).isEqualTo(44);
    }

    private static AvroSerializerSnapshot<GenericRecord> snapshotOf(Schema schema) {
        return new AvroSerializerSnapshot<>(schema, GenericRecord.class);
    }

    private static TypeSerializerSnapshot<GenericRecord> nonAvroSnapshot() {
        return new TypeSerializerSnapshot<GenericRecord>() {
            @Override
            public int getCurrentVersion() {
                return 1;
            }

            @Override
            public void writeSnapshot(DataOutputView out) {}

            @Override
            public void readSnapshot(
                    int readVersion, DataInputView in, ClassLoader userCodeClassLoader) {}

            @Override
            public TypeSerializerSchemaCompatibility<GenericRecord> resolveSchemaCompatibility(
                    TypeSerializerSnapshot<GenericRecord> oldSerializerSnapshot) {
                return TypeSerializerSchemaCompatibility.incompatible();
            }

            @Override
            public TypeSerializer<GenericRecord> restoreSerializer() {
                return null;
            }
        };
    }

    private static <T> T roundTrip(TypeSerializer<T> serializer, T value) throws Exception {
        DataOutputSerializer out = new DataOutputSerializer(16);
        serializer.serialize(value, out);
        return serializer.deserialize(new DataInputDeserializer(out.getCopyOfBuffer()));
    }
}
