                                    + "\","
                                    + "\"fields\":["
                                    + "{\"name\":\"name\",\"type\":\"string\"},"
                                    + "{\"name\":\"age\",\"type\":\"int\"},"
                                    + "{\"name\":\"score\",\"type\":[\"null\",\"double\"],\"default\":null}"
                                    + "]"
                                    + "}");

    static final Schema GENERIC_SCHEMA_WITH_EXTRA_FIELD =
            new Schema.Parser()
                    .parse(
                            "{"
                                    + "\"type\":\"record\","
                                    + "\"name\":\"TestRecord\","
                                    + "\"namespace\":\""
                                    + RECORD_NAMESPACE
                                    + "\","
                                    + "\"fields\":["
                                    + "{\"name\":\"name\",\"type\":\"string\"},"
                                    + "{\"name\":\"age\",\"type\":\"int\"},"
                                    + "{\"name\":\"score\",\"type\":[\"null\",\"double\"],\"default\":null},"
                                    + "{\"name\":\"active\",\"type\":\"boolean\",\"default\":true}"
                                    + "]"
                                    + "}");

    static final Schema GENERIC_SCHEMA_INCOMPATIBLE =
