import org.junit.jupiter.api.Test;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.IntStream;

import static org.assertj.core.api.Assertions.assertThat;

/** Tests for {@link AvroTypeInfo}. */
class AvroTypeInfoTest {

    @Test
    void testFieldsAreDerivedFromAvroSchema() {
        AvroTypeInfo<SpecificPojo> typeInfo = new AvroTypeInfo<>(SpecificPojo.class);

        assertThat(typeInfo.getTypeClass()).isEqualTo(SpecificPojo.class);
        assertThat(typeInfo.isBasicType()).isFalse();
        assertThat(typeInfo.isTupleType()).isFalse();
        assertThat(typeInfo.getArity()).isEqualTo(2);
        assertThat(typeInfo.getTotalFields()).isEqualTo(2);

        List<PojoField> fields =
                IntStream.range(0, typeInfo.getArity())
                        .mapToObj(typeInfo::getPojoFieldAt)
                        .collect(Collectors.toList());
        assertThat(fields)
                .extracting(field -> field.getField().getName())
                .containsExactlyInAnyOrder("name", "age");

        PojoField nameField =
                fields.stream()
                        .filter(field -> field.getField().getName().equals("name"))
                        .findFirst()
                        .get();
        PojoField ageField =
                fields.stream()
                        .filter(field -> field.getField().getName().equals("age"))
                        .findFirst()
                        .get();

        assertThat(nameField.getTypeInformation().getTypeClass()).isEqualTo(Utf8.class);
        assertThat(ageField.getTypeInformation().getTypeClass()).isEqualTo(Integer.class);
    }

    @Test
    void testCreateSerializerProducesWorkingAvroSerializer() throws Exception {
        AvroTypeInfo<SpecificPojo> typeInfo = new AvroTypeInfo<>(SpecificPojo.class);

        TypeSerializer<SpecificPojo> serializer =
                typeInfo.createSerializer(new SerializerConfigImpl());
        assertThat(serializer).isInstanceOf(AvroSerializer.class);

        SpecificPojo value = new SpecificPojo("laura", 37);
        DataOutputSerializer out = new DataOutputSerializer(16);
        serializer.serialize(value, out);

        SpecificPojo result =
                serializer.deserialize(new DataInputDeserializer(out.getCopyOfBuffer()));
        assertThat(result.name.toString()).isEqualTo("laura");
        assertThat(result.age).isEqualTo(37);
    }

    @Test
    void testJavaSerialization() throws Exception {
        AvroTypeInfo<SpecificPojo> typeInfo = new AvroTypeInfo<>(SpecificPojo.class);

        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        try (ObjectOutputStream out = new ObjectOutputStream(bytes)) {
            out.writeObject(typeInfo);
        }

        try (ObjectInputStream in =
                new ObjectInputStream(new ByteArrayInputStream(bytes.toByteArray()))) {
            AvroTypeInfo<?> copy = (AvroTypeInfo<?>) in.readObject();
            assertThat(copy.getTypeClass()).isEqualTo(SpecificPojo.class);
            assertThat(copy.getArity()).isEqualTo(typeInfo.getArity());
        }
    }
}
