import org.junit.jupiter.api.Test;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

/** Tests for {@link GenericRecordAvroTypeInfo}. */
class GenericRecordAvroTypeInfoTest {

    @Test
    void testTypeInformationMetadata() {
        GenericRecordAvroTypeInfo typeInfo =
                new GenericRecordAvroTypeInfo(AvroTestFixtures.GENERIC_SCHEMA);

        assertThat(typeInfo.isBasicType()).isFalse();
        assertThat(typeInfo.isTupleType()).isFalse();
        assertThat(typeInfo.getArity()).isEqualTo(1);
        assertThat(typeInfo.getTotalFields()).isEqualTo(1);
        assertThat(typeInfo.getTypeClass()).isEqualTo(GenericRecord.class);
        assertThat(typeInfo.isKeyType()).isFalse();
        assertThat(typeInfo.canEqual(typeInfo)).isTrue();
        assertThat(typeInfo.canEqual("not a type info")).isFalse();
        assertThat(typeInfo.toString())
                .startsWith("GenericRecord(\"")
                .contains("TestRecord")
                .contains("name");
    }

    @Test
    void testEqualityAndHashCodeUseTheSchema() {
        GenericRecordAvroTypeInfo first =
                new GenericRecordAvroTypeInfo(AvroTestFixtures.GENERIC_SCHEMA);
        GenericRecordAvroTypeInfo same =
                new GenericRecordAvroTypeInfo(
                        new Schema.Parser().parse(AvroTestFixtures.GENERIC_SCHEMA.toString()));
        GenericRecordAvroTypeInfo different =
                new GenericRecordAvroTypeInfo(AvroTestFixtures.GENERIC_SCHEMA_WITH_EXTRA_FIELD);

        assertThat(first).isEqualTo(same);
        assertThat(first.hashCode()).isEqualTo(same.hashCode());
        assertThat(first).isNotEqualTo(different);
        assertThat(first).isNotEqualTo(null);
        assertThat(first).isNotEqualTo("different type");
    }

    @Test
    void testJavaSerializationPreservesSchema() throws Exception {
        GenericRecordAvroTypeInfo typeInfo =
                new GenericRecordAvroTypeInfo(AvroTestFixtures.GENERIC_SCHEMA);

        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        try (ObjectOutputStream out = new ObjectOutputStream(bytes)) {
            out.writeObject(typeInfo);
