package org.apache.flink.formats.avro.typeutils;

import org.junit.jupiter.api.Test;

import static org.assertj.core.api.Assertions.assertThat;

/** Tests for {@link AvroSerializerDebugInitHelper}. */
class AvroSerializerDebugInitHelperTest {

    @Test
    void testConcurrencyCheckIsNotEnabledByDefaultInProduction() {
        assertThat(AvroSerializerDebugInitHelper.INITIAL_SETTING).isFalse();
    }

    @Test
    void testDebugFlagCanBeToggledByTestsWithoutChangingInitialSetting() {
        boolean previous = AvroSerializerDebugInitHelper.setToDebug;
        try {
            AvroSerializerDebugInitHelper.setToDebug = false;
            assertThat(AvroSerializerDebugInitHelper.setToDebug).isFalse();
            AvroSerializerDebugInitHelper.setToDebug = true;
            assertThat(AvroSerializerDebugInitHelper.setToDebug).isTrue();
        } finally {
            AvroSerializerDebugInitHelper.setToDebug = previous;
        }
        assertThat(AvroSerializerDebugInitHelper.INITIAL_SETTING).isFalse();
    }
}

