import static org.assertj.core.api.Assertions.assertThat;

/** Tests for {@link SerializableAvroSchema}. */
class SerializableAvroSchemaTest {

    @Test
    void testNullSchemaRoundTrip() throws Exception {
        SerializableAvroSchema serializableSchema = new SerializableAvroSchema();
        assertThat(serializableSchema.getAvroSchema()).isNull();

        SerializableAvroSchema copy = javaRoundTrip(serializableSchema);
        assertThat(copy.getAvroSchema()).isNull();
    }

    @Test
    void testSchemaRoundTrip() throws Exception {
        SerializableAvroSchema serializableSchema =
                new SerializableAvroSchema(AvroTestFixtures.GENERIC_SCHEMA);

        SerializableAvroSchema copy = javaRoundTrip(serializableSchema);

        assertThat(copy).isNotSameAs(serializableSchema);
        assertThat(copy.getAvroSchema()).isEqualTo(AvroTestFixtures.GENERIC_SCHEMA);
        assertThat(copy.getAvroSchema().getFullName())
                .isEqualTo(AvroTestFixtures.GENERIC_SCHEMA.getFullName());
    }

    private static SerializableAvroSchema javaRoundTrip(SerializableAvroSchema schema)
            throws Exception {
        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        try (ObjectOutputStream out = new ObjectOutputStream(bytes)) {
            out.writeObject(schema);
        }

        try (ObjectInputStream in =
                new ObjectInputStream(new ByteArrayInputStream(bytes.toByteArray()))) {
            return (SerializableAvroSchema) in.readObject();
        }
    }
}

