/** A hand-written specific record, shaped like a class generated by Avro. */
public class SpecificPojo extends SpecificRecordBase {

    private static final long serialVersionUID = 1L;

    // CHECKSTYLE.OFF: ConstantName
    public static final Schema SCHEMA$ =
            new Schema.Parser()
                    .parse(
                            "{"
                                    + "\"type\":\"record\","
                                    + "\"name\":\"SpecificPojo\","
                                    + "\"namespace\":\"org.apache.flink.formats.avro.typeutils\","
                                    + "\"fields\":["
                                    + "{\"name\":\"name\",\"type\":\"string\"},"
                                    + "{\"name\":\"age\",\"type\":\"int\"}"
                                    + "]"
                                    + "}");
    // CHECKSTYLE.ON: ConstantName

    public static final Schema SCHEMA = SCHEMA$;

    public CharSequence name;
    public int age;

    public SpecificPojo() {}

    public SpecificPojo(CharSequence name, int age) {
        this.name = name;
        this.age = age;
    }

    @Override
    public Schema getSchema() {
        return SCHEMA$;
    }

    @Override
    public Object get(int field) {
        switch (field) {
            case 0:
                return name;
            case 1:
                return age;
            default:
                throw new IndexOutOfBoundsException("Unknown field index: " + field);
        }
    }

    @Override
    public void put(int field, Object value) {
        switch (field) {
            case 0:
                name = (CharSequence) value;
                break;
            case 1:
                age = (Integer) value;
                break;
            default:
                throw new IndexOutOfBoundsException("Unknown field index: " + field);
        }
    }
}

