import org.junit.jupiter.api.Test;

import java.io.IOException;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

/** Tests for {@link EnumNameDeserializer}. */
class EnumNameDeserializerTest {

    private static final String[] NAMES = {"RED", "GREEN", "BLUE"};

    enum TestEnum {
        RED,
        GREEN,
        BLUE
    }

    @Test
    void testDeserializeMapsWireOrdinalToName() throws IOException {
        EnumNameDeserializer deserializer = new EnumNameDeserializer(NAMES);

        assertThat(deserializer.deserialize(inputWithOrdinal(0))).isEqualTo("RED");
        assertThat(deserializer.deserialize(inputWithOrdinal(1))).isEqualTo("GREEN");
        assertThat(deserializer.deserialize(inputWithOrdinal(2))).isEqualTo("BLUE");
    }

    @Test
    void testDeserializeConsumesExactlyFourBytes() throws IOException {
        DataOutputSerializer out = new DataOutputSerializer(16);
        out.writeInt(1);
        out.writeInt(4711);
        DataInputView in = new DataInputDeserializer(out.getCopyOfBuffer());

        assertThat(new EnumNameDeserializer(NAMES).deserialize(in)).isEqualTo("GREEN");
        assertThat(in.readInt()).isEqualTo(4711);
    }

    @Test
    void testDeserializeWithReuseBehavesLikeDeserialize() throws IOException {
        EnumNameDeserializer deserializer = new EnumNameDeserializer(NAMES);

        assertThat(deserializer.deserialize("reuse-me", inputWithOrdinal(2))).isEqualTo("BLUE");
    }

    @Test
    void testDeserializeRejectsNegativeOrdinal() {
        assertThatThrownBy(() -> new EnumNameDeserializer(NAMES).deserialize(inputWithOrdinal(-1)))
                .isInstanceOf(IOException.class)
                .hasMessageContaining("Unknown enum ordinal -1")
                .hasMessageContaining("have 3 known constants");
    }

    @Test
    void testDeserializeRejectsOrdinalBeyondKnownConstants() {
        assertThatThrownBy(() -> new EnumNameDeserializer(NAMES).deserialize(inputWithOrdinal(3)))
                .isInstanceOf(IOException.class)
                .hasMessageContaining("Unknown enum ordinal 3")
                .hasMessageContaining("have 3 known constants");
    }

    @Test
    void testDeserializeFailsForEmptyNameArray() {
        assertThatThrownBy(
                        () ->
                                new EnumNameDeserializer(new String[0])
                                        .deserialize(inputWithOrdinal(0)))
                .isInstanceOf(IOException.class)
                .hasMessageContaining("have 0 known constants");
    }

    @Test
    void testCreateFromSnapshotDecodesBytesWrittenByEnumSerializer() throws IOException {
        EnumSerializer<TestEnum> enumSerializer = new EnumSerializer<>(TestEnum.class);

        DataOutputSerializer records = new DataOutputSerializer(32);
        for (TestEnum value : TestEnum.values()) {
            enumSerializer.serialize(value, records);
        }

        EnumSerializer.EnumSerializerSnapshot<TestEnum> snapshot = readBackSnapshot(enumSerializer);
        EnumNameDeserializer deserializer = EnumNameDeserializer.create(snapshot);

        DataInputView in = new DataInputDeserializer(records.getCopyOfBuffer());
        assertThat(deserializer.deserialize(in)).isEqualTo("RED");
        assertThat(deserializer.deserialize(in)).isEqualTo("GREEN");
        assertThat(deserializer.deserialize(in)).isEqualTo("BLUE");
    }

    @Test
    void testOrdinalsFollowSnapshotNameOrderNotJavaDeclarationOrder() throws IOException {
        // Simulate a savepoint whose enum was written when the constants were ordered
        // differently: the snapshot array defines the meaning of each wire ordinal.
        EnumSerializer.EnumSerializerSnapshot<TestEnum> snapshot =
                readBackSnapshot(TestEnum.class.getName(), "GREEN", "RED", "BLUE");

        EnumNameDeserializer deserializer = EnumNameDeserializer.create(snapshot);

        assertThat(deserializer.deserialize(inputWithOrdinal(0))).isEqualTo("GREEN");
        assertThat(deserializer.deserialize(inputWithOrdinal(1))).isEqualTo("RED");
        assertThat(deserializer.deserialize(inputWithOrdinal(2))).isEqualTo("BLUE");
    }

    @Test
    void testCreateInstanceReturnsFirstKnownName() {
        assertThat(new EnumNameDeserializer(NAMES).createInstance()).isEqualTo("RED");
    }

    @Test
    void testCreateInstanceIsNullWithoutKnownNames() {
        assertThat(new EnumNameDeserializer(new String[0]).createInstance()).isNull();
    }

    @Test
    void testSerializerIsImmutableAndHasFixedLength() {
        EnumNameDeserializer deserializer = new EnumNameDeserializer(NAMES);

        assertThat(deserializer.isImmutableType()).isTrue();
        assertThat(deserializer.getLength()).isEqualTo(4);
        assertThat(deserializer.duplicate()).isSameAs(deserializer);
    }

    @Test
    void testCopyReturnsInputValue() {
        EnumNameDeserializer deserializer = new EnumNameDeserializer(NAMES);

        assertThat(deserializer.copy("GREEN")).isEqualTo("GREEN");
        assertThat(deserializer.copy("BLUE", "GREEN")).isEqualTo("BLUE");
    }

    @Test
    void testSerializationIsNotSupported() {
        EnumNameDeserializer deserializer = new EnumNameDeserializer(NAMES);
        DataOutputSerializer out = new DataOutputSerializer(8);

        assertThatThrownBy(() -> deserializer.serialize("RED", out))
                .isInstanceOf(UnsupportedOperationException.class)
                .hasMessageContaining("read-only");
    }

    @Test
    void testCopyFromInputToOutputIsNotSupported() {
        EnumNameDeserializer deserializer = new EnumNameDeserializer(NAMES);
        DataOutputSerializer out = new DataOutputSerializer(8);

        assertThatThrownBy(() -> deserializer.copy(inputWithOrdinal(0), out))
                .isInstanceOf(UnsupportedOperationException.class)
                .hasMessageContaining("read-only");
    }

    @Test
    void testSnapshotConfigurationIsNotSupported() {
        assertThatThrownBy(() -> new EnumNameDeserializer(NAMES).snapshotConfiguration())
                .isInstanceOf(UnsupportedOperationException.class)
                .hasMessageContaining("never re-snapshotted");
    }

    @Test
    void testEqualsAndHashCodeAreBasedOnKnownNames() {
        EnumNameDeserializer first = new EnumNameDeserializer(new String[] {"RED", "GREEN"});
        EnumNameDeserializer same = new EnumNameDeserializer(new String[] {"RED", "GREEN"});
        EnumNameDeserializer different = new EnumNameDeserializer(new String[] {"RED", "BLUE"});

        assertThat(first).isEqualTo(same).hasSameHashCodeAs(same);
        assertThat(first).isEqualTo(first);
        assertThat(first).isNotEqualTo(different);
        assertThat(first).isNotEqualTo("RED");
        assertThat(first).isNotEqualTo(null);
    }

    // ------------------------------------------------------------------------
    //  Helpers
    // ------------------------------------------------------------------------

    private static DataInputView inputWithOrdinal(int ordinal) {
        DataOutputSerializer out = new DataOutputSerializer(4);
        try {
            out.writeInt(ordinal);
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
        return new DataInputDeserializer(out.getCopyOfBuffer());
    }

    private static EnumSerializer.EnumSerializerSnapshot<TestEnum> readBackSnapshot(
            EnumSerializer<TestEnum> serializer) throws IOException {
        DataOutputSerializer out = new DataOutputSerializer(64);
        TypeSerializerSnapshot.writeVersionedSnapshot(out, serializer.snapshotConfiguration());
        return readBackSnapshot(out.getCopyOfBuffer());
    }

    private static EnumSerializer.EnumSerializerSnapshot<TestEnum> readBackSnapshot(
            String enumClassName, String... names) throws IOException {
        DataOutputSerializer out = new DataOutputSerializer(64);
        out.writeUTF(enumClassName);
        out.writeInt(names.length);
        for (String name : names) {
            out.writeUTF(name);
        }

        EnumSerializer.EnumSerializerSnapshot<TestEnum> snapshot =
                new EnumSerializer.EnumSerializerSnapshot<>();
        snapshot.readSnapshot(
                snapshot.getCurrentVersion(),
                new DataInputDeserializer(out.getCopyOfBuffer()),
                EnumNameDeserializerTest.class.getClassLoader());
        return snapshot;
    }

    @SuppressWarnings("unchecked")
    private static EnumSerializer.EnumSerializerSnapshot<TestEnum> readBackSnapshot(
            byte[] snapshotBytes) throws IOException {
        TypeSerializerSnapshot<TestEnum> snapshot =
                TypeSerializerSnapshot.readVersionedSnapshot(
                        new DataInputDeserializer(snapshotBytes),
                        EnumNameDeserializerTest.class.getClassLoader());
        return (EnumSerializer.EnumSerializerSnapshot<TestEnum>) snapshot;
    }
}
