/** Tests for {@link InternalTypeConverter}. */
class InternalTypeConverterTest {

    @Test
    void testNullValueIsAlwaysConvertedToNull() {
        assertThat(InternalTypeConverter.toInternal(null, new IntType())).isNull();
        assertThat(InternalTypeConverter.toInternal(null, new RowType(true, List.of()))).isNull();
        assertThat(InternalTypeConverter.toInternal(null, new ArrayType(new IntType()))).isNull();
    }

    @Test
    void testCharacterStringConversion() {
        assertThat(InternalTypeConverter.toInternal("hello", new VarCharType()))
                .isEqualTo(StringData.fromString("hello"));

        // non-string values are stringified
        assertThat(InternalTypeConverter.toInternal(42, new VarCharType()))
                .isEqualTo(StringData.fromString("42"));

        assertThat(InternalTypeConverter.toInternal("ab", new CharType(3)))
                .isEqualTo(StringData.fromString("ab"));
    }

    @Test
    void testStringDataIsPassedThroughUnchanged() {
        StringData value = StringData.fromString("already internal");
        assertThat(InternalTypeConverter.toInternal(value, new VarCharType())).isSameAs(value);
    }

    @Test
    void testPrimitiveTypesArePassedThroughUnchanged() {
        Integer integer = 42;
        Long longValue = 42L;
        Double doubleValue = 1.5d;
        Boolean booleanValue = true;

        assertThat(InternalTypeConverter.toInternal(integer, new IntType())).isSameAs(integer);
        assertThat(InternalTypeConverter.toInternal(longValue, new BigIntType()))
                .isSameAs(longValue);
        assertThat(InternalTypeConverter.toInternal(doubleValue, new DoubleType()))
                .isSameAs(doubleValue);
        assertThat(InternalTypeConverter.toInternal(booleanValue, new BooleanType()))
                .isSameAs(booleanValue);
    }

    @Test
    void testDecimalFromBigDecimalKeepsPrecisionAndScale() {
        Object converted =
                InternalTypeConverter.toInternal(new BigDecimal("12.345"), new DecimalType(10, 3));

        assertThat(converted).isInstanceOf(DecimalData.class);
        DecimalData decimal = (DecimalData) converted;
        assertThat(decimal.precision()).isEqualTo(10);
        assertThat(decimal.scale()).isEqualTo(3);
        assertThat(decimal.toBigDecimal()).isEqualByComparingTo(new BigDecimal("12.345"));
    }

    @Test
    void testDecimalFromUnscaledBytes() {
        BigDecimal expected = new BigDecimal("12.34");
        byte[] unscaled = expected.unscaledValue().toByteArray();

        Object fromArray = InternalTypeConverter.toInternal(unscaled, new DecimalType(5, 2));
        Object fromBuffer =
                InternalTypeConverter.toInternal(ByteBuffer.wrap(unscaled), new DecimalType(5, 2));

        assertThat(((DecimalData) fromArray).toBigDecimal()).isEqualByComparingTo(expected);
        assertThat(((DecimalData) fromBuffer).toBigDecimal()).isEqualByComparingTo(expected);
    }

    @Test
    void testDecimalDataIsPassedThroughUnchanged() {
        DecimalData value = DecimalData.fromUnscaledBytes(new byte[] {1, 2}, 10, 2);
        assertThat(InternalTypeConverter.toInternal(value, new DecimalType(10, 2))).isSameAs(value);
    }

    @Test
    void testDateConversion() {
        LocalDate date = LocalDate.of(2021, 3, 4);
        int epochDay = (int) date.toEpochDay();

        assertThat(InternalTypeConverter.toInternal(java.sql.Date.valueOf(date), new DateType()))
                .isEqualTo(epochDay);
        assertThat(InternalTypeConverter.toInternal(date, new DateType())).isEqualTo(epochDay);
        assertThat(InternalTypeConverter.toInternal(epochDay, new DateType())).isEqualTo(epochDay);
    }

    @Test
    void testTimestampConversions() {
        TimestampType type = new TimestampType(3);

        Timestamp timestamp = Timestamp.valueOf("2021-03-04 05:06:07.123");
        assertThat(InternalTypeConverter.toInternal(timestamp, type))
                .isEqualTo(TimestampData.fromTimestamp(timestamp));

        Instant instant = Instant.ofEpochMilli(1_600_000_000_123L);
        assertThat(InternalTypeConverter.toInternal(instant, type))
                .isEqualTo(TimestampData.fromInstant(instant));

        LocalDateTime localDateTime = LocalDateTime.of(2021, 3, 4, 5, 6, 7, 123_000_000);
        assertThat(InternalTypeConverter.toInternal(localDateTime, type))
                .isEqualTo(TimestampData.fromLocalDateTime(localDateTime));

        TimestampData timestampData = TimestampData.fromEpochMillis(1000, 42);
        assertThat(InternalTypeConverter.toInternal(timestampData, type)).isSameAs(timestampData);
    }

    @Test
    void testTimestampWithLocalTimeZoneUsesSameConversion() {
        LocalDateTime localDateTime = LocalDateTime.of(2021, 3, 4, 5, 6, 7);
        Object converted =
                InternalTypeConverter.toInternal(localDateTime, new LocalZonedTimestampType(3));
        assertThat(converted).isEqualTo(TimestampData.fromLocalDateTime(localDateTime));
    }

    @Test
    void testBinaryConversion() {
        byte[] bytes = {1, 2, 3};

        assertThat(InternalTypeConverter.toInternal(ByteBuffer.wrap(bytes), new VarBinaryType(10)))
                .isEqualTo(bytes);
        // byte arrays are already in the internal representation
        assertThat(InternalTypeConverter.toInternal(bytes, new VarBinaryType(10))).isSameAs(bytes);
    }

    @Test
    void testNullTypeAlwaysProducesNull() {
        assertThat(InternalTypeConverter.toInternal("ignored", new NullType())).isNull();
    }

    @Test
    void testRowConversionConvertsFieldsRecursively() {
        RowType rowType =
                new RowType(
                        true,
                        Arrays.asList(
                                new RowType.RowField("name", new VarCharType()),
                                new RowType.RowField("age", new IntType())));

        Row row = Row.of("Alice", 42);
        row.setKind(RowKind.UPDATE_AFTER);

        Object converted = InternalTypeConverter.toInternal(row, rowType);

        assertThat(converted).isInstanceOf(GenericRowData.class);
        GenericRowData rowData = (GenericRowData) converted;
        assertThat(rowData.getArity()).isEqualTo(2);
        assertThat(rowData.getRowKind()).isEqualTo(RowKind.UPDATE_AFTER);
        assertThat(rowData.getString(0)).isEqualTo(StringData.fromString("Alice"));
        assertThat(rowData.getInt(1)).isEqualTo(42);
    }

    @Test
    void testRowWithMoreFieldsThanRowTypeKeepsExtraFieldsUnconverted() {
        RowType rowType =
                new RowType(true, List.of(new RowType.RowField("name", new VarCharType())));

        GenericRowData rowData =
                (GenericRowData) InternalTypeConverter.toInternal(Row.of("Alice", 7), rowType);

        assertThat(rowData.getArity()).isEqualTo(2);
        assertThat(rowData.getString(0)).isEqualTo(StringData.fromString("Alice"));
        assertThat(rowData.getField(1)).isEqualTo(7);
    }

    @Test
    void testGenericRowDataIsPassedThroughUnchanged() {
        GenericRowData rowData = GenericRowData.of(StringData.fromString("x"));
        assertThat(InternalTypeConverter.toInternal(rowData, new RowType(true, List.of())))
                .isSameAs(rowData);
    }

    @Test
    void testArrayConversionFromObjectArray() {
        ArrayType type = new ArrayType(new VarCharType());

        GenericArrayData arrayData =
                (GenericArrayData) InternalTypeConverter.toInternal(new Object[] {"a", null}, type);

        assertThat(arrayData.size()).isEqualTo(2);
        assertThat(arrayData.getString(0)).isEqualTo(StringData.fromString("a"));
        assertThat(arrayData.isNullAt(1)).isTrue();
    }

    @Test
    void testArrayConversionFromIterable() {
        ArrayType type = new ArrayType(new IntType());

        GenericArrayData arrayData =
                (GenericArrayData) InternalTypeConverter.toInternal(Arrays.asList(1, 2, 3), type);

        assertThat(arrayData.toObjectArray()).containsExactly(1, 2, 3);
    }

    @Test
    void testGenericArrayDataIsPassedThroughUnchanged() {
        GenericArrayData arrayData = new GenericArrayData(new Object[] {1});
        assertThat(InternalTypeConverter.toInternal(arrayData, new ArrayType(new IntType())))
                .isSameAs(arrayData);
    }

    @Test
    void testMapConversionFromMap() {
        MapType type = new MapType(new VarCharType(), new IntType());
        Map<String, Integer> map = new LinkedHashMap<>();
        map.put("one", 1);
        map.put("two", 2);

        GenericMapData mapData = (GenericMapData) InternalTypeConverter.toInternal(map, type);

        assertThat(mapData.size()).isEqualTo(2);
        assertThat(mapData.get(StringData.fromString("one"))).isEqualTo(1);
        assertThat(mapData.get(StringData.fromString("two"))).isEqualTo(2);
    }

    @Test
    void testMapConversionFromMapEntryIterable() {
        MapType type = new MapType(new VarCharType(), new IntType());
        Iterable<Map.Entry<String, Integer>> entries =
                List.of(new AbstractMap.SimpleEntry<>("key", 11));

        GenericMapData mapData = (GenericMapData) InternalTypeConverter.toInternal(entries, type);

        assertThat(mapData.size()).isEqualTo(1);
        assertThat(mapData.get(StringData.fromString("key"))).isEqualTo(11);
    }

    @Test
    void testMapConversionRejectsNonEntryIterables() {
        MapType type = new MapType(new VarCharType(), new IntType());

        assertThatThrownBy(() -> InternalTypeConverter.toInternal(List.of("not-an-entry"), type))
                .isInstanceOf(UnsupportedOperationException.class)
                .hasMessageContaining("Iterable<Map.Entry>");
    }

    @Test
    void testGenericMapDataIsPassedThroughUnchanged() {
        GenericMapData mapData =
                new GenericMapData(Collections.singletonMap(StringData.fromString("k"), 1));
        assertThat(
                        InternalTypeConverter.toInternal(
                                mapData, new MapType(new VarCharType(), new IntType())))
                .isSameAs(mapData);
    }

    @Test
    void testMultisetConversionFromMap() {
        MultisetType type = new MultisetType(new IntType());
        Map<Integer, Integer> multiplicities = new LinkedHashMap<>();
        multiplicities.put(7, 3);

        GenericMapData mapData =
                (GenericMapData) InternalTypeConverter.toInternal(multiplicities, type);

        assertThat(mapData.size()).isEqualTo(1);
        assertThat(mapData.get(7)).isEqualTo(3);
    }

    @Test
    void testMultisetConversionFromEntryIterable() {
        MultisetType type = new MultisetType(new IntType());

        GenericMapData mapData =
                (GenericMapData)
                        InternalTypeConverter.toInternal(
                                List.of(new AbstractMap.SimpleEntry<>(7, 3)), type);

        assertThat(mapData.get(7)).isEqualTo(3);
    }

    @Test
    void testUnsupportedTypeRootFails() {
        LogicalType rawType = new RawType<>(Integer.class, IntSerializer.INSTANCE);

        assertThatThrownBy(() -> InternalTypeConverter.toInternal(42, rawType))
                .isInstanceOf(UnsupportedOperationException.class)
                .hasMessageContaining("RAW");
    }

    @Test
    void testNestedRowInsideArrayIsConvertedRecursively() {
        RowType rowType =
                new RowType(true, List.of(new RowType.RowField("name", new VarCharType())));
        ArrayType arrayType = new ArrayType(rowType);

        GenericArrayData arrayData =
                (GenericArrayData)
                        InternalTypeConverter.toInternal(new Object[] {Row.of("Alice")}, arrayType);

        RowData nested = arrayData.getRow(0, 1);
        assertThat(nested.getString(0)).isEqualTo(StringData.fromString("Alice"));
    }
}
