/** Tests for {@link MissingClassSerializerFactory}. */
class MissingClassSerializerFactoryTest {

    @Test
    void testCreatesPojoDeserializerForPojoSnapshot() {
        TypeSerializer<SimplePojo> serializer = pojoSerializer(SimplePojo.class);
        PojoSerializerSnapshot<SimplePojo> snapshot = snapshot(serializer);

        TypeSerializer<?> created = MissingClassSerializerFactory.create(snapshot);

        assertThat(created).isInstanceOf(PojoToRowDataDeserializer.class);
        assertThat(created).isEqualTo(PojoToRowDataDeserializer.create(snapshot));
    }

    @Test
    void testCreatesEnumNameDeserializerForEnumSnapshot() throws Exception {
        EnumSerializer<Color> enumSerializer = new EnumSerializer<>(Color.class);
        EnumSerializer.EnumSerializerSnapshot<Color> snapshot = readBackSnapshot(enumSerializer);

        DataOutputSerializer records = new DataOutputSerializer(32);
        enumSerializer.serialize(Color.GREEN, records);

        TypeSerializer<?> created = MissingClassSerializerFactory.create(snapshot);

        assertThat(created).isInstanceOf(EnumNameDeserializer.class);
        assertThat(created.deserialize(input(records.getCopyOfBuffer()))).isEqualTo("GREEN");
    }

    @Test
    void testRejectsSnapshotsWithoutFallback() {
        TypeSerializerSnapshot<Integer> unsupported =
                IntSerializer.INSTANCE.snapshotConfiguration();

        assertThatThrownBy(() -> MissingClassSerializerFactory.create(unsupported))
                .isInstanceOf(UnsupportedOperationException.class)
                .hasMessageContaining("No fallback serializer available")
                .hasMessageContaining(unsupported.getClass().getName());
    }

    @Test
    void testCreatesAvroSerializerForAvroSnapshot() throws Exception {
        Schema schema =
                new Schema.Parser()
                        .parse(
                                "{\"type\":\"record\",\"name\":\"SimpleRecord\",\"fields\":["
                                        + "{\"name\":\"name\",\"type\":\"string\"},"
                                        + "{\"name\":\"value\",\"type\":\"int\"}]}");
        AvroSerializer<GenericRecord> avroSerializer =
                new AvroSerializer<>(GenericRecord.class, schema);

        GenericData.Record record = new GenericData.Record(schema);
        record.put("name", "avro");
        record.put("value", 3);

        DataOutputSerializer out = new DataOutputSerializer(64);
        avroSerializer.serialize(record, out);

        TypeSerializerSnapshot<GenericRecord> snapshot = avroSerializer.snapshotConfiguration();
        TypeSerializer<?> created = MissingClassSerializerFactory.create(snapshot);

        assertThat(created).isInstanceOf(AvroSerializer.class);
        assertThat(created.deserialize(input(out.getCopyOfBuffer()))).isEqualTo(record);
    }

    @Test
    void testPojoClassCanBeMissingWhenFactoryIsRegistered() throws Exception {
        TypeSerializer<SimplePojo> serializer = pojoSerializer(SimplePojo.class);
        byte[] recordBytes = serialize(serializer, new SimplePojo("Alice", 42));
        byte[] snapshotBytes = writeSnapshot(serializer);

        ClassLoader classLoader = filteringClassLoader(SimplePojo.class.getName());

        CustomRestoreSerializerFactory.set(MissingClassSerializerFactory::create);
        try {
            TypeSerializerSnapshot<SimplePojo> readSnapshot =
                    readSnapshot(snapshotBytes, classLoader);
            PojoSerializerSnapshot<SimplePojo> pojoSnapshot =
                    (PojoSerializerSnapshot<SimplePojo>) readSnapshot;

            assertThat(pojoSnapshot.isPojoClassAvailable()).isFalse();
            assertThat(pojoSnapshot.getPojoClassName()).isEqualTo(SimplePojo.class.getName());

            TypeSerializer<?> created = MissingClassSerializerFactory.create(pojoSnapshot);
            assertThat(created).isInstanceOf(PojoToRowDataDeserializer.class);

            RowData row = (RowData) created.deserialize(input(recordBytes));
            assertThat(row.getInt(0)).isEqualTo(42);
            assertThat(row.getString(1)).isEqualTo(StringData.fromString("Alice"));
        } finally {
            CustomRestoreSerializerFactory.remove();
        }

        assertThat(CustomRestoreSerializerFactory.get()).isNull();
    }

    @Test
    void testEnumClassCanBeMissingWhenFactoryIsRegistered() throws Exception {
        EnumSerializer<Color> enumSerializer = new EnumSerializer<>(Color.class);
        DataOutputSerializer records = new DataOutputSerializer(32);
        enumSerializer.serialize(Color.BLUE, records);

        byte[] snapshotBytes = writeSnapshot(enumSerializer);
        ClassLoader classLoader = filteringClassLoader(Color.class.getName());

        CustomRestoreSerializerFactory.set(MissingClassSerializerFactory::create);
        try {
            TypeSerializerSnapshot<Color> snapshot = readSnapshot(snapshotBytes, classLoader);
            TypeSerializer<?> created = MissingClassSerializerFactory.create(snapshot);

            assertThat(created).isInstanceOf(EnumNameDeserializer.class);
            assertThat(created.deserialize(input(records.getCopyOfBuffer()))).isEqualTo("BLUE");
        } finally {
            CustomRestoreSerializerFactory.remove();
        }
    }

    @Test
    void testReadingMissingClassFailsWithoutRegisteredFactory() throws Exception {
        byte[] snapshotBytes = writeSnapshot(pojoSerializer(SimplePojo.class));
        ClassLoader classLoader = filteringClassLoader(SimplePojo.class.getName());

        DataInputView in = input(snapshotBytes);

        assertThatThrownBy(() -> TypeSerializerSnapshot.readVersionedSnapshot(in, classLoader))
                .isInstanceOf(NoClassDefFoundError.class)
                .hasMessageContaining(SimplePojo.class.getName());
    }

    @SuppressWarnings("unchecked")
    private static EnumSerializer.EnumSerializerSnapshot<Color> readBackSnapshot(
            EnumSerializer<Color> serializer) throws IOException {
        TypeSerializerSnapshot<Color> snapshot =
                readSnapshot(
                        writeSnapshot(serializer),
                        MissingClassSerializerFactoryTest.class.getClassLoader());
        return (EnumSerializer.EnumSerializerSnapshot<Color>) snapshot;
    }
}
