/** Lifecycle tests for the concrete iterative task classes. */
class IterativeTaskLifecycleTest {

    @Test
    void headCountsTheExtraInitialSolutionSetInputOnlyForWorksetIterations() {
        Environment environment = environment(JobID.generate(), 0);
        TestHeadTask headTask = new TestHeadTask(environment);
        TaskConfig config = new TaskConfig(new Configuration());
        config.setIterationId(1);
        headTask.setConfig(config);
        headTask.setDriver(IterativeTaskTestEnvironment.driver(2));

        assertThat(headTask.numberOfTaskInputs()).isEqualTo(2);

        config.setIsWorksetIteration();
        assertThat(headTask.numberOfTaskInputs()).isEqualTo(3);
    }

    @Test
    void intermediateTaskRejectsSimultaneousWorksetAndSolutionSetUpdates() throws Exception {
        JobID jobId = JobID.generate();
        Environment environment = environment(jobId, 0);
        TestIntermediateTask task = new TestIntermediateTask(environment);
        TaskConfig config = new TaskConfig(new Configuration());
        config.setIterationId(4);
        config.setIsWorksetUpdate();
        config.setIsSolutionSetUpdate();
        task.setConfig(config);
        task.setDriver(IterativeTaskTestEnvironment.driver(0));
        task.setChainedTasks(new ArrayList<>());

        String key = jobId + "#4#0";
        TestBlockingBackChannel backChannel = new TestBlockingBackChannel();
        BlockingBackChannelBroker.instance().handIn(key, backChannel);
        try {
            assertThatThrownBy(task::initializeTask)
                    .isInstanceOf(IllegalStateException.class)
                    .hasMessageContaining("workset and solutions set update");
        } finally {
            BlockingBackChannelBroker.instance().remove(key);
        }
    }

    @Test
    void intermediateTaskWrapsOutputWithWorksetUpdateCollector() throws Exception {
        JobID jobId = JobID.generate();
        Environment environment = environment(jobId, 2);
        TestIntermediateTask task = new TestIntermediateTask(environment);
        TaskConfig config = new TaskConfig(new Configuration());
        config.setIterationId(8);
        config.setIsWorksetUpdate();
        config.setOutputSerializer(
                new RuntimeSerializerFactory<>(IntSerializer.INSTANCE, Integer.class));
        task.setConfig(config);
        task.setDriver(IterativeTaskTestEnvironment.driver(0));
        task.setChainedTasks(new ArrayList<>());

        String key = jobId + "#8#2";
        TestBlockingBackChannel backChannel = new TestBlockingBackChannel();
        BlockingBackChannelBroker.instance().handIn(key, backChannel);
        try {
            task.initializeTask();

            assertThat(task.outputCollector()).isInstanceOf(WorksetUpdateOutputCollector.class);
            assertThat(backChannel.getWriteEndCalls).isEqualTo(1);
        } finally {
            BlockingBackChannelBroker.instance().remove(key);
        }
    }

    @Test
    void tailRejectsPlansThatDoNotUpdateIterationState() throws Exception {
        Environment environment = environment(JobID.generate(), 0);
        TestTailTask task = new TestTailTask(environment);
        TaskConfig config = new TaskConfig(new Configuration());
        config.setIterationId(2);
        task.setConfig(config);
        task.setDriver(IterativeTaskTestEnvironment.driver(0));
        task.setChainedTasks(new ArrayList<>());

        assertThatThrownBy(task::initializeTask)
                .isInstanceOf(RuntimeException.class)
                .hasMessageContaining("doesn't update workset or the solution set");
    }

    @Test
    void tailWithBulkSolutionSetUpdateUsesBarrierAndNoOpCollector() throws Exception {
        JobID jobId = JobID.generate();
        Environment environment = environment(jobId, 1);
        TestTailTask task = new TestTailTask(environment);
        TaskConfig config = new TaskConfig(new Configuration());
        config.setIterationId(11);
        config.setIsSolutionSetUpdate();
        task.setConfig(config);
        task.setDriver(IterativeTaskTestEnvironment.driver(0));
        task.setChainedTasks(new ArrayList<>());

        String key = jobId + "#11#1";
        SolutionSetUpdateBarrier barrier = new SolutionSetUpdateBarrier();
        SolutionSetUpdateBarrierBroker.instance().handIn(key, barrier);
        try {
            task.initializeTask();

            assertThat(task.outputCollector()).isNotNull();
            task.outputCollector().collect(42);
            task.outputCollector().close();
        } finally {
            SolutionSetUpdateBarrierBroker.instance().remove(key);
        }
    }

    @Test
    void intermediateAndTailExitWithoutWorkWhenTerminationWasAlreadyRequested() throws Exception {
        Environment environment = environment(JobID.generate(), 0);
        TaskConfig config = new TaskConfig(new Configuration());
        config.setIterationId(13);
        String key = environment.getJobID() + "#13#0";

        TestIntermediateTask intermediateTask = new TestIntermediateTask(environment);
        intermediateTask.setConfig(config);
        intermediateTask.requestTermination();
        SuperstepKickoffLatchBroker.instance().handIn(key, new SuperstepKickoffLatch());
        try {
            intermediateTask.run();
        } finally {
            SuperstepKickoffLatchBroker.instance().remove(key);
        }
        assertThat(intermediateTask.terminationRequested()).isTrue();

        TestTailTask tailTask = new TestTailTask(environment);
        tailTask.setConfig(config);
        tailTask.requestTermination();
        SuperstepKickoffLatchBroker.instance().handIn(key, new SuperstepKickoffLatch());
        try {
            tailTask.run();
        } finally {
            SuperstepKickoffLatchBroker.instance().remove(key);
        }
        assertThat(tailTask.terminationRequested()).isTrue();
    }

    private static Environment environment(JobID jobId, int subtaskIndex) {
        return IterativeTaskTestEnvironment.environment(jobId, subtaskIndex);
    }

    /** Back channel whose write side can be inspected without allocating network buffers. */
    private static final class TestBlockingBackChannel extends BlockingBackChannel {
        private final DataOutputView outputView =
                new DataOutputViewStreamWrapper(new ByteArrayOutputStream());
        private int getWriteEndCalls;

        TestBlockingBackChannel() {
            super((SerializedUpdateBuffer) null);
        }

        @Override
        public DataOutputView getWriteEnd() {
            getWriteEndCalls++;
            return outputView;
        }
    }

    private static final class TestHeadTask
            extends IterationHeadTask<Integer, Integer, Function, Integer> {

        TestHeadTask(Environment environment) {
            super(environment);
        }

        void setConfig(TaskConfig config) {
            this.config = config;
        }

        void setDriver(Driver<Function, Integer> driver) {
