            extends IterationIntermediateTask<Function, Integer> {

        TestIntermediateTask(Environment environment) {
            super(environment);
        }

        void setConfig(TaskConfig config) {
            this.config = config;
        }

        void setDriver(Driver<Function, Integer> driver) {
            this.driver = driver;
        }

        void setChainedTasks(List<ChainedDriver<?, ?>> tasks) {
            this.chainedTasks = new ArrayList<>(tasks);
        }

        void initializeTask() throws Exception {
            initialize();
        }

        Collector<Integer> outputCollector() {
            return this.output;
        }
    }

    private static final class TestTailTask extends IterationTailTask<Function, Integer> {

        TestTailTask(Environment environment) {
            super(environment);
        }

        void setConfig(TaskConfig config) {
            this.config = config;
        }

        void setDriver(Driver<Function, Integer> driver) {
            this.driver = driver;
        }

        void setChainedTasks(List<ChainedDriver<?, ?>> tasks) {
            this.chainedTasks = new ArrayList<>(tasks);
        }

        void initializeTask() throws Exception {
            initialize();
        }

        Collector<Integer> outputCollector() {
            return this.output;
        }
    }
