package org.apache.flink.runtime.iterative.task;

import org.apache.flink.api.common.aggregators.Aggregator;
import org.apache.flink.api.common.aggregators.LongSumAggregator;
import org.apache.flink.runtime.iterative.event.IterationEventWithAggregators;
import org.apache.flink.runtime.iterative.event.TerminationEvent;
import org.apache.flink.runtime.iterative.event.WorkerDoneEvent;
import org.apache.flink.types.LongValue;

import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;

import java.lang.reflect.Field;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

/** Tests for {@link SyncEventHandler}. */
class SyncEventHandlerTest {

    @AfterEach
    void clearInterruptFlag() {
        Thread.interrupted();
    }

    @Test
    void constructorRequiresAPositiveNumberOfEvents() {
        assertThatThrownBy(
                        () ->
                                new SyncEventHandler(
                                        0, Collections.emptyMap(), getClass().getClassLoader()))
                .isInstanceOf(IllegalArgumentException.class);
        assertThatThrownBy(
                        () ->
                                new SyncEventHandler(
                                        -3, Collections.emptyMap(), getClass().getClassLoader()))
                .isInstanceOf(IllegalArgumentException.class);
    }

    @Test
    void workerEventsAreAggregatedAndEndOfSuperstepIsSignalledAtTheConfiguredBoundary()
            throws Exception {
        LongSumAggregator aggregator = new LongSumAggregator();
        Map<String, Aggregator<?>> aggregators =
                Collections.<String, Aggregator<?>>singletonMap("count", aggregator);
        SyncEventHandler handler =
                new SyncEventHandler(2, aggregators, getClass().getClassLoader());

        handler.onEvent(workerDoneEvent(3L));

        assertThat(aggregator.getAggregate().getValue()).isEqualTo(3L);
        assertThat(handler.isEndOfSuperstep()).isFalse();
        assertThat(Thread.currentThread().isInterrupted()).isFalse();

        handler.onEvent(workerDoneEvent(4L));

        assertThat(aggregator.getAggregate().getValue()).isEqualTo(7L);
        assertThat(handler.isEndOfSuperstep()).isTrue();
        assertThat(Thread.currentThread().isInterrupted()).isTrue();
    }

    @Test
    void resettingEndOfSuperstepAllowsAnotherEventRound() throws Exception {
        LongSumAggregator aggregator = new LongSumAggregator();
        SyncEventHandler handler =
                new SyncEventHandler(
                        2,
                        Collections.<String, Aggregator<?>>singletonMap("count", aggregator),
                        getClass().getClassLoader());

        handler.onEvent(workerDoneEvent(1L));
        handler.onEvent(workerDoneEvent(2L));
        assertThat(handler.isEndOfSuperstep()).isTrue();
        Thread.interrupted();

        handler.resetEndOfSuperstep();

        assertThat(handler.isEndOfSuperstep()).isFalse();
        // The event count is cumulative; after two events another single event does not finish
        // a superstep.
        handler.onEvent(workerDoneEvent(3L));
        assertThat(handler.isEndOfSuperstep()).isFalse();
        assertThat(aggregator.getAggregate().getValue()).isEqualTo(6L);
        assertThat(Thread.currentThread().isInterrupted()).isFalse();

        handler.onEvent(workerDoneEvent(4L));
        assertThat(handler.isEndOfSuperstep()).isTrue();
        assertThat(aggregator.getAggregate().getValue()).isEqualTo(10L);
        assertThat(Thread.currentThread().isInterrupted()).isTrue();
    }

    @Test
    void multipleAggregatorsAreUpdatedFromOneWorkerEvent() throws Exception {
        LongSumAggregator first = new LongSumAggregator();
        LongSumAggregator second = new LongSumAggregator();
        Map<String, Aggregator<?>> aggregators = new LinkedHashMap<>();
        aggregators.put("first", first);
        aggregators.put("second", second);
        SyncEventHandler handler =
                new SyncEventHandler(1, aggregators, getClass().getClassLoader());

        WorkerDoneEvent event =
                new WorkerDoneEvent(
                        0,
                        new AggregatorWithNameMap()
                                .put("first", 5L)
                                .put("second", 8L)
                                .aggregators());
        handler.onEvent(event);

        assertThat(first.getAggregate().getValue()).isEqualTo(5L);
        assertThat(second.getAggregate().getValue()).isEqualTo(8L);
        assertThat(handler.isEndOfSuperstep()).isTrue();
        assertThat(Thread.currentThread().isInterrupted()).isTrue();
    }

    @Test
    void anotherWorkerEventBeforeResetIsRejected() throws Exception {
        LongSumAggregator aggregator = new LongSumAggregator();
        SyncEventHandler handler =
                new SyncEventHandler(
                        1,
                        Collections.<String, Aggregator<?>>singletonMap("count", aggregator),
                        getClass().getClassLoader());

        handler.onEvent(workerDoneEvent(1L));
        assertThat(handler.isEndOfSuperstep()).isTrue();
        Thread.interrupted();

        assertThatThrownBy(() -> handler.onEvent(workerDoneEvent(2L)))
                .isInstanceOf(RuntimeException.class)
                .hasMessageContaining("End-of-Superstep");
        assertThat(aggregator.getAggregate().getValue()).isEqualTo(1L);
    }

    @Test
    void nonWorkerDoneEventsAreRejected() {
        SyncEventHandler handler =
                new SyncEventHandler(1, Collections.emptyMap(), getClass().getClassLoader());

        assertThatThrownBy(() -> handler.onEvent(new TerminationEvent()))
                .isInstanceOf(IllegalStateException.class)
                .hasMessageContaining(TerminationEvent.class.getName());
        assertThat(handler.isEndOfSuperstep()).isFalse();
    }

    @Test
    void workerEventWithInconsistentAggregateArraysIsRejected() throws Exception {
        LongSumAggregator aggregator = new LongSumAggregator();
        SyncEventHandler handler =
                new SyncEventHandler(
                        1,
                        Collections.<String, Aggregator<?>>singletonMap("count", aggregator),
                        getClass().getClassLoader());
        WorkerDoneEvent event = workerDoneEvent(1L);

        Field namesField = IterationEventWithAggregators.class.getDeclaredField("aggNames");
        namesField.setAccessible(true);
        namesField.set(event, new String[] {"count", "extra"});

        assertThatThrownBy(() -> handler.onEvent(event))
                .isInstanceOf(RuntimeException.class)
                .hasMessageContaining("Inconsistent WorkerDoneEvent");
        assertThat(handler.isEndOfSuperstep()).isFalse();
        assertThat(Thread.currentThread().isInterrupted()).isFalse();
    }

    private static WorkerDoneEvent workerDoneEvent(long aggregate) {
        return new WorkerDoneEvent(0, "count", new LongValue(aggregate));
    }

    /** Small builder that avoids relying on map iteration order in tests. */
    private static final class AggregatorWithNameMap {
        private final Map<String, Aggregator<?>> aggregators = new LinkedHashMap<>();

        AggregatorWithNameMap put(String name, long value) {
            LongSumAggregator aggregator = new LongSumAggregator();
            aggregator.aggregate(value);
            aggregators.put(name, aggregator);
            return this;
        }

        Map<String, Aggregator<?>> aggregators() {
            return aggregators;
        }
    }
}

