    @Test
    void solutionSetCollectorSupportsBothManagedAndObjectSolutionSets() throws Exception {
        JobID jobId = JobID.fromHexString("33333333333333333333333333333333");
        Environment environment = environment(jobId, 0);
        TestIterativeTask task = new TestIterativeTask(environment);
        TaskConfig config = new TaskConfig(new Configuration());
        config.setIterationId(5);
        task.setConfig(config);
        String key = task.brokerKey();

        CompactingHashTable<Integer> hashTable =
                new CompactingHashTable<>(
                        IntSerializer.INSTANCE, new IntComparator(true), memorySegments());
        try {
            SolutionSetBroker.instance().handIn(key, hashTable);
            Collector<Integer> managed = task.createSolutionSetCollector(null);
            assertThat(managed).isInstanceOf(SolutionSetUpdateOutputCollector.class);
            hashTable.close();
        } finally {
            SolutionSetBroker.instance().remove(key);
        }

        JoinHashMap<Integer> joinHashMap =
                new JoinHashMap<>(IntSerializer.INSTANCE, new IntComparator(true));
        SolutionSetBroker.instance().handIn(key, joinHashMap);
        try {
            Collector<Integer> objectBacked = task.createSolutionSetCollector(null);
            assertThat(objectBacked).isInstanceOf(SolutionSetObjectsUpdateOutputCollector.class);
        } finally {
            SolutionSetBroker.instance().remove(key);
        }
    }

    @Test
    void solutionSetCollectorRejectsUnknownHandles() {
        Environment environment = environment(JobID.generate(), 0);
        TestIterativeTask task = new TestIterativeTask(environment);
        TaskConfig config = new TaskConfig(new Configuration());
        config.setIterationId(6);
        task.setConfig(config);
        String key = task.brokerKey();
        Object unexpected = new Object();
        SolutionSetBroker.instance().handIn(key, unexpected);
        try {
            assertThatThrownBy(() -> task.createSolutionSetCollector(null))
                    .isInstanceOf(RuntimeException.class)
                    .hasMessageContaining("Unrecognized solution set handle");
        } finally {
            SolutionSetBroker.instance().remove(key);
        }
    }

    private static Environment environment(JobID jobId, int subtaskIndex) {
        return IterativeTaskTestEnvironment.environment(jobId, subtaskIndex);
    }

    private static List<MemorySegment> memorySegments() {
        List<MemorySegment> segments = new ArrayList<>();
        for (int i = 0; i < 33; i++) {
            segments.add(MemorySegmentFactory.allocateUnpooledSegment(4096));
        }
        return segments;
    }

    /** Configurable reader fake that records superstep transitions. */
    private static final class TestReader implements MutableReader<IntValue> {
        private final boolean[] finishedResults;
        private final boolean endOfSuperstep;
        private int finishedCalls;
        private int startedSupersteps;

        TestReader(boolean finished, boolean endOfSuperstep) {
            this(new boolean[] {finished}, endOfSuperstep);
        }

        TestReader(boolean[] finishedResults, boolean endOfSuperstep) {
            this.finishedResults = finishedResults;
            this.endOfSuperstep = endOfSuperstep;
        }

        @Override
        public boolean isFinished() {
            int index = Math.min(finishedCalls++, finishedResults.length - 1);
            return finishedResults[index];
        }

        @Override
        public void sendTaskEvent(TaskEvent event) {}

        @Override
        public void registerTaskEventListener(
                EventListener<TaskEvent> listener, Class<? extends TaskEvent> eventType) {}

        @Override
        public void setIterativeReader() {}

        @Override
        public void startNextSuperstep() {
            startedSupersteps++;
        }

        @Override
        public boolean hasReachedEndOfSuperstep() {
            return endOfSuperstep;
        }

        @Override
        public boolean next(IntValue target) {
            return false;
        }

        @Override
        public void clearBuffers() {}
    }

