/** Tests for {@link IterationSynchronizationSinkTask}. */
class IterationSynchronizationSinkTaskTest {

    @AfterEach
    void clearInterruptFlag() {
        Thread.interrupted();
    }

    @Test
    void terminationCanBeRequestedAndIsIdempotent() {
        IterationSynchronizationSinkTask task =
                new IterationSynchronizationSinkTask(
                        IterativeTaskTestEnvironment.environment(JobID.generate(), 0));

        assertThat(task.terminationRequested()).isFalse();
        task.requestTermination();
        assertThat(task.terminationRequested()).isTrue();
        task.requestTermination();
        assertThat(task.terminationRequested()).isTrue();
    }

    @Test
    void reachingMaximumNumberOfIterationsSendsTerminationEvent() throws Exception {
        Configuration configuration = new Configuration();
        TaskConfig taskConfig = new TaskConfig(configuration);
        taskConfig.setNumberOfIterations(1);
        taskConfig.setGateIterativeWithNumberOfEventsUntilInterrupt(0, 1);

        GateController gate = new GateController(1);
        Environment environment = environment(configuration, gate.gate);
        IterationSynchronizationSinkTask task = new IterationSynchronizationSinkTask(environment);
        ExecutorService executor = Executors.newSingleThreadExecutor();
        Future<?> invocation = executor.submit(() -> invoke(task));

        try {
            assertThat(gate.awaitEntered(0)).isTrue();
            publishWorkerDone(task);
            gate.release(0);
            invocation.get(5, TimeUnit.SECONDS);

            assertThat(task.terminationRequested()).isTrue();
            assertThat(gate.sentEvents).hasSize(1);
            assertThat(gate.sentEvents.get(0)).isInstanceOf(TerminationEvent.class);
        } finally {
            gate.releaseAll();
            executor.shutdownNow();
            assertThat(executor.awaitTermination(5, TimeUnit.SECONDS)).isTrue();
        }
    }

    @Test
    void nonConvergedIterationSignalsAllWorkersDoneAndContinues() throws Exception {
        Configuration configuration = new Configuration();
        TaskConfig taskConfig = new TaskConfig(configuration);
        taskConfig.setNumberOfIterations(2);
        taskConfig.setGateIterativeWithNumberOfEventsUntilInterrupt(0, 1);

        GateController gate = new GateController(2);
        Environment environment = environment(configuration, gate.gate);
        IterationSynchronizationSinkTask task = new IterationSynchronizationSinkTask(environment);
        ExecutorService executor = Executors.newSingleThreadExecutor();
        Future<?> invocation = executor.submit(() -> invoke(task));

        try {
            assertThat(gate.awaitEntered(0)).isTrue();
            publishWorkerDone(task);
            gate.release(0);

            assertThat(gate.awaitEntered(1)).isTrue();
            assertThat(gate.sentEvents).hasSize(1);
            assertThat(gate.sentEvents.get(0)).isInstanceOf(AllWorkersDoneEvent.class);

            publishWorkerDone(task);
            gate.release(1);
            invocation.get(5, TimeUnit.SECONDS);

            assertThat(task.terminationRequested()).isTrue();
            assertThat(gate.sentEvents).hasSize(2);
            assertThat(gate.sentEvents.get(1)).isInstanceOf(TerminationEvent.class);
        } finally {
            gate.releaseAll();
            executor.shutdownNow();
            assertThat(executor.awaitTermination(5, TimeUnit.SECONDS)).isTrue();
        }
    }

    @Test
    void convergenceCriterionCanTerminateBeforeTheIterationLimit() throws Exception {
        Configuration configuration = new Configuration();
        TaskConfig taskConfig = new TaskConfig(configuration);
        taskConfig.setNumberOfIterations(10);
        taskConfig.setGateIterativeWithNumberOfEventsUntilInterrupt(0, 1);
        taskConfig.addIterationAggregator("convergence", new LongSumAggregator());
        taskConfig.setConvergenceCriterion("convergence", new AlwaysConvergedCriterion());

        GateController gate = new GateController(1);
        Environment environment = environment(configuration, gate.gate);
        IterationSynchronizationSinkTask task = new IterationSynchronizationSinkTask(environment);
        ExecutorService executor = Executors.newSingleThreadExecutor();
        Future<?> invocation = executor.submit(() -> invoke(task));

        try {
            assertThat(gate.awaitEntered(0)).isTrue();
            publishWorkerDone(task);
            gate.release(0);
            invocation.get(5, TimeUnit.SECONDS);

            assertThat(task.terminationRequested()).isTrue();
            assertThat(gate.sentEvents).hasSize(1);
            assertThat(gate.sentEvents.get(0)).isInstanceOf(TerminationEvent.class);
        } finally {
            gate.releaseAll();
            executor.shutdownNow();
            assertThat(executor.awaitTermination(5, TimeUnit.SECONDS)).isTrue();
        }
    }

    private static void invoke(IterationSynchronizationSinkTask task) {
        try {
            task.invoke();
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    private static void publishWorkerDone(IterationSynchronizationSinkTask task) throws Exception {
        Field readerField =
                IterationSynchronizationSinkTask.class.getDeclaredField("headEventReader");
        readerField.setAccessible(true);
        @SuppressWarnings("unchecked")
        MutableRecordReader<IntValue> reader =
                (MutableRecordReader<IntValue>) readerField.get(task);
        reader.publish(new WorkerDoneEvent(0, Collections.emptyMap()));
        // SyncEventHandler interrupts the thread publishing the worker event when the
        // superstep boundary is reached. The interrupt belongs to the test thread here.
        Thread.interrupted();
    }

    private static Environment environment(Configuration configuration, IndexedInputGate gate) {
        Map<String, Object> returns = new HashMap<>();
        returns.put("getInputGate", gate);
        returns.put("getTaskConfiguration", configuration);
        return IterativeTaskTestEnvironment.environment(JobID.generate(), 0, returns);
    }

    private static final class GateController {
        private final ControlledGate gate = new ControlledGate();
        private final List<TaskEvent> sentEvents = new CopyOnWriteArrayList<>();
        private final List<CountDownLatch> entered = new ArrayList<>();
        private final List<CountDownLatch> released = new ArrayList<>();
        private final AtomicInteger calls = new AtomicInteger();

        GateController(int expectedCalls) {
            for (int i = 0; i < expectedCalls; i++) {
                entered.add(new CountDownLatch(1));
                released.add(new CountDownLatch(1));
            }
            gate.entered = entered;
            gate.released = released;
            gate.calls = calls;
            gate.sentEvents = sentEvents;
        }

        boolean awaitEntered(int call) throws InterruptedException {
            return entered.get(call).await(5, TimeUnit.SECONDS);
        }

        void release(int call) {
            released.get(call).countDown();
        }

        void releaseAll() {
            for (CountDownLatch latch : released) {
                latch.countDown();
            }
        }
    }

    /** Input gate that hands control of each read back to the test thread. */
    private static final class ControlledGate extends IndexedInputGate {
        private List<CountDownLatch> entered;
        private List<CountDownLatch> released;
        private AtomicInteger calls;
        private List<TaskEvent> sentEvents;

        @Override
        public Optional<BufferOrEvent> getNext() throws IOException, InterruptedException {
            int call = calls.getAndIncrement();
            entered.get(call).countDown();
            released.get(call).await();
            throw new InterruptedException();
        }

        @Override
        public Optional<BufferOrEvent> pollNext() {
            return Optional.empty();
        }

        @Override
        public void sendTaskEvent(TaskEvent event) {
            sentEvents.add(event);
        }

        @Override
        public int getNumberOfInputChannels() {
            return 0;
        }

        @Override
        public boolean isFinished() {
            return false;
        }

        @Override
        public EndOfDataStatus hasReceivedEndOfData() {
            return EndOfDataStatus.NOT_END_OF_DATA;
        }

        @Override
        public void resumeGateConsumption() {}

        @Override
        public void resumeConsumption(InputChannelInfo channelInfo) {}

        @Override
        public void acknowledgeAllRecordsProcessed(InputChannelInfo channelInfo) {}

        @Override
        public InputChannel getChannel(int channelIndex) {
            return null;
        }

        @Override
        public InputChannel getChannel(InputChannelInfo channelInfo) {
            return null;
        }

        @Override
        public void setup() {}

        @Override
        public void requestPartitions() {}

        @Override
        public CompletableFuture<Void> getStateConsumedFuture() {
            return CompletableFuture.completedFuture(null);
        }

        @Override
        public void finishReadRecoveredState() {}

        @Override
        public int getGateIndex() {
            return 0;
        }

        @Override
        public List<InputChannelInfo> getUnfinishedChannels() {
            return Collections.emptyList();
        }

        @Override
        public List<InputChannelInfo> getChannelInfos() {
            return Collections.emptyList();
        }

        @Override
        public ResultPartitionType getConsumedPartitionType() {
            return ResultPartitionType.PIPELINED;
        }

        @Override
        public void triggerDebloating() {}

        @Override
        public void close() {}

        @Override
        public void checkpointStarted(CheckpointBarrier barrier) throws CheckpointException {}

        @Override
        public void checkpointStopped(long cancelledCheckpointId) {}
    }

    /** Convergence criterion used to verify that convergence can end an iteration early. */
    private static final class AlwaysConvergedCriterion implements ConvergenceCriterion<Value> {
        private static final long serialVersionUID = 1L;

        @Override
        public boolean isConverged(int iteration, Value value) {
            return true;
        }
    }
