    @Test
    void intermediateTaskRejectsSimultaneousWorksetAndSolutionSetUpdates() throws Exception {
        JobID jobId = JobID.generate();
        Environment environment = environment(jobId, 0);
        TestIntermediateTask task = new TestIntermediateTask(environment);
        TaskConfig config = new TaskConfig(new Configuration());
        config.setIterationId(4);
        config.setIsWorksetUpdate();
        config.setIsSolutionSetUpdate();
        task.setConfig(config);
        task.setDriver(IterativeTaskTestEnvironment.driver(0));
        task.setChainedTasks(new ArrayList<>());

        String key = jobId + "#4#0";
        TestBlockingBackChannel backChannel = new TestBlockingBackChannel();
        BlockingBackChannelBroker.instance().handIn(key, backChannel);
        try {
            assertThatThrownBy(task::initializeTask)
                    .isInstanceOf(IllegalStateException.class)
                    .hasMessageContaining("workset and solutions set update");
        } finally {
            BlockingBackChannelBroker.instance().remove(key);
