import org.apache.flink.runtime.operators.Driver;
import org.apache.flink.runtime.taskmanager.TaskManagerRuntimeInfo;
import org.apache.flink.util.UserCodeClassLoader;

import java.lang.reflect.InvocationHandler;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

/**
 * Lightweight test doubles for the collaborators used by the iterative tasks. The types are
 * intentionally kept local to the module so the tests do not depend on heavyweight cluster
 * components.
 */
final class IterativeTaskTestEnvironment {

    private IterativeTaskTestEnvironment() {}

    static Environment environment(JobID jobId, int subtaskIndex) {
        return environment(jobId, subtaskIndex, Collections.emptyMap());
    }

    static Environment environment(
            JobID jobId, int subtaskIndex, Map<String, Object> additionalReturns) {
        Map<String, Object> returns = new HashMap<>();
        returns.put("getJobID", jobId);
        returns.put("getJobInfo", proxy(JobInfo.class, Collections.emptyMap()));
        returns.put("getExecutionConfig", new ExecutionConfig());
        returns.put("getDistributedCacheEntries", Collections.emptyMap());
        returns.put(
                "getExternalResourceInfoProvider",
                ExternalResourceInfoProvider.NO_EXTERNAL_RESOURCES);
        returns.put("getTaskInfo", taskInfo(subtaskIndex));
        returns.put("getUserCodeClassLoader", classLoader());
        returns.put("getBroadcastVariableManager", new BroadcastVariableManager());
        returns.put("getTaskManagerInfo", taskManagerInfo());
        returns.putAll(additionalReturns);
        return proxy(Environment.class, returns);
    }

    static TaskInfo taskInfo(int subtaskIndex) {
        Map<String, Object> returns = new HashMap<>();
        returns.put("getTaskName", "iterative-task");
        returns.put("getTaskNameWithSubtasks", "iterative-task (" + (subtaskIndex + 1) + "/1)#0");
        returns.put("getIndexOfThisSubtask", subtaskIndex);
        returns.put("getNumberOfParallelSubtasks", 1);
        returns.put("getMaxNumberOfParallelSubtasks", 1);
        returns.put("getAttemptNumber", 0);
        returns.put("getAllocationIDAsString", "test-allocation");
        return proxy(TaskInfo.class, returns);
    }

    static UserCodeClassLoader classLoader() {
        Map<String, Object> returns = new HashMap<>();
        returns.put("asClassLoader", IterativeTaskTestEnvironment.class.getClassLoader());
        return proxy(UserCodeClassLoader.class, returns);
    }

    static OperatorMetricGroup metricGroup() {
        return proxy(OperatorMetricGroup.class, Collections.emptyMap());
    }

    @SuppressWarnings("unchecked")
    static Driver<Function, Integer> driver(int numberOfInputs) {
        Map<String, Object> returns = new HashMap<>();
        returns.put("getNumberOfInputs", numberOfInputs);
        returns.put("getNumberOfDriverComparators", 0);
        returns.put("getStubType", null);
        return (Driver<Function, Integer>) proxy(Driver.class, returns);
    }

    static TaskManagerRuntimeInfo taskManagerInfo() {
        Map<String, Object> returns = new HashMap<>();
        returns.put("getTmpDirectories", new String[0]);
        returns.put("getConfiguration", new Configuration());
        return proxy(TaskManagerRuntimeInfo.class, returns);
    }

    @SuppressWarnings("unchecked")
    static <T> T proxy(Class<T> type, Map<String, Object> returns) {
        InvocationHandler handler =
                (proxy, method, args) -> {
                    if (method.getDeclaringClass() == Object.class) {
                        return handleObjectMethod(proxy, method, args);
                    }
                    if (returns.containsKey(method.getName())) {
                        return returns.get(method.getName());
                    }
                    return defaultValue(method.getReturnType());
                };
        return (T)
                Proxy.newProxyInstance(
                        IterativeTaskTestEnvironment.class.getClassLoader(),
                        new Class<?>[] {type},
                        handler);
    }

    private static Object handleObjectMethod(Object proxy, Method method, Object[] args) {
        switch (method.getName()) {
            case "toString":
                return "TestDouble(" + proxy.getClass().getInterfaces()[0].getSimpleName() + ")";
            case "hashCode":
                return System.identityHashCode(proxy);
            case "equals":
                return proxy == args[0];
            default:
                throw new UnsupportedOperationException(method.getName());
        }
    }

    private static Object defaultValue(Class<?> type) {
        if (!type.isPrimitive()) {
            return null;
        }
        if (type == boolean.class) {
            return false;
        } else if (type == byte.class) {
            return (byte) 0;
        } else if (type == short.class) {
            return (short) 0;
        } else if (type == int.class) {
            return 0;
        } else if (type == long.class) {
            return 0L;
        } else if (type == float.class) {
            return 0.0f;
        } else if (type == double.class) {
            return 0.0d;
        } else if (type == char.class) {
            return '\0';
        } else {
            return null;
        }
    }
}

