        @Override
        public String getRpcUrl(
                String hostname,
                int port,
                String endpointName,
                AddressResolution addressResolution,
                Configuration config)
                throws UnknownHostException {
            throw new UnsupportedOperationException();
        }

        @Override
        public InetSocketAddress getInetSocketAddressFromRpcUrl(String url) {
            invocationCount++;
            lastUrl = url;
            return address;
        }

        @Override
        public long getMaximumMessageSizeInBytes(Configuration config) {
            throw new UnsupportedOperationException();
        }

        private int getInvocationCount() {
            return invocationCount;
        }

        private String getLastUrl() {
            return lastUrl;
        }
    }

    private static void assertAssignedToLocalInterface(InetAddress address) throws SocketException {
        assertNotNull(address);
        assertNotNull(
                NetworkInterface.getByInetAddress(address),
                "Address is not assigned to a local network interface: " + address);
    }
