/** Tests for {@link RedirectingSslHandler}. */
class RedirectingSslHandlerTest {

    @Test
    void redirectsPlainHttpRequestToConfiguredBaseUrl() throws Exception {
        final SSLHandlerFactory factory = unusedSslHandlerFactory();
        final RedirectingSslHandler handler =
                new RedirectingSslHandler(
                        "ignored.example.org",
                        CompletableFuture.completedFuture("https://leader.example.org:8443"),
                        factory);
        final EmbeddedChannel channel = new LocalAddressEmbeddedChannel(handler);

        try {
            final String response =
                    writeHttpRequestAndReadFirstResponse(
                            channel,
                            "GET /jobs/overview?limit=10 HTTP/1.1\r\nHost: localhost\r\n\r\n");

            assertRedirect(response, "https://leader.example.org:8443/jobs/overview?limit=10");
        } finally {
            if (channel.isOpen()) {
                channel.finishAndReleaseAll();
            }
        }
    }

    @Test
    void usesConfiguredHostAndLocalPortWhileRedirectBaseUrlIsPending() throws Exception {
        final SSLHandlerFactory factory = unusedSslHandlerFactory();
        final RedirectingSslHandler handler =
                new RedirectingSslHandler(
                        "gateway.example.org", new CompletableFuture<>(), factory);
        final InetSocketAddress localAddress = new InetSocketAddress("127.0.0.1", 31_234);
        final EmbeddedChannel channel = new LocalAddressEmbeddedChannel(localAddress, handler);

        try {
            final String response =
                    writeHttpRequestAndReadFirstResponse(
                            channel, "GET /health HTTP/1.1\r\nHost: localhost\r\n\r\n");

            assertRedirect(response, "https://gateway.example.org:31234/health");
        } finally {
            if (channel.isOpen()) {
                channel.finishAndReleaseAll();
            }
        }
    }

    @Test
    void completedRedirectBaseUrlTakesPrecedenceOverConfiguredHostAndLocalPort() throws Exception {
        final SSLHandlerFactory factory = unusedSslHandlerFactory();
        final RedirectingSslHandler handler =
                new RedirectingSslHandler(
                        "ignored.example.org",
                        CompletableFuture.completedFuture("https://external.example.org:9443"),
                        factory);
        final EmbeddedChannel channel =
                new LocalAddressEmbeddedChannel(
                        new InetSocketAddress("127.0.0.1", 31_234), handler);

        try {
            final String response =
                    writeHttpRequestAndReadFirstResponse(
                            channel, "GET /overview HTTP/1.1\r\nHost: localhost\r\n\r\n");

            assertRedirect(response, "https://external.example.org:9443/overview");
        } finally {
            if (channel.isOpen()) {
                channel.finishAndReleaseAll();
            }
        }
    }

    @Test
    void plainHttpRequestInstallsHttpCodecAndRedirectHandler() throws Exception {
        final SSLHandlerFactory factory = unusedSslHandlerFactory();
        final RedirectingSslHandler handler =
                new RedirectingSslHandler(
                        "localhost",
                        CompletableFuture.completedFuture("https://localhost:8443"),
                        factory);
        final EmbeddedChannel channel = new LocalAddressEmbeddedChannel(handler);

        try {
            writeHttpRequest(channel, "GET / HTTP/1.1\r\nHost: localhost\r\n");

            assertNotNull(channel.pipeline().get("http-codec"));
            assertNotNull(channel.pipeline().get("redirecting-non-ssl"));
            assertNull(channel.pipeline().get("ssl"));
        } finally {
            if (channel.isOpen()) {
                channel.finishAndReleaseAll();
            }
        }
    }

    @Test
    void encryptedRecordIsReplacedBySslHandler() throws Exception {
        final TestSslHandlerFactory factory = new TestSslHandlerFactory();
        final RedirectingSslHandler handler =
                new RedirectingSslHandler(
                        "localhost",
                        CompletableFuture.completedFuture("https://localhost:8443"),
                        factory);
        final EmbeddedChannel channel = new LocalAddressEmbeddedChannel(handler);

        try {
            channel.writeInbound(
                    Unpooled.wrappedBuffer(
                            new byte[] {
                                0x16, 0x03, 0x01, 0x00, 0x05, 0x01, 0x00, 0x00, 0x01, 0x00
                            }));

            assertTrue(channel.pipeline().get("ssl") instanceof NoOpHandshakeSslHandler);
            assertNull(channel.pipeline().get("http-codec"));
            assertEquals(1, factory.getCreatedHandlers());
        } finally {
            if (channel.isOpen()) {
                channel.finishAndReleaseAll();
            }
        }
    }

    @Test
    void shortNonSslPrefixIsTreatedAsPlainHttp() throws Exception {
        final SSLHandlerFactory factory = unusedSslHandlerFactory();
        final RedirectingSslHandler handler =
                new RedirectingSslHandler(
                        "localhost",
                        CompletableFuture.completedFuture("https://localhost:8443"),
                        factory);
        final EmbeddedChannel channel = new LocalAddressEmbeddedChannel(handler);

        try {
            channel.writeInbound(Unpooled.wrappedBuffer(new byte[] {'G', 'E', 'T'}));

            assertNotNull(channel.pipeline().get("http-codec"));
            assertNotNull(channel.pipeline().get("redirecting-non-ssl"));
        } finally {
            if (channel.isOpen()) {
                channel.finishAndReleaseAll();
            }
        }
    }

    private static void writeHttpRequest(EmbeddedChannel channel, String request) {
        channel.writeInbound(Unpooled.copiedBuffer(request, StandardCharsets.US_ASCII));
    }

    private static String writeHttpRequestAndReadFirstResponse(
            EmbeddedChannel channel, String request) {
        writeHttpRequest(channel, request);

        String firstResponse = null;
        Object message;
        while ((message = channel.readOutbound()) != null) {
            try {
                if (message instanceof ByteBuf) {
                    final String decoded = ((ByteBuf) message).toString(StandardCharsets.US_ASCII);
                    if (firstResponse == null && decoded.startsWith("HTTP/")) {
                        firstResponse = decoded;
                    }
                }
            } finally {
                ReferenceCountUtil.release(message);
            }
        }

        assertNotNull(firstResponse, "No HTTP response was written by the handler");
        return firstResponse;
    }

    private static void assertRedirect(String response, String expectedLocation) {
        assertTrue(
                response.startsWith("HTTP/1.1 301 Moved Permanently\r\n"),
                "Unexpected response status: " + response);
        assertTrue(
                response.toLowerCase(Locale.ROOT)
                        .contains(("location: " + expectedLocation).toLowerCase(Locale.ROOT)),
                "Response does not contain expected location "
                        + expectedLocation
                        + ": "
                        + response);
    }

    private static final class TestSslHandlerFactory extends SSLHandlerFactory {
        private final SslContext sslContext;
        private int createdHandlers;

        private TestSslHandlerFactory() throws Exception {
            this(SslContextBuilder.forClient().sslProvider(SslProvider.JDK).build());
        }

        private TestSslHandlerFactory(SslContext sslContext) {
            super(sslContext, -1, -1);
            this.sslContext = sslContext;
        }

        @Override
        public SslHandler createNettySSLHandler(ByteBufAllocator allocator) {
            createdHandlers++;
            return new NoOpHandshakeSslHandler(sslContext.newEngine(allocator));
        }

        private int getCreatedHandlers() {
            return createdHandlers;
        }
    }

    private static final class NoOpHandshakeSslHandler extends SslHandler {
        private NoOpHandshakeSslHandler(SSLEngine engine) {
            super(engine);
        }

        @Override
        protected void decode(ChannelHandlerContext context, ByteBuf in, List<Object> out) {
            in.skipBytes(in.readableBytes());
        }
    }

    private static SSLHandlerFactory unusedSslHandlerFactory() throws Exception {
        return new SSLHandlerFactory(
                SslContextBuilder.forClient().sslProvider(SslProvider.JDK).build(), -1, -1) {
            @Override
            public SslHandler createNettySSLHandler(ByteBufAllocator allocator) {
                throw new AssertionError("SSL handler must not be created for a non-SSL request");
            }
        };
    }

    private static final class LocalAddressEmbeddedChannel extends EmbeddedChannel {
        private final SocketAddress localAddress;

        private LocalAddressEmbeddedChannel(ChannelHandler... handlers) {
            this(new InetSocketAddress("127.0.0.1", 1), handlers);
        }

        private LocalAddressEmbeddedChannel(
                SocketAddress localAddress, ChannelHandler... handlers) {
            super(handlers);
            this.localAddress = localAddress;
        }

        @Override
        protected SocketAddress localAddress0() {
            return localAddress;
        }
    }
