/** Tests for {@link SSLUtils}. */
class SSLUtilsTest {

    private static final String TEST_PASSWORD = "password";
    private static final String TEST_PROTOCOL = "TLSv1.2";
    private static final String TEST_CIPHER = "TLS_ECDHE_RSA_WITH_AES_128_GCM_SHA256";

    @Test
    void defaultSslProviderIsJdk() {
        assertEquals(JDK, SSLUtils.getSSLProvider(new Configuration()));
    }

    @Test
    void sslProviderParsingIsCaseInsensitiveAndRejectsUnknownValues() {
        final Configuration configuration = new Configuration();
        configuration.set(SecurityOptions.SSL_PROVIDER, "jdk");
        assertEquals(JDK, SSLUtils.getSSLProvider(configuration));

        configuration.set(SecurityOptions.SSL_PROVIDER, "OpEnSsL");
        if (OpenSsl.isAvailable()) {
            assertEquals(OPENSSL, SSLUtils.getSSLProvider(configuration));
        } else {
            final IllegalConfigurationException exception =
                    assertThrows(
                            IllegalConfigurationException.class,
                            () -> SSLUtils.getSSLProvider(configuration));
            assertTrue(exception.getMessage().contains("openSSL not available"));
        }

        configuration.set(SecurityOptions.SSL_PROVIDER, "not-a-provider");
        final IllegalConfigurationException unknownProvider =
                assertThrows(
                        IllegalConfigurationException.class,
                        () -> SSLUtils.getSSLProvider(configuration));
        assertTrue(unknownProvider.getMessage().contains("Unknown SSL provider"));
        assertTrue(unknownProvider.getMessage().contains("not-a-provider"));
    }

    @Test
    void disabledSslRejectsAllPublicFactoryMethods() {
