        assertThrows(
                IllegalConfigurationException.class,
                () -> SSLUtils.createSSLServerSocketFactory(disabled));
        assertThrows(
                IllegalConfigurationException.class,
                () -> SSLUtils.createSSLClientSocketFactory(disabled));
        assertThrows(
                IllegalConfigurationException.class,
                () -> SSLUtils.createInternalServerSSLEngineFactory(disabled));
        assertThrows(
