    @Test
    void internalServerSocketFactoryConfiguresProtocolsCipherSuitesAndClientAuth()
            throws Exception {
        final Configuration configuration = internalSslConfiguration();
        configuration.set(SecurityOptions.SSL_PROTOCOL, TEST_PROTOCOL);
        configuration.set(SecurityOptions.SSL_ALGORITHMS, TEST_CIPHER);

        final ServerSocketFactory factory = SSLUtils.createSSLServerSocketFactory(configuration);
        try (ServerSocket serverSocket =
                factory.createServerSocket(0, 1, InetAddress.getLoopbackAddress())) {
            assertTrue(serverSocket instanceof SSLServerSocket);
            final SSLServerSocket sslServerSocket = (SSLServerSocket) serverSocket;

            assertArrayEquals(new String[] {TEST_PROTOCOL}, sslServerSocket.getEnabledProtocols());
            assertArrayEquals(new String[] {TEST_CIPHER}, sslServerSocket.getEnabledCipherSuites());
            assertTrue(sslServerSocket.getNeedClientAuth());
        }
    }

    @Test
    void internalHandlerFactoriesConfigureEngineModeAndTimeouts() throws Exception {
        final Configuration configuration = internalSslConfiguration();
        configuration.set(SecurityOptions.SSL_PROTOCOL, TEST_PROTOCOL);
        configuration.set(SecurityOptions.SSL_ALGORITHMS, TEST_CIPHER);
        configuration.set(SecurityOptions.SSL_INTERNAL_HANDSHAKE_TIMEOUT, 3_210);
        configuration.set(SecurityOptions.SSL_INTERNAL_CLOSE_NOTIFY_FLUSH_TIMEOUT, 6_543);

        final SSLHandlerFactory serverFactory =
                SSLUtils.createInternalServerSSLEngineFactory(configuration);
        final SSLHandlerFactory clientFactory =
                SSLUtils.createInternalClientSSLEngineFactory(configuration);

        final SslHandler serverHandler =
                serverFactory.createNettySSLHandler(UnpooledByteBufAllocator.DEFAULT);
        final SslHandler clientHandler =
                clientFactory.createNettySSLHandler(
                        UnpooledByteBufAllocator.DEFAULT, "localhost", 1234);

        assertFalse(serverHandler.engine().getUseClientMode());
        assertTrue(clientHandler.engine().getUseClientMode());
        assertArrayEquals(
                new String[] {TEST_PROTOCOL}, serverHandler.engine().getEnabledProtocols());
        assertArrayEquals(
                new String[] {TEST_CIPHER}, serverHandler.engine().getEnabledCipherSuites());
        assertEquals(3_210L, serverHandler.getHandshakeTimeoutMillis());
        assertEquals(6_543L, serverHandler.getCloseNotifyFlushTimeoutMillis());
        assertEquals(3_210L, clientHandler.getHandshakeTimeoutMillis());
        assertEquals(6_543L, clientHandler.getCloseNotifyFlushTimeoutMillis());
    }

    @Test
    void internalClientAndServerSocketFactoriesCompleteMutualTlsHandshake() throws Exception {
        final Configuration configuration = internalSslConfiguration();
        configuration.set(SecurityOptions.SSL_PROTOCOL, TEST_PROTOCOL);
        configuration.set(SecurityOptions.SSL_ALGORITHMS, TEST_CIPHER);

        final ServerSocketFactory serverSocketFactory =
                SSLUtils.createSSLServerSocketFactory(configuration);
        final SocketFactory clientSocketFactory =
                SSLUtils.createSSLClientSocketFactory(configuration);

        final ExecutorService executor = Executors.newSingleThreadExecutor();
        try (ServerSocket serverSocket =
                serverSocketFactory.createServerSocket(0, 1, InetAddress.getLoopbackAddress())) {
            final Future<Principal> serverPeer =
                    executor.submit(
                            () -> {
                                try (SSLSocket socket = (SSLSocket) serverSocket.accept()) {
                                    socket.setSoTimeout(5_000);
                                    socket.startHandshake();
                                    return socket.getSession().getPeerPrincipal();
                                }
                            });

            try (Socket socket =
                    clientSocketFactory.createSocket(
                            InetAddress.getLoopbackAddress(), serverSocket.getLocalPort())) {
                socket.setSoTimeout(5_000);
                final SSLSocket sslSocket = (SSLSocket) socket;
                sslSocket.startHandshake();
                assertNotNull(sslSocket.getSession().getPeerPrincipal());
            }

            assertNotNull(serverPeer.get(10, TimeUnit.SECONDS));
        } finally {
            executor.shutdownNow();
        }
    }

    @Test
