        final SslContext serverContext =
                SSLUtils.createRestNettySSLContext(
                        configuration, false, ClientAuth.NONE, SslProvider.JDK);
        final SslContext clientContext =
                SSLUtils.createRestNettySSLContext(
                        configuration, true, ClientAuth.NONE, SslProvider.JDK);
        final SslContext mutualServerContext =
                SSLUtils.createRestNettySSLContext(
                        configuration, false, ClientAuth.REQUIRE, SslProvider.JDK);

        assertFalse(serverContext.newEngine(UnpooledByteBufAllocator.DEFAULT).getUseClientMode());
        assertFalse(serverContext.newEngine(UnpooledByteBufAllocator.DEFAULT).getNeedClientAuth());
        assertTrue(clientContext.newEngine(UnpooledByteBufAllocator.DEFAULT).getUseClientMode());
        assertTrue(
                mutualServerContext
                        .newEngine(UnpooledByteBufAllocator.DEFAULT)
                        .getNeedClientAuth());

        assertNotNull(SSLUtils.createRestSSLContext(configuration, false));
        assertNotNull(SSLUtils.createRestSSLContext(configuration, true));
        assertNotNull(SSLUtils.createRestServerSSLEngineFactory(configuration));
        assertNotNull(SSLUtils.createRestClientSSLEngineFactory(configuration));
    }

