    @Test
    void testAddJobManagerMetric() {
        final MetricStore store = new MetricStore();
        store.add(new MetricDump.CounterDump(jmScope(""), "numRestarts", 7L));

        assertEquals("7", store.getJobManagerMetricStore().getMetric("numRestarts"));
    }

    @Test
    void testAddJobManagerMetricConcatenatesScopeAndName() {
        final MetricStore store = new MetricStore();
        store.add(new MetricDump.GaugeDump(jmScope("Status.JVM"), "Memory", "123"));

        assertEquals("123", store.getJobManagerMetricStore().getMetric("Status.JVM.Memory"));
    }

    @Test
    void testAddTaskManagerMetric() {
        final MetricStore store = new MetricStore();
        store.add(
                new MetricDump.GaugeDump(
                        new QueryScopeInfo.TaskManagerQueryScopeInfo("tm-1"), "Memory", "42"));

        final TaskManagerMetricStore tmStore = store.getTaskManagerMetricStore("tm-1");
        assertNotNull(tmStore);
        assertEquals("42", tmStore.getMetric("Memory"));
        assertTrue(tmStore.garbageCollectorNames.isEmpty());
    }

    @Test
    void testAddTaskManagerMetricExtractsGarbageCollectorName() {
        final MetricStore store = new MetricStore();
        final String scope = "Status.JVM.GarbageCollector.G1 Young Generation";
        store.add(
                new MetricDump.GaugeDump(
                        new QueryScopeInfo.TaskManagerQueryScopeInfo("tm-1", scope), "Count", "3"));

        final TaskManagerMetricStore tmStore = store.getTaskManagerMetricStore("tm-1");
        assertNotNull(tmStore);
        assertEquals("3", tmStore.getMetric(scope + ".Count"));
        assertEquals(Collections.singleton("G1 Young Generation"), tmStore.garbageCollectorNames);
    }

    @Test
    void testAddJobMetric() {
        final MetricStore store = new MetricStore();
        store.add(
                new MetricDump.CounterDump(new QueryScopeInfo.JobQueryScopeInfo(JOB_ID), "n", 5L));

        final ComponentMetricStore jobStore = store.getJobMetricStore(JOB_ID);
        assertNotNull(jobStore);
        assertEquals("5", jobStore.getMetric("n"));
