    @Test
    void testAddJobMetricConcatenatesScopeAndName() {
        final MetricStore store = new MetricStore();
        store.add(
                new MetricDump.GaugeDump(
                        new QueryScopeInfo.JobQueryScopeInfo(JOB_ID, "custom"), "g", "value"));

