    @Test
    void testAddTaskMetricIsDuplicatedIntoSubtaskAndTaskStores() {
        final MetricStore store = new MetricStore();
        store.add(
                new MetricDump.CounterDump(
                        new QueryScopeInfo.TaskQueryScopeInfo(JOB_ID, VERTEX_ID, 2, 0),
                        "records",
                        11L));

        final TaskMetricStore taskStore = store.getTaskMetricStore(JOB_ID, VERTEX_ID);
        assertNotNull(taskStore);

        // stored for the attempt
        assertEquals(
                "11",
                store.getJobs()
                        .getSubtaskAttemptMetricStore(JOB_ID, VERTEX_ID, 2, 0)
                        .getMetric("records"));
        // stored for the subtask
        assertEquals("11", taskStore.getSubtaskMetricStore(2).getMetric("records"));
        // stored for the task, prefixed with the subtask index
        assertEquals("11", taskStore.getMetric("2.records"));
    }

    @Test
    void testAddTaskMetricOnlyUsesRepresentativeAttemptForSubtaskAndTaskStores() {
        final MetricStore store = new MetricStore();
        store.updateCurrentExecutionAttempts(
                Collections.singletonList(
                        jobDetails(JOB_ID, currentAttempts(VERTEX_ID, 0, 2, setOf(1, 2), false))));

        store.add(
                new MetricDump.CounterDump(
                        new QueryScopeInfo.TaskQueryScopeInfo(JOB_ID, VERTEX_ID, 0, 1),
                        "stale",
                        1L));
        store.add(
                new MetricDump.CounterDump(
                        new QueryScopeInfo.TaskQueryScopeInfo(JOB_ID, VERTEX_ID, 0, 2),
                        "current",
                        2L));

        final TaskMetricStore taskStore = store.getTaskMetricStore(JOB_ID, VERTEX_ID);
        assertEquals(
                "1",
                store.getJobs()
                        .getSubtaskAttemptMetricStore(JOB_ID, VERTEX_ID, 0, 1)
                        .getMetric("stale"));
        assertNull(taskStore.getSubtaskMetricStore(0).getMetric("stale"));
        assertNull(taskStore.getMetric("0.stale"));

        assertEquals(
                "2",
                store.getJobs()
                        .getSubtaskAttemptMetricStore(JOB_ID, VERTEX_ID, 0, 2)
                        .getMetric("current"));
        assertEquals("2", taskStore.getSubtaskMetricStore(0).getMetric("current"));
        assertEquals("2", taskStore.getMetric("0.current"));
    }

    @Test
    void testAddOperatorMetricIsDuplicatedForRepresentativeAttempt() {
        final MetricStore store = new MetricStore();
        store.add(
                new MetricDump.GaugeDump(
                        new QueryScopeInfo.OperatorQueryScopeInfo(JOB_ID, VERTEX_ID, 1, 0, "opA"),
                        "numRecordsOut",
                        "9"));

        final TaskMetricStore taskStore = store.getTaskMetricStore(JOB_ID, VERTEX_ID);
        assertEquals(
                "9",
                store.getJobs()
                        .getSubtaskAttemptMetricStore(JOB_ID, VERTEX_ID, 1, 0)
                        .getMetric("opA.numRecordsOut"));
        assertEquals("9", taskStore.getSubtaskMetricStore(1).getMetric("opA.numRecordsOut"));
        assertEquals("9", taskStore.getMetric("1.opA.numRecordsOut"));
    }

    @Test
    void testAddOperatorMetricOnlyUsesRepresentativeAttemptForSubtaskAndTaskStores() {
        final MetricStore store = new MetricStore();
        store.updateCurrentExecutionAttempts(
                Collections.singletonList(
                        jobDetails(JOB_ID, currentAttempts(VERTEX_ID, 0, 1, setOf(0, 1), false))));

        store.add(
                new MetricDump.GaugeDump(
                        new QueryScopeInfo.OperatorQueryScopeInfo(JOB_ID, VERTEX_ID, 0, 0, "opA"),
                        "metric",
                        "stale"));
        store.add(
                new MetricDump.GaugeDump(
                        new QueryScopeInfo.OperatorQueryScopeInfo(JOB_ID, VERTEX_ID, 0, 1, "opA"),
                        "metric",
                        "current"));

        final TaskMetricStore taskStore = store.getTaskMetricStore(JOB_ID, VERTEX_ID);
        assertEquals(
                "stale",
                store.getJobs()
                        .getSubtaskAttemptMetricStore(JOB_ID, VERTEX_ID, 0, 0)
                        .getMetric("opA.metric"));
        assertEquals(
                "current",
                store.getJobs()
                        .getSubtaskAttemptMetricStore(JOB_ID, VERTEX_ID, 0, 1)
                        .getMetric("opA.metric"));
        assertEquals("current", taskStore.getSubtaskMetricStore(0).getMetric("opA.metric"));
        assertEquals("current", taskStore.getMetric("0.opA.metric"));
    }

