    @Test
    void testHistogramMetricExpandsToPercentileKeys() {
        final MetricStore store = new MetricStore();
        store.add(
                new MetricDump.HistogramDump(
                        jmScope(""), "hist", 1L, 10L, 2.5, 3.5, 0.5, 4.0, 5.0, 6.0, 7.0, 8.0, 9.0));

        final ComponentMetricStore jmStore = store.getJobManagerMetricStore();
        assertEquals("1", jmStore.getMetric("hist_min"));
        assertEquals("10", jmStore.getMetric("hist_max"));
        assertEquals("2.5", jmStore.getMetric("hist_mean"));
        assertEquals("3.5", jmStore.getMetric("hist_median"));
        assertEquals("0.5", jmStore.getMetric("hist_stddev"));
        assertEquals("4.0", jmStore.getMetric("hist_p75"));
        assertEquals("5.0", jmStore.getMetric("hist_p90"));
        assertEquals("6.0", jmStore.getMetric("hist_p95"));
        assertEquals("7.0", jmStore.getMetric("hist_p98"));
        assertEquals("8.0", jmStore.getMetric("hist_p99"));
        assertEquals("9.0", jmStore.getMetric("hist_p999"));
    }

