    @Test
    void testComponentMetricStoreReturnsDefaultValue() {
        final MetricStore store = new MetricStore();
        store.add(new MetricDump.GaugeDump(jmScope(""), "present", "value"));

        final ComponentMetricStore jmStore = store.getJobManagerMetricStore();
        assertEquals("value", jmStore.getMetric("present"));
        assertEquals("value", jmStore.getMetric("present", "fallback"));
        assertNull(jmStore.getMetric("absent"));
        assertEquals("fallback", jmStore.getMetric("absent", "fallback"));
    }

    @Test
    void testAccessorsReturnNullForNullOrUnknownIdentifiers() {
        final MetricStore store = new MetricStore();

        assertNull(store.getTaskManagerMetricStore(null));
        assertNull(store.getTaskManagerMetricStore("unknown"));
        assertNull(store.getJobMetricStore(null));
        assertNull(store.getJobMetricStore("unknown"));
        assertNull(store.getTaskMetricStore(null, VERTEX_ID));
        assertNull(store.getTaskMetricStore(JOB_ID, null));
        assertNull(store.getTaskMetricStore(JOB_ID, VERTEX_ID));
        assertNull(store.getJobManagerOperatorMetricStore(null, VERTEX_ID));
        assertNull(store.getJobManagerOperatorMetricStore(JOB_ID, null));
        assertNull(store.getJobManagerOperatorMetricStore(JOB_ID, VERTEX_ID));

        final JobMetricStoreSnapshot snapshot = store.getJobs();
        assertNull(snapshot.getSubtaskMetricStore(null, VERTEX_ID, 0));
        assertNull(snapshot.getSubtaskMetricStore(JOB_ID, null, 0));
        assertNull(snapshot.getSubtaskMetricStore(JOB_ID, VERTEX_ID, 0));
        assertNull(snapshot.getSubtaskAttemptMetricStore(JOB_ID, VERTEX_ID, 0, 0));
        assertTrue(snapshot.values().isEmpty());
    }

    @Test
    void testAccessorsReturnUnmodifiableViews() {
        final MetricStore store = new MetricStore();
        store.add(new MetricDump.GaugeDump(jmScope(""), "jm", "v"));
        store.add(
                new MetricDump.GaugeDump(
                        new QueryScopeInfo.TaskManagerQueryScopeInfo("tm-1"), "tm", "v"));
        store.add(
                new MetricDump.GaugeDump(new QueryScopeInfo.JobQueryScopeInfo(JOB_ID), "job", "v"));

        assertThrows(
                UnsupportedOperationException.class,
                () -> store.getJobManagerMetricStore().metrics.put("x", "y"));
        assertThrows(
                UnsupportedOperationException.class,
                () -> store.getTaskManagerMetricStore("tm-1").metrics.put("x", "y"));
        assertThrows(
                UnsupportedOperationException.class,
                () -> store.getJobMetricStore(JOB_ID).metrics.put("x", "y"));
    }

    // ---------------------------------------------------------------------
