    @Test
    void testJobSnapshotExposesSubtaskAndAttemptMetrics() {
        final MetricStore store = new MetricStore();
        store.add(
                new MetricDump.GaugeDump(
                        new QueryScopeInfo.TaskQueryScopeInfo(JOB_ID, VERTEX_ID, 0, 0), "m", "v"));

        final JobMetricStoreSnapshot snapshot = store.getJobs();
        assertEquals(1, snapshot.values().size());

        final ComponentMetricStore subtaskStore =
                snapshot.getSubtaskMetricStore(JOB_ID, VERTEX_ID, 0);
        assertNotNull(subtaskStore);
        assertEquals("v", subtaskStore.getMetric("m"));
        assertThrows(UnsupportedOperationException.class, () -> subtaskStore.metrics.put("x", "y"));

        final ComponentMetricStore attemptStore =
                snapshot.getSubtaskAttemptMetricStore(JOB_ID, VERTEX_ID, 0, 0);
        assertNotNull(attemptStore);
        assertEquals("v", attemptStore.getMetric("m"));
    }

    @Test
    void testTaskStoreExposesAllSubtaskAndAttemptStores() {
        final MetricStore store = new MetricStore();
        store.add(
                new MetricDump.GaugeDump(
                        new QueryScopeInfo.TaskQueryScopeInfo(JOB_ID, VERTEX_ID, 0, 0),
                        "m0",
                        "v0"));
        store.add(
                new MetricDump.GaugeDump(
                        new QueryScopeInfo.TaskQueryScopeInfo(JOB_ID, VERTEX_ID, 1, 0),
                        "m1",
                        "v1"));

        final TaskMetricStore taskStore = store.getTaskMetricStore(JOB_ID, VERTEX_ID);
        assertEquals(2, taskStore.getAllSubtaskMetricStores().size());
        assertEquals(1, taskStore.getSubtaskMetricStore(0).getAllAttemptsMetricStores().size());
        assertThrows(
                UnsupportedOperationException.class,
                () -> taskStore.getAllSubtaskMetricStores().put(2, null));
    }

