    @Test
    void testRetainTaskManagersRemovesInactiveOnes() {
        final MetricStore store = new MetricStore();
        store.add(
                new MetricDump.GaugeDump(
                        new QueryScopeInfo.TaskManagerQueryScopeInfo("tm-1"), "m", "1"));
        store.add(
                new MetricDump.GaugeDump(
                        new QueryScopeInfo.TaskManagerQueryScopeInfo("tm-2"), "m", "2"));

        store.retainTaskManagers(Collections.singletonList("tm-1"));

        assertNotNull(store.getTaskManagerMetricStore("tm-1"));
        assertNull(store.getTaskManagerMetricStore("tm-2"));
        assertEquals(Collections.singleton("tm-1"), store.getTaskManagers().keySet());
    }

    @Test
    void testRetainJobsRemovesInactiveJobsAndRepresentativeAttempts() {
        final MetricStore store = new MetricStore();
        final JobID activeJob = new JobID(0L, 1L);
        final JobID inactiveJob = new JobID(0L, 2L);

        store.add(
                new MetricDump.GaugeDump(
                        new QueryScopeInfo.JobQueryScopeInfo(activeJob.toString()), "m", "1"));
        store.add(
                new MetricDump.GaugeDump(
                        new QueryScopeInfo.JobQueryScopeInfo(inactiveJob.toString()), "m", "2"));

        store.updateCurrentExecutionAttempts(
                Arrays.asList(
                        jobDetails(
                                activeJob.toString(), currentAttempts("v", 0, 0, setOf(0), false)),
                        jobDetails(
                                inactiveJob.toString(),
                                currentAttempts("v", 0, 0, setOf(0), false))));
        assertEquals(2, store.getRepresentativeAttempts().size());

        store.retainJobs(Collections.singletonList(activeJob.toString()));

        assertNotNull(store.getJobMetricStore(activeJob.toString()));
        assertNull(store.getJobMetricStore(inactiveJob.toString()));
        assertTrue(store.getRepresentativeAttempts().containsKey(activeJob.toString()));
        assertFalse(store.getRepresentativeAttempts().containsKey(inactiveJob.toString()));
    }

