/** Tests for the {@link VoidMetricFetcher}. */
class VoidMetricFetcherTest {

    @Test
    void testInstanceIsSingleton() {
        assertSame(VoidMetricFetcher.INSTANCE, VoidMetricFetcher.valueOf("INSTANCE"));
    }

    @Test
    void testGetMetricStoreReturnsSharedEmptyStore() {
        final MetricFetcher fetcher = VoidMetricFetcher.INSTANCE;

        final MetricStore first = fetcher.getMetricStore();
