        assertTrue(first.getJobs().values().isEmpty());
        assertTrue(first.getTaskManagers().isEmpty());
        assertTrue(first.getJobManagerMetricStore().metrics.isEmpty());
    }

    @Test
    void testUpdateIsNoOp() {
        final MetricFetcher fetcher = VoidMetricFetcher.INSTANCE;
        final MetricStore storeBefore = fetcher.getMetricStore();

        fetcher.update();

        assertSame(storeBefore, fetcher.getMetricStore());
        assertEquals(0L, fetcher.getLastUpdateTime());
        assertTrue(fetcher.getMetricStore().getJobs().values().isEmpty());
