/** Tests for {@link KeySelectorUtil}. */
class KeySelectorUtilTest {

    @Test
    void testSelectorForTupleKeysReturnsFieldsInRequestedOrder() throws Exception {
        TypeInformation<Tuple2<String, Integer>> typeInfo = Types.TUPLE(Types.STRING, Types.INT);
        Keys<Tuple2<String, Integer>> keys = new Keys.ExpressionKeys<>(new int[] {1, 0}, typeInfo);

        KeySelector<Tuple2<String, Integer>, Tuple> selector =
                KeySelectorUtil.getSelectorForKeys(keys, typeInfo, new ExecutionConfig());

        Tuple key = selector.getKey(Tuple2.of("value", 42));
        assertEquals(2, key.getArity());
        assertEquals(Integer.valueOf(42), key.getField(0));
        assertEquals("value", key.getField(1));
        TupleTypeInfo<Tuple> producedType =
                (TupleTypeInfo<Tuple>) ((ResultTypeQueryable<Tuple>) selector).getProducedType();
        assertEquals(Types.INT, producedType.getTypeAt(0));
        assertEquals(Types.STRING, producedType.getTypeAt(1));
    }

    @Test
    void testSelectorForTupleKeysSupportsPojoKeyTypes() throws Exception {
        TypeInformation<HashablePojo> pojoType = Types.POJO(HashablePojo.class);
        TypeInformation<Tuple2<Integer, HashablePojo>> typeInfo = Types.TUPLE(Types.INT, pojoType);
        Keys<Tuple2<Integer, HashablePojo>> keys =
                new Keys.ExpressionKeys<>(new int[] {1}, typeInfo);

        KeySelector<Tuple2<Integer, HashablePojo>, Tuple> selector =
                KeySelectorUtil.getSelectorForKeys(keys, typeInfo, new ExecutionConfig());

        HashablePojo pojo = new HashablePojo(7);
        Tuple key = selector.getKey(Tuple2.of(1, pojo));
        assertEquals(1, key.getArity());
        assertEquals(Integer.valueOf(7), key.getField(0));
    }

    @Test
    void testSelectorForKeysRejectsNonCompositeType() {
        TypeInformation<String> typeInfo = Types.STRING;
        Keys<String> keys = new Keys.ExpressionKeys<>(typeInfo);

        assertThrows(
                InvalidTypesException.class,
                () -> KeySelectorUtil.getSelectorForKeys(keys, typeInfo, new ExecutionConfig()));
    }

    @Test
    void testSelectorForOneKeyExtractsSingleField() throws Exception {
        TypeInformation<Tuple2<String, Integer>> typeInfo = Types.TUPLE(Types.STRING, Types.INT);
        Keys<Tuple2<String, Integer>> keys = new Keys.ExpressionKeys<>(new int[] {1}, typeInfo);

        KeySelector<Tuple2<String, Integer>, Integer> selector =
                KeySelectorUtil.getSelectorForOneKey(
                        keys, new IntegerPartitioner(), typeInfo, new ExecutionConfig());

        assertEquals(Integer.valueOf(17), selector.getKey(Tuple2.of("ignored", 17)));
    }

    @Test
    void testSelectorForOneKeyRejectsMultipleFields() {
        TypeInformation<Tuple2<String, Integer>> typeInfo = Types.TUPLE(Types.STRING, Types.INT);
        Keys<Tuple2<String, Integer>> keys = new Keys.ExpressionKeys<>(new int[] {0, 1}, typeInfo);

        assertThrows(
