        TupleTypeInfo<Tuple> producedType =
                (TupleTypeInfo<Tuple>) ((ResultTypeQueryable<Tuple>) selector).getProducedType();
        assertEquals(Types.INT, producedType.getTypeAt(0));
        assertEquals(Types.INT, producedType.getTypeAt(1));
    }

    @Test
    void testSelectorForBoxedArrayUsesComponentTypeInformation() throws Exception {
