    @SuppressWarnings("unchecked")
    private static <T> T roundTrip(T value) throws Exception {
        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        try (ObjectOutputStream output = new ObjectOutputStream(bytes)) {
            output.writeObject(value);
        }
        try (ObjectInputStream input =
                new ObjectInputStream(new ByteArrayInputStream(bytes.toByteArray()))) {
            return (T) input.readObject();
        }
    }

    private enum TestEnum {
        FIRST,
        SECOND
    }

    public static class HashablePojo {
        public int value;

        public HashablePojo() {}

        public HashablePojo(int value) {
            this.value = value;
        }

        @Override
        public int hashCode() {
            return value;
        }

        @Override
        public boolean equals(Object other) {
            return other instanceof HashablePojo && ((HashablePojo) other).value == value;
        }
    }

    public static class NonHashablePojo {
        public int value;
    }

    private static final class IntegerPartitioner implements Partitioner<Integer> {
        @Override
        public int partition(Integer key, int numPartitions) {
            return Math.floorMod(key, numPartitions);
        }
    }

    private static final class StringPartitioner implements Partitioner<String> {
        @Override
        public int partition(String key, int numPartitions) {
            return Math.floorMod(key.hashCode(), numPartitions);
        }
    }
