/** Tests for {@link RemoteEnvironmentConfigUtils}. */
class RemoteEnvironmentConfigUtilsTest {

    @TempDir private Path tempDirectory;

    @AfterEach
    void restoreExplicitEnvironmentContext() {
        TestEnvironmentContext.resetContext();
    }

    @Test
    void testValidateAcceptsValidPortBoundaries() {
        assertDoesNotThrow(() -> RemoteEnvironmentConfigUtils.validate("localhost", 1));
        assertDoesNotThrow(() -> RemoteEnvironmentConfigUtils.validate("localhost", 0xfffe));
    }

    @Test
    void testValidateRejectsInvalidPorts() {
        for (int port : new int[] {-1, 0, 0xffff, 0x10000}) {
            assertThrows(
                    IllegalArgumentException.class,
                    () -> RemoteEnvironmentConfigUtils.validate("localhost", port),
                    "Port should be rejected: " + port);
        }
    }

    @Test
    void testValidateRejectsNullHost() {
        assertThrows(
                NullPointerException.class,
                () -> RemoteEnvironmentConfigUtils.validate(null, 8081));
    }

    @Test
    void testValidateRejectsExplicitEnvironmentInPredefinedContext() {
        TestEnvironmentContext.installContextEnvironment();

        InvalidProgramException exception =
                assertThrows(
                        InvalidProgramException.class,
                        () -> RemoteEnvironmentConfigUtils.validate(null, -1));

        assertTrue(exception.getMessage().contains("pre-defined context"));
    }

    @Test
    void testSetJobManagerAddressPropagatesToJobManagerAndRestOptions() {
        Configuration configuration = new Configuration();

        RemoteEnvironmentConfigUtils.setJobManagerAddressToConfig("127.0.0.1", 6123, configuration);

        assertEquals("127.0.0.1", configuration.get(JobManagerOptions.ADDRESS));
        assertEquals(6123, configuration.get(JobManagerOptions.PORT));
        assertEquals("127.0.0.1", configuration.get(RestOptions.ADDRESS));
        assertEquals(6123, configuration.get(RestOptions.PORT));
    }

    @Test
    void testSetJobManagerAddressOverridesPreviousValues() {
        Configuration configuration = new Configuration();
        configuration.set(JobManagerOptions.ADDRESS, "old-host");
        configuration.set(JobManagerOptions.PORT, 1111);
        configuration.set(RestOptions.ADDRESS, "old-rest-host");
        configuration.set(RestOptions.PORT, 2222);

        RemoteEnvironmentConfigUtils.setJobManagerAddressToConfig("127.0.0.1", 9876, configuration);

        assertEquals("127.0.0.1", configuration.get(JobManagerOptions.ADDRESS));
        assertEquals(9876, configuration.get(JobManagerOptions.PORT));
        assertEquals("127.0.0.1", configuration.get(RestOptions.ADDRESS));
        assertEquals(9876, configuration.get(RestOptions.PORT));
    }

    @Test
    void testSetJarUrlsLeavesConfigurationUntouchedForNullAndEmptyInput() {
        Configuration nullConfiguration = new Configuration();
        RemoteEnvironmentConfigUtils.setJarURLsToConfig(null, nullConfiguration);
        assertFalse(nullConfiguration.toMap().containsKey(PipelineOptions.JARS.key()));

        Configuration emptyConfiguration = new Configuration();
        RemoteEnvironmentConfigUtils.setJarURLsToConfig(new String[0], emptyConfiguration);
        assertFalse(emptyConfiguration.toMap().containsKey(PipelineOptions.JARS.key()));
    }

    @Test
    void testSetJarUrlsStoresAbsoluteFileUrlsInInputOrder() throws Exception {
        Path firstJar = createJar("first.jar");
        Path secondJar = createJar("second.jar");
        Configuration configuration = new Configuration();

        RemoteEnvironmentConfigUtils.setJarURLsToConfig(
                new String[] {firstJar.toString(), secondJar.toString()}, configuration);

        List<String> expected =
                Arrays.asList(
                        firstJar.toFile().getAbsoluteFile().toURI().toURL().toString(),
                        secondJar.toFile().getAbsoluteFile().toURI().toURL().toString());
        assertEquals(expected, configuration.get(PipelineOptions.JARS));
    }

    @Test
    void testSetJarUrlsRejectsMissingFile() {
        Path missingJar = tempDirectory.resolve("missing.jar");
        Configuration configuration = new Configuration();

        RuntimeException exception =
                assertThrows(
                        RuntimeException.class,
                        () ->
                                RemoteEnvironmentConfigUtils.setJarURLsToConfig(
                                        new String[] {missingJar.toString()}, configuration));

        assertTrue(exception.getMessage().contains("Problem with jar file"));
        assertTrue(exception.getCause() instanceof IOException);
        assertFalse(configuration.toMap().containsKey(PipelineOptions.JARS.key()));
    }

    @Test
    void testSetJarUrlsRejectsFileThatIsNotAJar() throws Exception {
        Path notAJar = Files.createFile(tempDirectory.resolve("not-a-jar.txt"));
        Files.write(notAJar, "plain text".getBytes());
        Configuration configuration = new Configuration();

        RuntimeException exception =
                assertThrows(
                        RuntimeException.class,
                        () ->
                                RemoteEnvironmentConfigUtils.setJarURLsToConfig(
                                        new String[] {notAJar.toString()}, configuration));

        assertTrue(exception.getMessage().contains("Problem with jar file"));
        assertTrue(exception.getCause() instanceof IOException);
    }

    private Path createJar(String name) throws IOException {
        Path jar = tempDirectory.resolve(name);
        try (OutputStream outputStream = Files.newOutputStream(jar);
                JarOutputStream jarOutputStream = new JarOutputStream(outputStream)) {
            jarOutputStream.putNextEntry(new JarEntry("entry.txt"));
            jarOutputStream.write("content".getBytes());
            jarOutputStream.closeEntry();
        }
        return jar;
    }

    /** Subclass used to access the protected static context-environment controls. */
    private static final class TestEnvironmentContext extends StreamExecutionEnvironment {

        private static void installContextEnvironment() {
            initializeContextEnvironment(
                    configuration -> new StreamExecutionEnvironment(configuration));
        }

        private static void resetContext() {
            resetContextEnvironment();
        }
    }
}
