        KeySelector<Tuple2<String, Integer>, Tuple> selector =
                KeySelectorUtil.getSelectorForKeys(keys, typeInfo, new ExecutionConfig());

        Tuple key = selector.getKey(Tuple2.of("value", 42));
        assertEquals(2, key.getArity());
