        TypeInformation<int[]> typeInfo = (TypeInformation<int[]>) Types.PRIMITIVE_ARRAY(Types.INT);
        KeySelector<int[], Tuple> selector =
                KeySelectorUtil.getSelectorForArray(new int[] {2, 0}, typeInfo);

        Tuple key = selector.getKey(new int[] {10, 20, 30});
        assertEquals(Integer.valueOf(30), key.getField(0));
        assertEquals(Integer.valueOf(10), key.getField(1));
        TupleTypeInfo<Tuple> producedType =
                (TupleTypeInfo<Tuple>) ((ResultTypeQueryable<Tuple>) selector).getProducedType();
        assertEquals(Types.INT, producedType.getTypeAt(0));
        assertEquals(Types.INT, producedType.getTypeAt(1));
