    @Test
    void testSelectorForArrayAcceptsMaximumNumberOfPositions() throws Exception {
        int[] positions = new int[Tuple.MAX_ARITY];
        int[] values = new int[Tuple.MAX_ARITY];
        for (int i = 0; i < Tuple.MAX_ARITY; i++) {
            positions[i] = i;
            values[i] = i * 2;
        }
        @SuppressWarnings("unchecked")
        TypeInformation<int[]> typeInfo = (TypeInformation<int[]>) Types.PRIMITIVE_ARRAY(Types.INT);

        KeySelector<int[], Tuple> selector =
                KeySelectorUtil.getSelectorForArray(positions, typeInfo);

        Tuple key = selector.getKey(values);
        assertEquals(Tuple.MAX_ARITY, key.getArity());
        assertEquals(Integer.valueOf(values[0]), key.getField(0));
        assertEquals(
                Integer.valueOf(values[Tuple.MAX_ARITY - 1]), key.getField(Tuple.MAX_ARITY - 1));
    }

