    @Test
    void testSerializedSelectorDoesNotExposeTransientTypeInformation() throws Exception {
        TypeInformation<Tuple2<String, Integer>> typeInfo = Types.TUPLE(Types.STRING, Types.INT);
        Keys<Tuple2<String, Integer>> keys = new Keys.ExpressionKeys<>(new int[] {1}, typeInfo);
        @SuppressWarnings("unchecked")
        KeySelectorUtil.ComparableKeySelector<Tuple2<String, Integer>> selector =
                (KeySelectorUtil.ComparableKeySelector<Tuple2<String, Integer>>)
                        KeySelectorUtil.getSelectorForKeys(keys, typeInfo, new ExecutionConfig());

        KeySelectorUtil.ComparableKeySelector<Tuple2<String, Integer>> copy = roundTrip(selector);

        assertEquals(Integer.valueOf(23), copy.getKey(Tuple2.of("ignored", 23)).getField(0));
        assertThrows(IllegalStateException.class, copy::getProducedType);
    }

    @Test
    void testValidateKeyTypeAcceptsHashableNestedTypes() {
        TypeInformation<Tuple2<String, HashablePojo>> typeInfo =
                Types.TUPLE(Types.STRING, Types.POJO(HashablePojo.class));

        assertSame(typeInfo, KeySelectorUtil.validateKeyType(typeInfo));
    }

    @Test
    void testValidateKeyTypeRejectsArraysAndEnums() {
        @SuppressWarnings("unchecked")
        TypeInformation<int[]> arrayType =
                (TypeInformation<int[]>) Types.PRIMITIVE_ARRAY(Types.INT);
        TypeInformation<TestEnum> enumType = Types.ENUM(TestEnum.class);

        assertThrows(
                InvalidProgramException.class, () -> KeySelectorUtil.validateKeyType(arrayType));
        assertThrows(
                InvalidProgramException.class, () -> KeySelectorUtil.validateKeyType(enumType));
    }

    @Test
    void testValidateKeyTypeRejectsPojoWithoutHashCode() {
        TypeInformation<NonHashablePojo> typeInfo = Types.POJO(NonHashablePojo.class);

        InvalidProgramException exception =
                assertThrows(
                        InvalidProgramException.class,
                        () -> KeySelectorUtil.validateKeyType(typeInfo));

        assertTrue(exception.getMessage().contains("UNSUPPORTED key types"));
    }

    @Test
    void testValidateKeyTypeRejectsUnsupportedNestedField() {
        @SuppressWarnings({"unchecked", "rawtypes"})
        TypeInformation<Tuple2<String, int[]>> typeInfo =
                (TypeInformation) Types.TUPLE(Types.STRING, Types.PRIMITIVE_ARRAY(Types.INT));

        assertThrows(
                InvalidProgramException.class, () -> KeySelectorUtil.validateKeyType(typeInfo));
    }

    @Test
    void testValidateKeyTypeRejectsArrayOfUnsupportedValues() {
        assertThrows(
                InvalidProgramException.class,
                () -> KeySelectorUtil.validateKeyType(Types.OBJECT_ARRAY(Types.INT)));
    }

    @SuppressWarnings("unchecked")
    private static <T> T roundTrip(T value) throws Exception {
        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        try (ObjectOutputStream output = new ObjectOutputStream(bytes)) {
            output.writeObject(value);
        }
        try (ObjectInputStream input =
                new ObjectInputStream(new ByteArrayInputStream(bytes.toByteArray()))) {
            return (T) input.readObject();
        }
    }

    private enum TestEnum {
        FIRST,
        SECOND
    }

    public static class HashablePojo {
        public int value;

        public HashablePojo() {}

        public HashablePojo(int value) {
            this.value = value;
        }

        @Override
        public int hashCode() {
            return value;
        }

        @Override
        public boolean equals(Object other) {
            return other instanceof HashablePojo && ((HashablePojo) other).value == value;
        }
    }

    public static class NonHashablePojo {
        public int value;
    }

    private static final class IntegerPartitioner implements Partitioner<Integer> {
        @Override
        public int partition(Integer key, int numPartitions) {
            return Math.floorMod(key, numPartitions);
        }
    }

    private static final class StringPartitioner implements Partitioner<String> {
        @Override
        public int partition(String key, int numPartitions) {
            return Math.floorMod(key.hashCode(), numPartitions);
        }
    }
}

