/** Tests for {@link StreamingFunctionUtils}. */
class StreamingFunctionUtilsTest {

    @Test
    void testSetOutputTypeConfiguresWrappedFunction() {
        ConfigurableFunction function = new ConfigurableFunction();
        TypeInformation<String> outputType = Types.STRING;
        ExecutionConfig executionConfig = new ExecutionConfig();

        StreamingFunctionUtils.setOutputType(
                new TestWrappingFunction(new TestWrappingFunction(function)),
                outputType,
                executionConfig);

        assertEquals(1, function.setOutputTypeCalls);
        assertSame(outputType, function.outputType);
        assertSame(executionConfig, function.executionConfig);
    }

    @Test
    void testSetOutputTypeIgnoresFunctionThatDoesNotImplementOutputTypeConfigurable() {
        StreamingFunctionUtils.setOutputType(
                new NoOpFunction(), Types.STRING, new ExecutionConfig());
    }

    @Test
    void testSetOutputTypeRejectsNullArguments() {
        assertThrows(
                NullPointerException.class,
                () ->
                        StreamingFunctionUtils.setOutputType(
                                new NoOpFunction(), null, new ExecutionConfig()));
        assertThrows(
                NullPointerException.class,
                () -> StreamingFunctionUtils.setOutputType(new NoOpFunction(), Types.STRING, null));
    }

    @Test
    void testSnapshotFunctionStateCallsCheckpointedFunction() throws Exception {
        StateSnapshotContext context = new StateSnapshotContextSynchronousImpl(12L, 34L);
        OperatorStateBackend backend = newOperatorStateBackend();
        CheckpointedTestFunction function = new CheckpointedTestFunction();

        StreamingFunctionUtils.snapshotFunctionState(context, backend, function);

        assertEquals(1, function.snapshotCalls);
        assertSame(context, function.snapshotContext);
        assertTrue(backend.getRegisteredStateNames().isEmpty());
    }

    @Test
    void testSnapshotFunctionStateWritesListCheckpointedState() throws Exception {
        StateSnapshotContext context = new StateSnapshotContextSynchronousImpl(12L, 34L);
        OperatorStateBackend backend = newOperatorStateBackend();
        ListCheckpointedTestFunction function = new ListCheckpointedTestFunction();
        function.stateToSnapshot = Arrays.asList("one", "two");

        StreamingFunctionUtils.snapshotFunctionState(
                context, backend, new TestWrappingFunction(function));

        assertEquals(12L, function.snapshotCheckpointId);
        assertEquals(34L, function.snapshotTimestamp);
        assertEquals(Arrays.asList("one", "two"), getRawOperatorState(backend));
    }

    @Test
    void testSnapshotFunctionStateClearsListStateWhenFunctionReturnsNull() throws Exception {
        StateSnapshotContext context = new StateSnapshotContextSynchronousImpl(12L, 34L);
        OperatorStateBackend backend = newOperatorStateBackend();
        ListState<Serializable> state = getRawOperatorStateHandle(backend);
        state.update(Collections.singletonList("old-state"));
        ListCheckpointedTestFunction function = new ListCheckpointedTestFunction();
        function.stateToSnapshot = null;

        StreamingFunctionUtils.snapshotFunctionState(context, backend, function);

        assertTrue(getRawOperatorState(backend).isEmpty());
    }

    @Test
    void testSnapshotFunctionStateDoesNothingForOrdinaryFunction() throws Exception {
        OperatorStateBackend backend = newOperatorStateBackend();

        StreamingFunctionUtils.snapshotFunctionState(
                new StateSnapshotContextSynchronousImpl(1L, 2L), backend, new NoOpFunction());

        assertTrue(backend.getRegisteredStateNames().isEmpty());
    }

    @Test
    void testSnapshotFunctionStateRejectsNullContextAndBackend() {
        Function function = new NoOpFunction();
        StateSnapshotContext context = new StateSnapshotContextSynchronousImpl(1L, 2L);
        OperatorStateBackend backend = newOperatorStateBackend();

        assertThrows(
                NullPointerException.class,
                () -> StreamingFunctionUtils.snapshotFunctionState(null, backend, function));
        assertThrows(
                NullPointerException.class,
                () -> StreamingFunctionUtils.snapshotFunctionState(context, null, function));
    }

    @Test
    void testRestoreFunctionStateInitializesCheckpointedFunction() throws Exception {
        OperatorStateBackend backend = newOperatorStateBackend();
        StateInitializationContext context = newInitializationContext(null, backend);
        CheckpointedTestFunction function = new CheckpointedTestFunction();

        StreamingFunctionUtils.restoreFunctionState(context, new TestWrappingFunction(function));

        assertEquals(1, function.initializeCalls);
        assertSame(context, function.initializationContext);
    }

    @Test
    void testRestoreFunctionStateRestoresListCheckpointedState() throws Exception {
        OperatorStateBackend backend = newOperatorStateBackend();
        getRawOperatorStateHandle(backend).update(Arrays.asList("alpha", "beta"));
        StateInitializationContext context = newInitializationContext(8L, backend);
        ListCheckpointedTestFunction function = new ListCheckpointedTestFunction();

        StreamingFunctionUtils.restoreFunctionState(context, function);

        assertEquals(Arrays.asList("alpha", "beta"), function.restoredState);
    }

    @Test
    void testRestoreFunctionStateDoesNotRestoreListCheckpointedFunctionWithoutRestoredState()
            throws Exception {
        OperatorStateBackend backend = newOperatorStateBackend();
        StateInitializationContext context = newInitializationContext(null, backend);
        ListCheckpointedTestFunction function = new ListCheckpointedTestFunction();

        StreamingFunctionUtils.restoreFunctionState(context, function);

        assertNull(function.restoredState);
        assertTrue(backend.getRegisteredStateNames().isEmpty());
    }

    @Test
    void testRestoreFunctionStateWrapsListCheckpointedRestoreFailure() throws Exception {
        OperatorStateBackend backend = newOperatorStateBackend();
        getRawOperatorStateHandle(backend).update(Collections.singletonList("state"));
        StateInitializationContext context = newInitializationContext(1L, backend);
        ListCheckpointedTestFunction function = new ListCheckpointedTestFunction();
        function.failOnRestore = true;

        Exception exception =
                assertThrows(
                        Exception.class,
                        () -> StreamingFunctionUtils.restoreFunctionState(context, function));

        assertTrue(exception.getMessage().contains("Failed to restore state to function"));
        assertTrue(exception.getCause() instanceof IllegalStateException);
    }

    @Test
    void testRestoreFunctionStateRejectsNullContext() {
        assertThrows(
                NullPointerException.class,
                () ->
                        StreamingFunctionUtils.restoreFunctionState(
                                null, new CheckpointedTestFunction()));
    }

    private static OperatorStateBackend newOperatorStateBackend() {
        return new DefaultOperatorStateBackend(
                new ExecutionConfig(),
                new CloseableRegistry(),
                new HashMap<>(),
                new HashMap<>(),
                new HashMap<>(),
                new HashMap<>(),
                null);
    }

    private static StateInitializationContext newInitializationContext(
            Long restoredCheckpointId, OperatorStateBackend backend) {
        return new StateInitializationContextImpl(
                restoredCheckpointId,
                backend,
                null,
                Collections.emptyList(),
                Collections.emptyList());
    }

    private static ListState<Serializable> getRawOperatorStateHandle(OperatorStateBackend backend)
            throws Exception {
        return backend.getListState(
                new ListStateDescriptor<>(
                        DefaultOperatorStateBackend.DEFAULT_OPERATOR_STATE_NAME,
                        new JavaSerializer<>()));
    }

    private static List<Serializable> getRawOperatorState(OperatorStateBackend backend)
            throws Exception {
        List<Serializable> state = new ArrayList<>();
        for (Serializable value : getRawOperatorStateHandle(backend).get()) {
            state.add(value);
        }
        return state;
    }

    private static final class TestWrappingFunction extends WrappingFunction<Function> {
        private TestWrappingFunction(Function wrappedFunction) {
            super(wrappedFunction);
        }
    }

    private static final class NoOpFunction implements Function {}

    private static final class ConfigurableFunction
            implements Function, OutputTypeConfigurable<String> {
        private TypeInformation<String> outputType;
        private ExecutionConfig executionConfig;
        private int setOutputTypeCalls;

        @Override
        public void setOutputType(
                TypeInformation<String> outTypeInfo, ExecutionConfig executionConfig) {
            this.outputType = outTypeInfo;
            this.executionConfig = executionConfig;
            this.setOutputTypeCalls++;
        }
    }

    private static final class CheckpointedTestFunction implements Function, CheckpointedFunction {
        private int snapshotCalls;
        private int initializeCalls;
        private StateSnapshotContext snapshotContext;
        private StateInitializationContext initializationContext;

        @Override
        public void snapshotState(FunctionSnapshotContext context) {
            snapshotCalls++;
            snapshotContext = (StateSnapshotContext) context;
        }

        @Override
        public void initializeState(FunctionInitializationContext context) {
            initializeCalls++;
            initializationContext = (StateInitializationContext) context;
        }
    }

    @SuppressWarnings("deprecation")
    private static final class ListCheckpointedTestFunction
            implements Function, ListCheckpointed<Serializable> {
        private List<Serializable> stateToSnapshot = Collections.emptyList();
        private List<Serializable> restoredState;
        private long snapshotCheckpointId = -1L;
        private long snapshotTimestamp = -1L;
        private boolean failOnRestore;

        @Override
        public List<Serializable> snapshotState(long checkpointId, long timestamp) {
            snapshotCheckpointId = checkpointId;
            snapshotTimestamp = timestamp;
            return stateToSnapshot;
        }

        @Override
        public void restoreState(List<Serializable> state) {
            if (failOnRestore) {
                throw new IllegalStateException("restore failed");
            }
            restoredState = state;
        }
    }
}

