/** Tests for {@link WatermarkUtils}. */
class WatermarkUtilsTest {

    private static final LongWatermarkDeclaration CUSTOM_LONG_DECLARATION =
            new LongWatermarkDeclaration(
                    "custom-long",
                    new WatermarkCombinationPolicy(
                            WatermarkCombinationFunction.NumericWatermarkCombinationFunction.MIN,
                            true),
                    WatermarkHandlingStrategy.FORWARD);

    private static final BoolWatermarkDeclaration CUSTOM_BOOL_DECLARATION =
            new BoolWatermarkDeclaration(
                    "custom-bool",
                    new WatermarkCombinationPolicy(
                            WatermarkCombinationFunction.BoolWatermarkCombinationFunction.OR, true),
                    WatermarkHandlingStrategy.IGNORE);

    @Test
    void testConvertToInternalWatermarkDeclarationsConvertsSupportedTypes() {
        Set<WatermarkDeclaration> declarations =
                new HashSet<>(Arrays.asList(CUSTOM_LONG_DECLARATION, CUSTOM_BOOL_DECLARATION));

        Set<AbstractInternalWatermarkDeclaration<?>> converted =
                WatermarkUtils.convertToInternalWatermarkDeclarations(declarations);

        assertEquals(2, converted.size());
        AbstractInternalWatermarkDeclaration<?> longDeclaration =
                findDeclaration(converted, "custom-long");
        AbstractInternalWatermarkDeclaration<?> boolDeclaration =
                findDeclaration(converted, "custom-bool");
        assertInstanceOf(InternalLongWatermarkDeclaration.class, longDeclaration);
        assertInstanceOf(InternalBoolWatermarkDeclaration.class, boolDeclaration);
        assertEquals(
                CUSTOM_LONG_DECLARATION.getCombinationPolicy(),
                longDeclaration.getCombinationPolicy());
        assertEquals(
                CUSTOM_BOOL_DECLARATION.getDefaultHandlingStrategy(),
                boolDeclaration.getDefaultHandlingStrategy());
    }

    @Test
    void testConvertToInternalWatermarkDeclarationsRejectsUnknownDeclarationType() {
        WatermarkDeclaration unknown =
                new WatermarkDeclaration() {
                    @Override
                    public String getIdentifier() {
                        return "unknown";
                    }
                };

        assertThrows(
                IllegalArgumentException.class,
                () ->
                        WatermarkUtils.convertToInternalWatermarkDeclarations(
                                Collections.singleton(unknown)));
    }

    @Test
    void testGetDeclarationsFromGraphCombinesProcessAndSourceDeclarations() {
        ProcessFunction processFunction =
                new ProcessFunction() {
                    @Override
                    public Set<? extends WatermarkDeclaration> declareWatermarks() {
                        return Collections.singleton(CUSTOM_LONG_DECLARATION);
                    }
                };
        StreamOperatorFactory<Object> processFactory =
                SimpleOperatorFactory.of(new TestAsyncUdfOperator(processFunction));
        SourceOperatorFactory<Object> sourceFactory =
                new SourceOperatorFactory<>(
                        new TestSource(Collections.singleton(CUSTOM_BOOL_DECLARATION)),
                        WatermarkStrategy.noWatermarks(),
                        true);

        TestStreamGraph graph = new TestStreamGraph();
        graph.addOperatorNode(1, processFactory);
        graph.addOperatorNode(2, sourceFactory);
        graph.addOperatorNode(3, new IgnoredOperatorFactory());

        Set<AbstractInternalWatermarkDeclaration<?>> declarations =
                WatermarkUtils.getInternalWatermarkDeclarationsFromStreamGraph(graph);

        assertEquals(2, declarations.size());
        Set<String> identifiers =
                declarations.stream()
                        .map(AbstractInternalWatermarkDeclaration::getIdentifier)
                        .collect(Collectors.toSet());
        assertEquals(new HashSet<>(Arrays.asList("custom-long", "custom-bool")), identifiers);
    }

    @Test
    void testGetDeclarationsFromGraphIgnoresNonProcessFunctionsAndNodesWithoutFactories() {
        StreamOperatorFactory<Object> factory =
                SimpleOperatorFactory.of(new TestAsyncUdfOperator(new NoOpFunction()));
        TestStreamGraph graph = new TestStreamGraph();
        graph.addOperatorNode(1, factory);
        graph.addOperatorNode(2, null);

        assertTrue(WatermarkUtils.getInternalWatermarkDeclarationsFromStreamGraph(graph).isEmpty());
    }

    @Test
    void testAddEventTimeWatermarkCombinerAddsCombinerForEventTimeAndIdleStatus() {
        Set<AbstractInternalWatermarkDeclaration<?>> declarations = new HashSet<>();
        declarations.add(
                AbstractInternalWatermarkDeclaration.from(
                        EventTimeExtension.EVENT_TIME_WATERMARK_DECLARATION));
        Map<String, WatermarkCombiner> combiners = new HashMap<>();

        WatermarkUtils.addEventTimeWatermarkCombinerIfNeeded(declarations, combiners, 4);

        assertEquals(2, combiners.size());
        WatermarkCombiner eventTimeCombiner =
                combiners.get(EventTimeExtension.EVENT_TIME_WATERMARK_DECLARATION.getIdentifier());
        assertInstanceOf(EventTimeWatermarkCombiner.class, eventTimeCombiner);
        assertSame(
                eventTimeCombiner,
                combiners.get(
                        EventTimeExtension.IDLE_STATUS_WATERMARK_DECLARATION.getIdentifier()));
    }

    @Test
    void testAddEventTimeWatermarkCombinerDoesNothingWithoutEventTimeDeclaration() {
        Set<AbstractInternalWatermarkDeclaration<?>> declarations = new HashSet<>();
        declarations.add(AbstractInternalWatermarkDeclaration.from(CUSTOM_BOOL_DECLARATION));
        WatermarkCombiner existingCombiner = new EventTimeWatermarkCombiner(1);
        Map<String, WatermarkCombiner> combiners = new HashMap<>();
        combiners.put("existing", existingCombiner);

        WatermarkUtils.addEventTimeWatermarkCombinerIfNeeded(declarations, combiners, 2);

        assertEquals(1, combiners.size());
        assertSame(existingCombiner, combiners.get("existing"));
        assertFalse(
                combiners.containsKey(
                        EventTimeExtension.EVENT_TIME_WATERMARK_DECLARATION.getIdentifier()));
    }

    @Test
    void testAddEventTimeWatermarkCombinerDoesNothingForEmptyDeclarations() {
        Map<String, WatermarkCombiner> combiners = new HashMap<>();

        WatermarkUtils.addEventTimeWatermarkCombinerIfNeeded(Collections.emptySet(), combiners, 3);

        assertTrue(combiners.isEmpty());
    }

    private static AbstractInternalWatermarkDeclaration<?> findDeclaration(
            Set<AbstractInternalWatermarkDeclaration<?>> declarations, String identifier) {
        return declarations.stream()
                .filter(declaration -> declaration.getIdentifier().equals(identifier))
                .findFirst()
                .orElseThrow(() -> new AssertionError("Missing declaration: " + identifier));
    }

