                typeFactory
                        .builder()
                        .add("id", nonNullIntType)
                        .add("amount", typeFactory.createSqlType(SqlTypeName.BIGINT))
                        .build();

        List<RexNode> projects = rexBuilder.identityProjects(rowType);

        assertEquals(2, projects.size());
