        RexNode single = rexBuilder.makeIn(intRef, ImmutableList.of(one));
        RexNode multiple = rexBuilder.makeIn(intRef, ImmutableList.of(one, two));
        RexNode expressionBound = rexBuilder.makeCall(SqlStdOperatorTable.PLUS, intRef, one);
        RexNode mixed = rexBuilder.makeIn(intRef, ImmutableList.of(expressionBound, two));
        RexNode empty = rexBuilder.makeIn(intRef, ImmutableList.of());

        assertEquals(SqlKind.EQUALS, single.getKind());
        assertEquals(SqlKind.SEARCH, multiple.getKind());
