/** Behavior tests for {@link RexSimplify}. */
class RexSimplifyTest {
    private RelDataTypeFactory typeFactory;
    private RexBuilder rexBuilder;
    private RexSimplify simplify;
    private RelDataType intType;
    private RelDataType booleanType;
    private RelDataType nonNullBooleanType;
    private RexInputRef intRef;
    private RexInputRef booleanRef;
    private RexInputRef nonNullBooleanRef;

    @BeforeEach
    void setUp() {
        typeFactory = new JavaTypeFactoryImpl();
        rexBuilder = new RexBuilder(typeFactory);
        simplify = new RexSimplify(rexBuilder, RelOptPredicateList.EMPTY, RexUtil.EXECUTOR);
        intType = nullable(typeFactory.createSqlType(SqlTypeName.INTEGER));
        booleanType = nullable(typeFactory.createSqlType(SqlTypeName.BOOLEAN));
        nonNullBooleanType = notNull(typeFactory.createSqlType(SqlTypeName.BOOLEAN));
        intRef = rexBuilder.makeInputRef(intType, 0);
        booleanRef = rexBuilder.makeInputRef(booleanType, 1);
        nonNullBooleanRef = rexBuilder.makeInputRef(nonNullBooleanType, 2);
    }

    private RelDataType nullable(RelDataType type) {
        return typeFactory.createTypeWithNullability(type, true);
    }

    private RelDataType notNull(RelDataType type) {
        return typeFactory.createTypeWithNullability(type, false);
    }

    private RexLiteral intLiteral(long value) {
        return rexBuilder.makeExactLiteral(BigDecimal.valueOf(value));
    }

    private RexNode eq(RexNode left, RexNode right) {
        return rexBuilder.makeCall(SqlStdOperatorTable.EQUALS, left, right);
    }

    private RexNode not(RexNode node) {
        return rexBuilder.makeCall(SqlStdOperatorTable.NOT, node);
    }

    private RexNode and(RexNode... nodes) {
        return rexBuilder.makeCall(SqlStdOperatorTable.AND, nodes);
    }

    private RexNode or(RexNode... nodes) {
        return rexBuilder.makeCall(SqlStdOperatorTable.OR, nodes);
    }

    @Test
    void simplifiesBooleanIdentities() {
        RexNode trueLiteral = rexBuilder.makeLiteral(true);
        RexNode falseLiteral = rexBuilder.makeLiteral(false);

        assertSame(booleanRef, simplify.simplify(and(trueLiteral, booleanRef)));
        assertSame(booleanRef, simplify.simplify(or(falseLiteral, booleanRef)));
        assertTrue(simplify.simplify(and(booleanRef, falseLiteral)).isAlwaysFalse());
        assertTrue(simplify.simplify(or(booleanRef, trueLiteral)).isAlwaysTrue());
        assertSame(booleanRef, simplify.simplify(not(not(booleanRef))));
        assertSame(booleanRef, simplify.simplify(and(booleanRef, booleanRef)));
        assertSame(booleanRef, simplify.simplify(or(booleanRef, booleanRef)));
    }

    @Test
    void simplifiesContradictionsForNonNullablePredicates() {
        RexNode notRef = not(nonNullBooleanRef);

        assertTrue(simplify.simplify(and(nonNullBooleanRef, notRef)).isAlwaysFalse());
        assertTrue(simplify.simplify(or(nonNullBooleanRef, notRef)).isAlwaysTrue());
    }

    @Test
    void simplifiesNullHandlingForComparisons() {
        RexNode isOne = eq(intRef, intLiteral(1));
        RexNode nullInt = rexBuilder.makeNullLiteral(intType);

        assertTrue(
                simplify.simplify(
                                or(
                                        isOne,
                                        not(isOne),
                                        rexBuilder.makeCall(SqlStdOperatorTable.IS_NULL, intRef)))
                        .isAlwaysTrue());
        assertTrue(
                simplify.simplifyUnknownAsFalse(
                                or(
                                        isOne,
                                        not(isOne),
                                        rexBuilder.makeCall(SqlStdOperatorTable.IS_NULL, intRef)))
                        .isAlwaysTrue());
        assertTrue(RexUtil.isNull(simplify.simplify(eq(nullInt, intRef))));
    }

    @Test
    void simplifiesLiteralComparisons() {
        assertTrue(simplify.simplify(eq(intLiteral(2), intLiteral(2))).isAlwaysTrue());
        assertTrue(simplify.simplify(eq(intLiteral(2), intLiteral(3))).isAlwaysFalse());
        assertTrue(
                simplify.simplify(
                                rexBuilder.makeCall(
                                        SqlStdOperatorTable.GREATER_THAN,
                                        intLiteral(5),
                                        intLiteral(3)))
                        .isAlwaysTrue());
        assertTrue(
                simplify.simplify(
                                rexBuilder.makeCall(
                                        SqlStdOperatorTable.LESS_THAN,
                                        intLiteral(5),
                                        intLiteral(3)))
                        .isAlwaysFalse());
    }

    @Test
    void simplifiesNullPredicates() {
        RexNode nullInt = rexBuilder.makeNullLiteral(intType);

        assertTrue(
                simplify.simplify(rexBuilder.makeCall(SqlStdOperatorTable.IS_NULL, nullInt))
                        .isAlwaysTrue());
        assertTrue(
                simplify.simplify(rexBuilder.makeCall(SqlStdOperatorTable.IS_NOT_NULL, nullInt))
                        .isAlwaysFalse());
        assertTrue(
                simplify.simplify(rexBuilder.makeCall(SqlStdOperatorTable.IS_NULL, intLiteral(1)))
                        .isAlwaysFalse());
        assertTrue(
                simplify.simplify(
                                rexBuilder.makeCall(SqlStdOperatorTable.IS_NOT_NULL, intLiteral(1)))
                        .isAlwaysTrue());
    }

    @Test
    void simplifiesArithmeticIdentities() {
        RexNode plusZero = rexBuilder.makeCall(SqlStdOperatorTable.PLUS, intRef, intLiteral(0));
        RexNode timesOne = rexBuilder.makeCall(SqlStdOperatorTable.MULTIPLY, intRef, intLiteral(1));

        assertSame(intRef, simplify.simplify(plusZero));
        assertSame(intRef, simplify.simplify(timesOne));
        assertEquals(
                SqlKind.PLUS,
                simplify.simplify(
                                rexBuilder.makeCall(
                                        SqlStdOperatorTable.PLUS, intLiteral(1), intLiteral(2)))
                        .getKind());
    }

    @Test
    void simplifiesCoalesceAndCase() {
        RexNode nullInt = rexBuilder.makeNullLiteral(intType);
        RexNode coalesce =
                rexBuilder.makeCall(
                        intType,
                        SqlStdOperatorTable.COALESCE,
                        ImmutableList.of(nullInt, intLiteral(5)));
        RexNode caseTrue =
                rexBuilder.makeCall(
                        intType,
                        SqlStdOperatorTable.CASE,
                        ImmutableList.of(
                                rexBuilder.makeLiteral(true), intLiteral(1), intLiteral(2)));
        RexNode caseFalse =
                rexBuilder.makeCall(
                        intType,
                        SqlStdOperatorTable.CASE,
                        ImmutableList.of(
                                rexBuilder.makeLiteral(false), intLiteral(1), intLiteral(2)));

        assertEquals(BigDecimal.valueOf(5), ((RexLiteral) simplify.simplify(coalesce)).getValue());
        assertEquals(BigDecimal.ONE, ((RexLiteral) simplify.simplify(caseTrue)).getValue());
        assertEquals(BigDecimal.valueOf(2), ((RexLiteral) simplify.simplify(caseFalse)).getValue());
    }

    @Test
    void appliesUnknownAsPolicyToBooleanAndNonBooleanNulls() {
        RexNode nullBoolean = rexBuilder.makeNullLiteral(booleanType);
        RexNode nullInt = rexBuilder.makeNullLiteral(intType);

        assertTrue(simplify.simplifyUnknownAs(nullBoolean, RexUnknownAs.FALSE).isAlwaysFalse());
        assertTrue(simplify.simplifyUnknownAs(nullBoolean, RexUnknownAs.TRUE).isAlwaysTrue());
        RexNode simplifiedInt = simplify.simplifyUnknownAs(nullInt, RexUnknownAs.FALSE);
        assertTrue(RexUtil.isNull(simplifiedInt));
        assertEquals(SqlTypeName.INTEGER, simplifiedInt.getType().getSqlTypeName());
    }

    @Test
    void simplifiesIsTrueAndIsFalseWhenNullabilityIsKnown() {
        RexNode isTrue = rexBuilder.makeCall(SqlStdOperatorTable.IS_TRUE, nonNullBooleanRef);
        RexNode isFalse = rexBuilder.makeCall(SqlStdOperatorTable.IS_FALSE, nonNullBooleanRef);
        RexNode isNotTrue = rexBuilder.makeCall(SqlStdOperatorTable.IS_NOT_TRUE, nonNullBooleanRef);
        RexNode isNotFalse =
                rexBuilder.makeCall(SqlStdOperatorTable.IS_NOT_FALSE, nonNullBooleanRef);

        assertSame(nonNullBooleanRef, simplify.simplify(isTrue));
        assertEquals(SqlKind.NOT, simplify.simplify(isFalse).getKind());
        assertEquals(SqlKind.NOT, simplify.simplify(isNotTrue).getKind());
        assertSame(nonNullBooleanRef, simplify.simplify(isNotFalse));
    }

    @Test
    void simplifiesComparisonsAgainstNullUsingExplicitPolicy() {
        RexNode comparison = eq(intRef, rexBuilder.makeNullLiteral(intType));

        RexNode asFalse = simplify.simplifyComparisonWithNull(comparison, RexUnknownAs.FALSE);
        RexNode asUnknown = simplify.simplifyComparisonWithNull(comparison, RexUnknownAs.UNKNOWN);

        assertTrue(asFalse.isAlwaysFalse());
        assertTrue(RexUtil.isNull(asUnknown));
        assertEquals(SqlTypeName.BOOLEAN, asUnknown.getType().getSqlTypeName());
    }

    @Test
    void staticComparisonAgainstNullUsesFalsePolicy() {
        RexNode comparison = eq(rexBuilder.makeNullLiteral(intType), intRef);

        assertTrue(RexSimplify.simplifyComparisonWithNull(comparison, rexBuilder).isAlwaysFalse());
    }

    @Test
    void withUnknownAsFalseEnablesPredicateOptimizations() {
        RexSimplify falseSimplify = simplify.withUnknownAsFalse(true);
        RexNode comparison = eq(intRef, rexBuilder.makeNullLiteral(intType));

        assertNotSame(simplify, falseSimplify);
        assertTrue(falseSimplify.simplify(comparison).isAlwaysFalse());
        assertTrue(RexUtil.isNull(simplify.simplify(comparison)));
    }

    @Test
    void withParanoidCreatesIndependentSimplifier() {
        RexSimplify paranoid = simplify.withParanoid(true);
        RexNode expression = and(booleanRef, rexBuilder.makeLiteral(true));

        assertNotSame(simplify, paranoid);
        assertSame(booleanRef, paranoid.simplify(expression));
        assertSame(booleanRef, simplify.simplify(expression));
    }

    @Test
    void usesKnownPredicatesWhenSimplifying() {
        RexNode notNull = rexBuilder.makeCall(SqlStdOperatorTable.IS_NOT_NULL, intRef);
        RexNode isOne = eq(intRef, intLiteral(1));
        RelOptPredicateList predicates =
                RelOptPredicateList.of(rexBuilder, ImmutableList.of(notNull, isOne));
        RexSimplify withPredicates = new RexSimplify(rexBuilder, predicates, RexUtil.EXECUTOR);

        assertTrue(withPredicates.simplify(notNull).isAlwaysTrue());
        assertEquals(SqlKind.IS_NOT_NULL, simplify.simplify(notNull).getKind());
    }

    @Test
    void withPredicatesAddsKnowledgeWithoutMutatingOriginal() {
        RexNode notNull = rexBuilder.makeCall(SqlStdOperatorTable.IS_NOT_NULL, intRef);
        RelOptPredicateList predicates =
                RelOptPredicateList.of(rexBuilder, ImmutableList.of(notNull));
        RexSimplify withPredicates = simplify.withPredicates(predicates);
        RexNode expression = and(notNull, rexBuilder.makeLiteral(true));

        assertNotSame(simplify, withPredicates);
        assertTrue(withPredicates.simplify(expression).isAlwaysTrue());
        assertEquals(SqlKind.IS_NOT_NULL, simplify.simplify(expression).getKind());
    }

    @Test
    void simplifyPreservingTypeKeepsExpressionTypeAndNullability() {
        RexNode comparison =
                or(
                        eq(intRef, intLiteral(1)),
                        not(eq(intRef, intLiteral(1))),
                        rexBuilder.makeCall(SqlStdOperatorTable.IS_NULL, intRef));
        assertTrue(comparison.getType().isNullable());

        RexNode simplified = simplify.simplifyPreservingType(comparison);

        assertTrue(simplified.isAlwaysTrue());
        assertEquals(comparison.getType(), simplified.getType());
        assertTrue(simplified.getType().isNullable());
    }

    @Test
    void simplifiesAndsAndOrsCollections() {
        RexNode isOne = eq(intRef, intLiteral(1));

        RexNode conjunction =
                simplify.simplifyAnds(
                        new java.util.ArrayList<>(
                                Arrays.asList(rexBuilder.makeLiteral(true), isOne, isOne)));
        RexNode disjunction =
                simplify.simplifyOrs(
                        new java.util.ArrayList<>(
                                Arrays.asList(rexBuilder.makeLiteral(false), isOne, isOne)));

        assertSame(isOne, conjunction);
        assertSame(isOne, disjunction);
    }

    @Test
    void simplifiesCallSpecificConjunctionAndDisjunction() {
        RexNode isOne = eq(intRef, intLiteral(1));
        RexCall conjunction = (RexCall) and(isOne, rexBuilder.makeLiteral(true));
        RexCall disjunction = (RexCall) or(isOne, rexBuilder.makeLiteral(false));

        assertEquals(isOne, simplify.simplifyAnd(conjunction));
        assertEquals(isOne, simplify.simplifyOr(disjunction));
    }

    @Test
    void deprecatedSimplifyAndsWithPoliciesRemainUsable() {
        RexNode nullComparison = eq(intRef, rexBuilder.makeNullLiteral(intType));

        assertTrue(
                simplify.simplifyAnds(ImmutableList.of(nullComparison), RexUnknownAs.FALSE)
                        .isAlwaysFalse());
        assertTrue(simplify.simplifyUnknownAs(nullComparison, RexUnknownAs.FALSE).isAlwaysFalse());
    }

    @Test
    void paranoidMethodsRejectUnsupportedEntryPoints() {
        RexSimplify paranoid = simplify.withParanoid(true);
        RexNode isOne = eq(intRef, intLiteral(1));
        RexCall conjunction = (RexCall) and(isOne, rexBuilder.makeLiteral(true));

        assertThrows(UnsupportedOperationException.class, () -> paranoid.simplifyAnd(conjunction));
        assertThrows(
                UnsupportedOperationException.class,
                () -> paranoid.simplifyAnds(ImmutableList.of(isOne)));
    }
