/** Behavior tests for {@link RexUtil}. */
class RexUtilTest {
    private RelDataTypeFactory typeFactory;
    private RexBuilder rexBuilder;
    private RelDataType intType;
    private RelDataType nonNullIntType;
    private RelDataType bigintType;
    private RelDataType booleanType;
    private RexInputRef intRef;
    private RexInputRef otherRef;

    @BeforeEach
    void setUp() {
        typeFactory = new JavaTypeFactoryImpl();
        rexBuilder = new RexBuilder(typeFactory);
        intType =
                typeFactory.createTypeWithNullability(
                        typeFactory.createSqlType(SqlTypeName.INTEGER), true);
        nonNullIntType =
                typeFactory.createTypeWithNullability(
                        typeFactory.createSqlType(SqlTypeName.INTEGER), false);
        bigintType =
                typeFactory.createTypeWithNullability(
                        typeFactory.createSqlType(SqlTypeName.BIGINT), true);
        booleanType =
                typeFactory.createTypeWithNullability(
                        typeFactory.createSqlType(SqlTypeName.BOOLEAN), true);
        intRef = rexBuilder.makeInputRef(intType, 0);
        otherRef = rexBuilder.makeInputRef(intType, 1);
    }

    private RexLiteral intLiteral(long value) {
        return rexBuilder.makeExactLiteral(BigDecimal.valueOf(value));
    }

    private RexLiteral booleanLiteral(boolean value) {
        return rexBuilder.makeLiteral(value);
    }

    private RexNode eq(RexNode left, RexNode right) {
        return rexBuilder.makeCall(SqlStdOperatorTable.EQUALS, left, right);
    }

    private RexNode and(RexNode... nodes) {
        return rexBuilder.makeCall(SqlStdOperatorTable.AND, nodes);
    }

    private RexNode or(RexNode... nodes) {
        return rexBuilder.makeCall(SqlStdOperatorTable.OR, nodes);
    }

    @Test
    void getSelectivityUsesSentinelValueForUnknownOrTrue() {
        assertEquals(1d, RexUtil.getSelectivity(null));
        assertEquals(1d, RexUtil.getSelectivity(booleanLiteral(true)));
        assertEquals(0.1d, RexUtil.getSelectivity(eq(intRef, intLiteral(1))));
    }

    @Test
    void identifiesNullLiterals() {
        RexLiteral nullInt = rexBuilder.makeNullLiteral(intType);
        RexNode castNull = rexBuilder.makeAbstractCast(bigintType, nullInt);

        assertTrue(RexUtil.isNullLiteral(rexBuilder.constantNull(), true));
        assertTrue(RexUtil.isNullLiteral(nullInt, true));
        assertTrue(RexUtil.isNull(nullInt));
        assertTrue(RexUtil.isNull(castNull));
        assertFalse(RexUtil.isNull(intLiteral(1)));
        assertFalse(RexUtil.isNull(booleanLiteral(false)));
    }

    @Test
    void identifiesSymbolAndOtherLiterals() {
        RexLiteral flag = rexBuilder.makeFlag(java.time.temporal.ChronoUnit.DAYS);
        RexNode castLiteral = rexBuilder.makeAbstractCast(bigintType, intLiteral(1));
        RexNode castRef = rexBuilder.makeAbstractCast(bigintType, intRef);

        assertTrue(RexUtil.isSymbolLiteral(flag));
        assertFalse(RexUtil.isSymbolLiteral(intLiteral(1)));
        assertTrue(RexUtil.isLiteral(intLiteral(1), false));
        assertTrue(RexUtil.isLiteral(castLiteral, true));
        assertFalse(RexUtil.isLiteral(castLiteral, false));
        assertTrue(RexUtil.allLiterals(ImmutableList.of(intLiteral(1), castLiteral)));
        assertFalse(RexUtil.allLiterals(ImmutableList.of(intLiteral(1), castRef)));
    }

    @Test
    void identifiesReferencesCastsAndFieldAccess() {
        RelDataType rowType = typeFactory.builder().add("i", intType).build();
        RexInputRef rowRef =
                rexBuilder.makeInputRef(typeFactory.createTypeWithNullability(rowType, true), 0);
        RexNode fieldAccess = rexBuilder.makeFieldAccess(rowRef, 0);
        RexNode castRef = rexBuilder.makeAbstractCast(bigintType, intRef);

        assertTrue(RexUtil.isReferenceOrAccess(intRef, false));
        assertTrue(RexUtil.isReferenceOrAccess(fieldAccess, false));
        assertTrue(RexUtil.isReferenceOrAccess(castRef, true));
        assertFalse(RexUtil.isReferenceOrAccess(castRef, false));
        assertFalse(RexUtil.isReferenceOrAccess(eq(intRef, intLiteral(1)), true));
    }

    @Test
    void detectsAndRemovesNullabilityCastsAndRegularCasts() {
        RexNode nonNullRef = rexBuilder.makeInputRef(nonNullIntType, 0);
        RexNode nullableCast = rexBuilder.makeNullable(nonNullRef);
        RexNode intToBigint = rexBuilder.makeAbstractCast(bigintType, intRef);

        assertTrue(RexUtil.isNullabilityCast(typeFactory, nullableCast));
        assertSame(nonNullRef, RexUtil.removeNullabilityCast(typeFactory, nullableCast));
        assertFalse(RexUtil.isNullabilityCast(typeFactory, intToBigint));
        assertSame(intRef, RexUtil.removeCast(intToBigint));
    }

    @Test
    void predicateConstantsExtractsEqualityConstants() {
        RexNode isOne = eq(intRef, intLiteral(1));
        RexNode notNull = rexBuilder.makeCall(SqlStdOperatorTable.IS_NOT_NULL, otherRef);

        ImmutableMap<RexNode, RexLiteral> constants =
                RexUtil.predicateConstants(
                        RexLiteral.class, rexBuilder, ImmutableList.of(isOne, notNull));

        assertEquals(1, constants.size());
        assertEquals(intLiteral(1), constants.get(intRef));
    }

    @Test
    void countsNodesAndFindsCallsByKind() {
        RexNode sum = rexBuilder.makeCall(SqlStdOperatorTable.PLUS, intRef, intLiteral(1));
        RexNode product = rexBuilder.makeCall(SqlStdOperatorTable.MULTIPLY, sum, intLiteral(2));

        assertEquals(1, intLiteral(1).nodeCount());
        assertEquals(3, sum.nodeCount());
        assertEquals(9, RexUtil.nodeCount(ImmutableList.of(intLiteral(1), sum, product)));
        assertTrue(RexUtil.find(SqlKind.PLUS).contains(product));
        assertFalse(RexUtil.find(SqlKind.DIVIDE).contains(product));
        assertTrue(RexUtil.find(intRef).contains(product));
        assertFalse(RexUtil.find(otherRef).contains(product));
    }

    @Test
    void evaluatesConstantAndDeterminismProperties() {
        RexNode constantSum =
                rexBuilder.makeCall(SqlStdOperatorTable.PLUS, intLiteral(1), intLiteral(2));
        RexNode refSum = rexBuilder.makeCall(SqlStdOperatorTable.PLUS, intRef, intLiteral(1));
        RexNode random =
                rexBuilder.makeCall(booleanType, SqlStdOperatorTable.RAND, ImmutableList.of());
        RexNode isOne = eq(intRef, intLiteral(1));
        RexNode plusOne = rexBuilder.makeCall(SqlStdOperatorTable.PLUS, intRef, intLiteral(1));

        assertTrue(RexUtil.isConstant(intLiteral(1)));
        assertTrue(RexUtil.isConstant(constantSum));
        assertFalse(RexUtil.isConstant(refSum));
        assertTrue(RexUtil.isDeterministic(refSum));
        assertFalse(RexUtil.isDeterministic(random));
        assertEquals(
                ImmutableList.of(isOne),
                RexUtil.retainDeterministic(ImmutableList.of(isOne, random)));
        assertEquals(plusOne, RexUtil.findOperatorCall(SqlStdOperatorTable.PLUS, refSum));
        assertNull(RexUtil.findOperatorCall(SqlStdOperatorTable.MULTIPLY, refSum));
    }

    @Test
    void detectsInputRefsAndFieldAccess() {
        RelDataType rowType = typeFactory.builder().add("i", intType).build();
        RexInputRef rowRef = rexBuilder.makeInputRef(rowType, 0);
        RexNode fieldAccess = rexBuilder.makeFieldAccess(rowRef, "i", true);

        assertTrue(RexUtil.containsInputRef(eq(intRef, intLiteral(1))));
        assertFalse(RexUtil.containsInputRef(intLiteral(1)));
        assertTrue(RexUtil.containsFieldAccess(fieldAccess));
        assertFalse(RexUtil.containsFieldAccess(intRef));
    }

    @Test
    void detectsDecimalExpansionRequirements() {
        RelDataType decimalType =
                typeFactory.createTypeWithNullability(
                        typeFactory.createSqlType(SqlTypeName.DECIMAL, 10, 2), true);
        RexInputRef decimalRef = rexBuilder.makeInputRef(decimalType, 2);
        RexNode decimalSum = rexBuilder.makeCall(SqlStdOperatorTable.PLUS, decimalRef, decimalRef);
        RexNode intSum = rexBuilder.makeCall(SqlStdOperatorTable.PLUS, intRef, intLiteral(1));
        RexNode decimalIsNull = rexBuilder.makeCall(SqlStdOperatorTable.IS_NULL, decimalRef);

        assertTrue(RexUtil.requiresDecimalExpansion(decimalSum, true));
        assertFalse(RexUtil.requiresDecimalExpansion(intSum, true));
        assertFalse(RexUtil.requiresDecimalExpansion(decimalIsNull, true));
    }

    @Test
    void createsStructTypesAndCompatibleExpressionLists() {
        RexLiteral one = intLiteral(1);
        RexLiteral two = intLiteral(2);

        RelDataType unnamed = RexUtil.createStructType(typeFactory, ImmutableList.of(one, two));
        RelDataType named =
                RexUtil.createStructType(
                        typeFactory, ImmutableList.of(one, two), Arrays.asList("a", null));
        RelDataType compatible =
                typeFactory.builder().add("a", one.getType()).add("b", two.getType()).build();

        assertEquals("$f0", unnamed.getFieldList().get(0).getName());
        assertEquals("$f1", unnamed.getFieldList().get(1).getName());
        assertEquals("a", named.getFieldList().get(0).getName());
        assertEquals("$f1", named.getFieldList().get(1).getName());
        assertTrue(RexUtil.compatibleTypes(ImmutableList.of(one, two), compatible, Litmus.IGNORE));
        assertFalse(RexUtil.compatibleTypes(ImmutableList.of(one), compatible, Litmus.IGNORE));
    }

    @Test
    void makeKeyIncludesTypeInformation() {
        RexLiteral intOne = intLiteral(1);
        RexLiteral bigintOne = rexBuilder.makeBigintLiteral(BigDecimal.ONE);

        Pair<RexNode, String> intKey = RexUtil.makeKey(intOne);
        Pair<RexNode, String> bigintKey = RexUtil.makeKey(bigintOne);

        assertSame(intOne, intKey.left);
        assertEquals(intOne.getType().getFullTypeString(), intKey.right);
        assertNotEquals(intKey.right, bigintKey.right);
    }

    @Test
    void recognisesIdentityProjections() {
        RelDataType rowType = typeFactory.builder().add("i", intType).add("j", bigintType).build();
        List<RexNode> identity = rexBuilder.identityProjects(rowType);
        List<RexNode> reordered = ImmutableList.of(identity.get(1), identity.get(0));

        assertTrue(RexUtil.isIdentity(identity, rowType));
        assertTrue(RexUtil.containIdentity(identity, rowType, Litmus.IGNORE));
        assertFalse(RexUtil.isIdentity(reordered, rowType));
        assertFalse(RexUtil.containIdentity(reordered, rowType, Litmus.IGNORE));
    }

    @Test
    void composesAndFlattensConjunctions() {
        RexNode first = eq(intRef, intLiteral(1));
        RexNode second = eq(otherRef, intLiteral(2));
        RexNode nested = and(first, and(second, first));

        RexNode empty = RexUtil.composeConjunction(rexBuilder, ImmutableList.of());
        RexNode withTrue =
                RexUtil.composeConjunction(
                        rexBuilder, ImmutableList.of(booleanLiteral(true), first));
        RexNode withFalse =
                RexUtil.composeConjunction(
                        rexBuilder, ImmutableList.of(first, booleanLiteral(false)));
        RexCall flattened =
                (RexCall) RexUtil.composeConjunction(rexBuilder, ImmutableList.of(nested));

        assertTrue(empty.isAlwaysTrue());
        assertSame(first, withTrue);
        assertTrue(withFalse.isAlwaysFalse());
        assertEquals(SqlKind.AND, flattened.getKind());
        assertEquals(2, flattened.getOperands().size());
        assertEquals(ImmutableList.of(first, second), RexUtil.flattenAnd(ImmutableList.of(nested)));
    }

    @Test
    void composesAndFlattensDisjunctions() {
        RexNode first = eq(intRef, intLiteral(1));
        RexNode second = eq(otherRef, intLiteral(2));
        RexNode nested = or(first, or(second, first));

        RexNode empty = RexUtil.composeDisjunction(rexBuilder, ImmutableList.of());
        RexNode withFalse =
                RexUtil.composeDisjunction(
                        rexBuilder, ImmutableList.of(booleanLiteral(false), first));
        RexNode withTrue =
                RexUtil.composeDisjunction(
                        rexBuilder, ImmutableList.of(first, booleanLiteral(true)));
        RexCall flattened =
                (RexCall) RexUtil.composeDisjunction(rexBuilder, ImmutableList.of(nested));

        assertTrue(empty.isAlwaysFalse());
        assertSame(first, withFalse);
        assertTrue(withTrue.isAlwaysTrue());
        assertEquals(SqlKind.OR, flattened.getKind());
        assertEquals(2, flattened.getOperands().size());
        assertEquals(ImmutableList.of(first, second), RexUtil.flattenOr(ImmutableList.of(nested)));
    }

    @Test
    void convertsBetweenNormalForms() {
        RexNode a = rexBuilder.makeInputRef(booleanType, 0);
        RexNode b = rexBuilder.makeInputRef(booleanType, 1);
        RexNode c = rexBuilder.makeInputRef(booleanType, 2);

        RexNode cnf = RexUtil.toCnf(rexBuilder, or(and(a, b), c));
        RexNode dnf = RexUtil.toDnf(rexBuilder, and(or(a, b), c));

        assertEquals(SqlKind.AND, cnf.getKind());
        assertEquals(2, ((RexCall) cnf).getOperands().size());
        assertTrue(
                ((RexCall) cnf)
                        .getOperands().stream().allMatch(node -> node.getKind() == SqlKind.OR));
        assertEquals(SqlKind.OR, dnf.getKind());
        assertEquals(2, ((RexCall) dnf).getOperands().size());
        assertTrue(
                ((RexCall) dnf)
                        .getOperands().stream().allMatch(node -> node.getKind() == SqlKind.AND));
    }

    @Test
    void shiftsInputReferences() {
        RexNode expression = eq(intRef, otherRef);
        RexInputRef lowRef = rexBuilder.makeInputRef(intType, 0);
        RexInputRef highRef = rexBuilder.makeInputRef(intType, 2);
        RexNode startExpression = eq(lowRef, highRef);

        RexNode shifted = RexUtil.shift(expression, 5);
        RexNode partiallyShifted = RexUtil.shift(startExpression, 1, 4);
        List<RexNode> shiftedList = RexUtil.shift(ImmutableList.of(intRef, otherRef), 3);

        assertEquals(5, ((RexInputRef) ((RexCall) shifted).getOperands().get(0)).getIndex());
        assertEquals(6, ((RexInputRef) ((RexCall) shifted).getOperands().get(1)).getIndex());
        assertEquals(
                0, ((RexInputRef) ((RexCall) partiallyShifted).getOperands().get(0)).getIndex());
        assertEquals(
                6, ((RexInputRef) ((RexCall) partiallyShifted).getOperands().get(1)).getIndex());
        assertEquals(3, ((RexInputRef) shiftedList.get(0)).getIndex());
        assertEquals(4, ((RexInputRef) shiftedList.get(1)).getIndex());
        assertSame(expression, RexUtil.shift(expression, 0));
    }

    @Test
    void fixesInputRefNullabilityToMatchFields() {
        RexInputRef nullableRef = rexBuilder.makeInputRef(intType, 0);

        List<RexNode> result =
                RexUtil.fixUp(
                        rexBuilder,
                        ImmutableList.of(nullableRef),
                        ImmutableList.of(nonNullIntType));

        RexInputRef fixed = (RexInputRef) result.get(0);
        assertEquals(0, fixed.getIndex());
        assertFalse(fixed.getType().isNullable());
        assertThrows(
                AssertionError.class,
                () ->
                        RexUtil.fixUp(
                                rexBuilder,
                                ImmutableList.of(intRef),
                                ImmutableList.of(bigintType)));
    }

    @Test
    void extractsTypesAndFamilies() {
        List<RelDataType> types = RexUtil.types(ImmutableList.of(intRef, intLiteral(1)));

        assertEquals(ImmutableList.of(intType, intLiteral(1).getType()), types);
        assertEquals(
                ImmutableList.of(intType.getFamily(), intType.getFamily()),
                RexUtil.families(types));
