import org.junit.jupiter.api.Test;

import static org.assertj.core.api.Assertions.assertThat;

/** Tests for the public decorrelation entry points of {@link RelDecorrelator}. */
class RelDecorrelatorTest {

    @Test
    void returnsOriginalPlanWhenThereIsNoCorrelation() {
        final RelBuilder builder = Sql2RelTestSupport.newRelBuilder();
        final RelNode root =
                builder.scan(Sql2RelTestSupport.EMP).project(builder.field("EMPNO")).build();

        final RelNode result =
                RelDecorrelator.decorrelateQuery(root, Sql2RelTestSupport.newRelBuilder());

        assertThat(result).isSameAs(root);
    }

    @Test
    void decorrelatesCorrelatedLeftJoin() {
        final RelNode root = correlatedJoin(JoinRelType.LEFT);
        assertThat(Sql2RelTestSupport.containsCorrelate(root)).isTrue();

        final RelNode result =
                RelDecorrelator.decorrelateQuery(root, Sql2RelTestSupport.newRelBuilder());

        assertThat(Sql2RelTestSupport.containsCorrelate(result)).isFalse();
        assertThat(result.getRowType().getFieldNames()).containsExactly("ENAME", "DNAME");

        final LogicalJoin join = Sql2RelTestSupport.find(result, LogicalJoin.class);
        assertThat(join).isNotNull();
        assertThat(join.getJoinType()).isEqualTo(JoinRelType.LEFT);
        assertThat(join.getCondition().getKind()).isEqualTo(SqlKind.EQUALS);
    }

    @Test
    void decorrelatesCorrelatedInnerJoin() {
        final RelNode root = correlatedJoin(JoinRelType.INNER);

        final RelNode result =
                RelDecorrelator.decorrelateQuery(root, Sql2RelTestSupport.newRelBuilder());

        assertThat(Sql2RelTestSupport.containsCorrelate(result)).isFalse();
        final LogicalJoin join = Sql2RelTestSupport.find(result, LogicalJoin.class);
        assertThat(join).isNotNull();
        assertThat(join.getJoinType()).isEqualTo(JoinRelType.INNER);
        assertThat(join.getCondition().getKind()).isEqualTo(SqlKind.EQUALS);
    }

    @Test
    void decorrelatesScalarAggregateSubQuery() {
        final RelNode root = correlatedScalarAggregate();
        assertThat(Sql2RelTestSupport.containsCorrelate(root)).isTrue();

        final RelNode result =
                RelDecorrelator.decorrelateQuery(root, Sql2RelTestSupport.newRelBuilder());

        assertThat(Sql2RelTestSupport.containsCorrelate(result)).isFalse();
        assertThat(result.getRowType().getFieldNames()).containsExactly("ENAME", "C");
        assertThat(Sql2RelTestSupport.find(result, LogicalAggregate.class)).isNotNull();
        assertThat(Sql2RelTestSupport.find(result, LogicalJoin.class).getJoinType())
                .isEqualTo(JoinRelType.LEFT);
    }

    @Test
    void corelMapBuilderFindsCorrelationVariables() {
        final RelNode root = correlatedJoin(JoinRelType.LEFT);
        final Correlate correlate = Sql2RelTestSupport.find(root, Correlate.class);
        assertThat(correlate).isNotNull();

        final RelDecorrelator.CorelMap corelMap = new RelDecorrelator.CorelMapBuilder().build(root);

        assertThat(corelMap.hasCorrelation()).isTrue();
        assertThat(corelMap.getMapCorToCorRel()).containsOnlyKeys(correlate.getCorrelationId());

        final RelNode plain =
                Sql2RelTestSupport.newRelBuilder().scan(Sql2RelTestSupport.EMP).build();
        final RelDecorrelator.CorelMap emptyMap =
                new RelDecorrelator.CorelMapBuilder().build(plain);

        assertThat(emptyMap.hasCorrelation()).isFalse();
        assertThat(emptyMap.getMapCorToCorRel()).isEmpty();
    }

    @Test
    void decorrelateQueryAcceptsExplicitRuleSet() {
        final RelNode root = correlatedScalarAggregate();

        final RelNode result =
                RelDecorrelator.decorrelateQuery(
                        root,
                        Sql2RelTestSupport.newRelBuilder(),
                        RuleSets.ofList(
                                RelDecorrelator.RemoveCorrelationForScalarProjectRule.DEFAULT
                                        .toRule()));

        assertThat(result).isNotSameAs(root);
        assertThat(Sql2RelTestSupport.containsCorrelate(result)).isFalse();
        assertThat(result.getRowType().getFieldNames()).containsExactly("ENAME", "C");
    }

    private static RelNode correlatedJoin(JoinRelType joinType) {
        final RelBuilder builder = Sql2RelTestSupport.newRelBuilder();
        builder.scan(Sql2RelTestSupport.EMP).as("e");
        final Holder<RexCorrelVariable> holder = Holder.of(null);
        builder.variable(holder::set);
        final RexCorrelVariable correlateVariable = holder.get();
        final RexNode correlatedDeptNo =
                builder.getRexBuilder().makeFieldAccess(correlateVariable, 2);

        builder.scan(Sql2RelTestSupport.DEPT)
                .as("d")
                .filter(builder.equals(builder.field("DEPTNO"), correlatedDeptNo))
                .project(builder.field("DNAME"));
        builder.correlate(joinType, correlateVariable.id, builder.literal(true));
        builder.project(builder.field("e", "ENAME"), builder.field("d", "DNAME"));
        return builder.build();
    }

    private static RelNode correlatedScalarAggregate() {
        final RelBuilder builder = Sql2RelTestSupport.newRelBuilder();
        builder.scan(Sql2RelTestSupport.EMP).as("e");
        final Holder<RexCorrelVariable> holder = Holder.of(null);
        builder.variable(holder::set);
        final RexCorrelVariable correlateVariable = holder.get();
        final RexNode correlatedDeptNo =
                builder.getRexBuilder().makeFieldAccess(correlateVariable, 2);

        builder.scan(Sql2RelTestSupport.DEPT)
                .as("d")
                .filter(builder.equals(builder.field("DEPTNO"), correlatedDeptNo))
                .project(builder.field("DNAME"), builder.field("DEPTNO"))
                .aggregate(builder.groupKey(), builder.count(false, "C"));
        builder.correlate(JoinRelType.LEFT, correlateVariable.id, builder.literal(true));
        builder.project(builder.field("e", "ENAME"), builder.alias(builder.field(5), "C"));
        return builder.build();
    }
