/** Tests for the public workflows of {@link SqlToRelConverter}. */
class SqlToRelConverterTest {

    @Test
    void convertsSelectToProjectFilterAndSortedRoot() {
        final Sql2RelTestSupport fixture = new Sql2RelTestSupport();

        final RelRoot root =
                fixture.convert("select EMPNO, ENAME from EMP where DEPTNO = 10 order by EMPNO");

        assertThat(root.kind).isEqualTo(SqlKind.SELECT);
        assertThat(root.rel).isInstanceOf(LogicalSort.class);
        assertThat(root.rel.getRowType().getFieldNames()).containsExactly("EMPNO", "ENAME");
        assertThat(root.collation.getFieldCollations()).hasSize(1);

        final LogicalSort sort = (LogicalSort) root.rel;
        final RelFieldCollation fieldCollation = sort.collation.getFieldCollations().get(0);
        assertThat(fieldCollation.getFieldIndex()).isZero();
        assertThat(fieldCollation.getDirection()).isEqualTo(RelFieldCollation.Direction.ASCENDING);

        final LogicalProject project = Sql2RelTestSupport.find(root.rel, LogicalProject.class);
        assertThat(project).isNotNull();
        assertThat(project.getRowType().getFieldNames()).containsExactly("EMPNO", "ENAME");

        final LogicalFilter filter = Sql2RelTestSupport.find(root.rel, LogicalFilter.class);
        assertThat(filter).isNotNull();
        assertThat(filter.getCondition().getKind()).isEqualTo(SqlKind.EQUALS);

        final LogicalTableScan scan = Sql2RelTestSupport.find(root.rel, LogicalTableScan.class);
        assertThat(scan).isNotNull();
        assertThat(scan.getTable().getQualifiedName()).containsExactly(Sql2RelTestSupport.EMP);
    }

    @Test
    void convertQueryValidatesOnDemandAndRejectsInvalidColumns() {
        final Sql2RelTestSupport fixture = new Sql2RelTestSupport();

        final SqlNode unvalidated = Sql2RelTestSupport.parseQuery("select EMPNO from EMP");
        final RelRoot root = fixture.converter.convertQuery(unvalidated, true, true);

        assertThat(root.rel.getRowType().getFieldNames()).containsExactly("EMPNO");

        final SqlNode invalid = Sql2RelTestSupport.parseQuery("select NOSUCH from EMP");
        assertThatThrownBy(() -> fixture.converter.convertQuery(invalid, true, true))
                .isInstanceOf(CalciteContextException.class)
                .hasMessageContaining("Column 'NOSUCH' not found");
    }

    @Test
    void reportsDynamicParameterCountAndInferredType() {
        final Sql2RelTestSupport fixture = new Sql2RelTestSupport();

        final RelRoot root = fixture.convert("select EMPNO from EMP where DEPTNO = ?");

        assertThat(fixture.converter.getDynamicParamCount()).isEqualTo(1);
        assertThat(fixture.converter.getDynamicParamType(0).getSqlTypeName())
                .isEqualTo(SqlTypeName.INTEGER);

        final LogicalFilter filter = Sql2RelTestSupport.find(root.rel, LogicalFilter.class);
        final RexCall condition = (RexCall) filter.getCondition();
        assertThat(condition.getOperands().get(1)).isInstanceOf(RexDynamicParam.class);
        assertThat(((RexDynamicParam) condition.getOperands().get(1)).getIndex()).isZero();

        assertThatThrownBy(() -> fixture.converter.getDynamicParamType(9))
                .isInstanceOf(IndexOutOfBoundsException.class);
    }

    @Test
    void convertExpressionEvaluatesLiteralArithmetic() {
        final Sql2RelTestSupport fixture = new Sql2RelTestSupport();

        final RexNode rex =
                fixture.converter.convertExpression(Sql2RelTestSupport.parseExpression("1 + 2"));

        assertThat(rex).isInstanceOf(RexCall.class);
        final RexCall call = (RexCall) rex;
        assertThat(call.getKind()).isEqualTo(SqlKind.PLUS);
        assertThat(call.getOperands()).hasSize(2);
        assertThat(call.getOperands()).allMatch(operand -> operand instanceof RexLiteral);
        assertThat(call.getType().getSqlTypeName()).isEqualTo(SqlTypeName.INTEGER);
    }

    @Test
    void convertExpressionUsesNameToNodeMapping() {
        final Sql2RelTestSupport fixture = new Sql2RelTestSupport();
        final RexNode ten = fixture.converter.getRexBuilder().makeExactLiteral(BigDecimal.TEN);

        final RexNode rex =
                fixture.converter.convertExpression(
                        Sql2RelTestSupport.parseExpression("A + 1"), Map.of("A", ten));

        final RexCall call = (RexCall) rex;
        assertThat(call.getKind()).isEqualTo(SqlKind.PLUS);
        assertThat(call.getOperands().get(0)).isEqualTo(ten);
        assertThat(call.getOperands().get(1)).isInstanceOf(RexLiteral.class);
    }

    @Test
    void convertsAggregateCallsWithNamesKindsAndDistinctFlags() {
        final Sql2RelTestSupport fixture = new Sql2RelTestSupport();

        final RelRoot root =
                fixture.convert(
                        "select DEPTNO, count(*) as C, sum(SAL) as S, "
                                + "count(distinct ENAME) as DC "
                                + "from EMP group by DEPTNO");

        final LogicalAggregate aggregate =
                Sql2RelTestSupport.find(root.rel, LogicalAggregate.class);

        assertThat(aggregate).isNotNull();
        assertThat(aggregate.getRowType().getFieldNames())
                .containsExactly("DEPTNO", "C", "S", "DC");
        assertThat(aggregate.getGroupSet().toList()).containsExactly(0);

        assertThat(aggregate.getAggCallList()).hasSize(3);
        final AggregateCall count = aggregate.getAggCallList().get(0);
        assertThat(count.getName()).isEqualTo("C");
        assertThat(count.getAggregation().getKind()).isEqualTo(SqlKind.COUNT);
        assertThat(count.isDistinct()).isFalse();

        final AggregateCall sum = aggregate.getAggCallList().get(1);
        assertThat(sum.getName()).isEqualTo("S");
        assertThat(sum.getAggregation().getKind()).isEqualTo(SqlKind.SUM);
        assertThat(sum.isDistinct()).isFalse();

        final AggregateCall countDistinct = aggregate.getAggCallList().get(2);
        assertThat(countDistinct.getName()).isEqualTo("DC");
        assertThat(countDistinct.getAggregation().getKind()).isEqualTo(SqlKind.COUNT);
        assertThat(countDistinct.isDistinct()).isTrue();
    }

    @Test
    void collapsesDuplicateGroupByExpressions() {
        final Sql2RelTestSupport fixture = new Sql2RelTestSupport();

        final RelRoot root = fixture.convert("select DEPTNO from EMP group by DEPTNO, DEPTNO");

        final LogicalAggregate aggregate =
                Sql2RelTestSupport.find(root.rel, LogicalAggregate.class);

        assertThat(aggregate).isNotNull();
        assertThat(aggregate.getGroupSet().cardinality()).isEqualTo(1);
        assertThat(aggregate.getGroupSets()).hasSize(1);
        assertThat(aggregate.getAggCallList()).isEmpty();
    }

    @Test
    void expandsGroupingSets() {
        final Sql2RelTestSupport fixture = new Sql2RelTestSupport();

        final RelRoot root =
                fixture.convert(
                        "select DEPTNO, count(*) from EMP "
                                + "group by grouping sets ((DEPTNO), ())");

        final LogicalAggregate aggregate =
                Sql2RelTestSupport.find(root.rel, LogicalAggregate.class);

        assertThat(aggregate).isNotNull();
        assertThat(aggregate.getGroupSet().toList()).containsExactly(0);
        assertThat(aggregate.getGroupSets())
                .extracting(ImmutableBitSet::cardinality)
                .containsExactlyInAnyOrder(0, 1);
        assertThat(aggregate.getAggCallList()).hasSize(1);
    }

    @Test
    void havingClauseReferencesAggregateOutput() {
        final Sql2RelTestSupport fixture = new Sql2RelTestSupport();

        final RelRoot root =
                fixture.convert(
                        "select DEPTNO, count(*) as C from EMP "
                                + "group by DEPTNO having count(*) > 1");

        final LogicalFilter filter = Sql2RelTestSupport.find(root.rel, LogicalFilter.class);
        final LogicalAggregate aggregate =
                Sql2RelTestSupport.find(root.rel, LogicalAggregate.class);

        assertThat(filter).isNotNull();
        assertThat(aggregate).isNotNull();
        assertThat(filter.getInput()).isSameAs(aggregate);
        assertThat(filter.getCondition().getKind()).isEqualTo(SqlKind.GREATER_THAN);

        final RexCall condition = (RexCall) filter.getCondition();
        assertThat(condition.getOperands().get(0)).isInstanceOf(RexInputRef.class);
        assertThat(((RexInputRef) condition.getOperands().get(0)).getIndex()).isEqualTo(1);
    }

    @Test
    void expandConfigCreatesCorrelationAndDecorrelateRemovesIt() {
        final Sql2RelTestSupport fixture =
                new Sql2RelTestSupport(SqlToRelConverter.config().withExpand(true));
        final String sql =
                "select ENAME from EMP e where exists "
                        + "(select 1 from DEPT d where d.DEPTNO = e.DEPTNO)";
        final SqlNode query = fixture.validate(sql);

        final RelRoot root = fixture.convert(query);

        assertThat(Sql2RelTestSupport.containsCorrelate(root.rel)).isTrue();

        final RelNode decorrelated = fixture.converter.decorrelate(query, root.rel);

        assertThat(decorrelated).isNotSameAs(root.rel);
        assertThat(Sql2RelTestSupport.containsCorrelate(decorrelated)).isFalse();
        assertThat(decorrelated.getRowType().getFieldNames()).containsExactly("ENAME");
    }

    @Test
    void decorrelateLeavesPlanUntouchedWhenDecorrelationIsDisabled() {
        final Sql2RelTestSupport fixture =
                new Sql2RelTestSupport(
                        SqlToRelConverter.config()
                                .withExpand(true)
                                .withDecorrelationEnabled(false));
        final SqlNode query =
                fixture.validate(
                        "select ENAME from EMP e where exists "
                                + "(select 1 from DEPT d where d.DEPTNO = e.DEPTNO)");
        final RelRoot root = fixture.convert(query);

        final RelNode result = fixture.converter.decorrelate(query, root.rel);

        assertThat(result).isSameAs(root.rel);
    }

    @Test
    void configuredSubQueryConverterIsUsedForNonCorrelatedScalarSubQuery() {
        final Sql2RelTestSupport fixture =
                new Sql2RelTestSupport(SqlToRelConverter.config().withExpand(true));
        final AtomicInteger invocations = new AtomicInteger();
        fixture.converter.setSubQueryConverter(
                new SubQueryConverter() {
                    @Override
                    public boolean canConvertSubQuery() {
                        return true;
                    }

                    @Override
                    public RexNode convertSubQuery(
                            SqlCall call,
                            SqlToRelConverter converter,
                            boolean isExists,
                            boolean explain) {
                        invocations.incrementAndGet();
                        return converter.getRexBuilder().makeNullLiteral(SqlTypeName.INTEGER);
                    }
                });

        final RelRoot root =
                fixture.convert("select EMPNO, (select max(DEPTNO) from DEPT) from EMP");

        assertThat(invocations).hasValue(1);
        assertThat(fixture.converter.getMapConvertedNonCorrSubqs()).hasSize(1);

        final LogicalProject project = Sql2RelTestSupport.find(root.rel, LogicalProject.class);
        final RexNode scalarExpression = project.getProjects().get(1);
        assertThat(scalarExpression).isInstanceOf(RexLiteral.class);
        assertThat(((RexLiteral) scalarExpression).isNull()).isTrue();
        assertThat(scalarExpression.getType().getSqlTypeName()).isEqualTo(SqlTypeName.INTEGER);
    }

    @Test
    void addConvertedNonCorrSubqsExposesAccumulatedMapping() {
        final Sql2RelTestSupport fixture = new Sql2RelTestSupport();
        final SqlNode key = Sql2RelTestSupport.parseExpression("1");
        final RexNode value = fixture.converter.getRexBuilder().makeExactLiteral(BigDecimal.ONE);
        final Map<SqlNode, RexNode> converted = new HashMap<>();
        converted.put(key, value);

        fixture.converter.addConvertedNonCorrSubqs(converted);

        assertThat(fixture.converter.getMapConvertedNonCorrSubqs()).containsEntry(key, value);
    }

    @Test
    void isOrderedDetectsTopLevelOrderBy() {
        assertThat(
                        SqlToRelConverter.isOrdered(
                                Sql2RelTestSupport.parseQuery("select EMPNO from EMP")))
                .isFalse();
        assertThat(
                        SqlToRelConverter.isOrdered(
                                Sql2RelTestSupport.parseQuery(
                                        "select EMPNO from EMP order by EMPNO")))
                .isTrue();
        assertThat(
                        SqlToRelConverter.isOrdered(
                                Sql2RelTestSupport.parseQuery(
                                        "select EMPNO from EMP union "
                                                + "select DEPTNO from DEPT")))
                .isFalse();
    }

    @Test
    void explainParameterCountCanBeReadAndIncremented() {
        final Sql2RelTestSupport fixture =
                new Sql2RelTestSupport(SqlToRelConverter.config().withExplain(true));

        assertThat(fixture.converter.getDynamicParamCountInExplain(false)).isZero();
        assertThat(fixture.converter.getDynamicParamCountInExplain(true)).isZero();
        assertThat(fixture.converter.getDynamicParamCountInExplain(false)).isEqualTo(1);

        fixture.converter.setDynamicParamCountInExplain(7);

        assertThat(fixture.converter.getDynamicParamCountInExplain(false)).isEqualTo(7);
    }

    @Test
    void convertsSetOperation() {
        final Sql2RelTestSupport fixture = new Sql2RelTestSupport();

        final RelRoot root =
                fixture.convert("select EMPNO from EMP union all select DEPTNO from DEPT");

        assertThat(root.kind).isEqualTo(SqlKind.UNION);
        assertThat(root.rel).isInstanceOf(LogicalUnion.class);
        assertThat(((LogicalUnion) root.rel).all).isTrue();
        assertThat(root.rel.getInputs()).hasSize(2);
        assertThat(root.rel.getRowType().getFieldNames()).containsExactly("EMPNO");
    }

    @Test
    void convertsValuesClause() {
        final Sql2RelTestSupport fixture = new Sql2RelTestSupport();

        final RelRoot root = fixture.convert("values (1, 'a'), (2, 'b')");

        assertThat(root.kind).isEqualTo(SqlKind.VALUES);
        assertThat(root.rel).isInstanceOf(LogicalValues.class);
        assertThat(((LogicalValues) root.rel).getTuples()).hasSize(2);
        assertThat(root.rel.getRowType().getFieldNames()).containsExactly("EXPR$0", "EXPR$1");
    }

    @Test
    void convertsWithClause() {
        final Sql2RelTestSupport fixture = new Sql2RelTestSupport();

        final RelRoot root =
                fixture.convert("with t as (select EMPNO from EMP) select EMPNO from t");

        assertThat(root.kind).isEqualTo(SqlKind.WITH);
        assertThat(root.rel.getRowType().getFieldNames()).containsExactly("EMPNO");
        final LogicalTableScan scan = Sql2RelTestSupport.find(root.rel, LogicalTableScan.class);
        assertThat(scan).isNotNull();
        assertThat(scan.getTable().getQualifiedName()).containsExactly(Sql2RelTestSupport.EMP);
    }

    @Test
    void isTrimUnusedFieldsReflectsConfiguration() {
        final Sql2RelTestSupport defaults = new Sql2RelTestSupport();
        final Sql2RelTestSupport trimming =
                new Sql2RelTestSupport(SqlToRelConverter.config().withTrimUnusedFields(true));

        assertThat(defaults.converter.isTrimUnusedFields()).isFalse();
        assertThat(trimming.converter.isTrimUnusedFields()).isTrue();
        assertThat(trimming.converter.config.isTrimUnusedFields()).isTrue();
    }

    @Test
    void exposesClusterAndRexBuilder() {
        final Sql2RelTestSupport fixture = new Sql2RelTestSupport();

        assertThat(fixture.converter.getCluster()).isSameAs(fixture.cluster);
        assertThat(fixture.converter.getRexBuilder()).isSameAs(fixture.cluster.getRexBuilder());
    }
}

