package org.apache.flink.table.data;

import org.apache.flink.table.api.TableException;
import org.apache.flink.table.data.binary.BinaryStringData;
import org.apache.flink.table.data.binary.BinaryStringDataUtil;

import org.junit.jupiter.api.Test;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.time.DateTimeException;
import java.time.LocalDateTime;
import java.time.ZoneOffset;
import java.util.Arrays;
import java.util.TimeZone;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

/** Tests for {@link BinaryStringDataUtil}. */
class BinaryStringDataUtilTest {

    private static BinaryStringData bs(String value) {
        return BinaryStringData.fromString(value);
    }

    @Test
    void testConstants() {
        assertThat(BinaryStringDataUtil.NULL_STRING.toString()).isEqualTo("NULL");
        assertThat(BinaryStringDataUtil.TRUE_STRING.toString()).isEqualTo("TRUE");
        assertThat(BinaryStringDataUtil.FALSE_STRING.toString()).isEqualTo("FALSE");
        assertThat(BinaryStringDataUtil.EMPTY_STRING_ARRAY).isEmpty();
    }

    @Test
    void testSplitByWholeSeparatorPreserveAllTokens() {
        assertThat(
                        toStrings(
                                BinaryStringDataUtil.splitByWholeSeparatorPreserveAllTokens(
                                        bs("ab:cd:ef"), bs(":"))))
                .containsExactly("ab", "cd", "ef");

        assertThat(
                        toStrings(
                                BinaryStringDataUtil.splitByWholeSeparatorPreserveAllTokens(
                                        bs("ab-!-cd-!-ef"), bs("-!-"))))
                .containsExactly("ab", "cd", "ef");

        // Adjacent separators produce empty tokens.
        assertThat(
                        toStrings(
                                BinaryStringDataUtil.splitByWholeSeparatorPreserveAllTokens(
                                        bs("ab::cd"), bs(":"))))
                .containsExactly("ab", "", "cd");

        // A null or empty separator splits on whitespace.
        assertThat(
                        toStrings(
                                BinaryStringDataUtil.splitByWholeSeparatorPreserveAllTokens(
                                        bs("ab   de fg"), null)))
                .containsExactly("ab", "", "", "de", "fg");
        assertThat(
                        toStrings(
                                BinaryStringDataUtil.splitByWholeSeparatorPreserveAllTokens(
                                        bs("ab de fg"), bs(""))))
                .containsExactly("ab", "de", "fg");

        // Empty input yields an empty array.
        assertThat(BinaryStringDataUtil.splitByWholeSeparatorPreserveAllTokens(bs(""), bs(":")))
                .isEmpty();

        // Leading and trailing separators yield empty tokens.
        assertThat(
                        toStrings(
                                BinaryStringDataUtil.splitByWholeSeparatorPreserveAllTokens(
                                        bs(":ab:"), bs(":"))))
                .containsExactly("", "ab", "");
    }

    @Test
    void testToBoolean() {
        for (String value : Arrays.asList("t", "true", "y", "yes", "1", "TRUE", "True", "YES")) {
            assertThat(BinaryStringDataUtil.toBoolean(bs(value)))
                    .as("toBoolean(%s)", value)
                    .isTrue();
        }
        for (String value : Arrays.asList("f", "false", "n", "no", "0", "FALSE", "False", "NO")) {
            assertThat(BinaryStringDataUtil.toBoolean(bs(value)))
                    .as("toBoolean(%s)", value)
                    .isFalse();
        }

        assertThatThrownBy(() -> BinaryStringDataUtil.toBoolean(bs("maybe")))
                .isInstanceOf(TableException.class);
        assertThatThrownBy(() -> BinaryStringDataUtil.toBoolean(bs("")))
                .isInstanceOf(TableException.class);
    }

    @Test
    void testHash() throws NoSuchAlgorithmException {
        String expected = "900150983cd24fb0d6963f7d28e17f72";

        assertThat(
                        BinaryStringDataUtil.hash(bs("abc"), MessageDigest.getInstance("MD5"))
                                .toString())
                .isEqualTo(expected);
        assertThat(
                        BinaryStringDataUtil.hash(
                                        "abc".getBytes(StandardCharsets.UTF_8),
                                        MessageDigest.getInstance("MD5"))
                                .toString())
                .isEqualTo(expected);
        assertThat(BinaryStringDataUtil.hash(bs("abc"), "MD5").toString()).isEqualTo(expected);

        assertThatThrownBy(() -> BinaryStringDataUtil.hash(bs("abc"), "not-an-algorithm"))
                .isInstanceOf(NoSuchAlgorithmException.class);
    }

    @Test
    void testToDecimal() {
        DecimalData data = BinaryStringDataUtil.toDecimal(bs("123.45"), 5, 2);
        assertThat(data.toBigDecimal()).isEqualByComparingTo("123.45");
        assertThat(data.precision()).isEqualTo(5);
        assertThat(data.scale()).isEqualTo(2);

        assertThat(BinaryStringDataUtil.toDecimal(bs("  12.5  "), 5, 2).toBigDecimal())
                .isEqualByComparingTo("12.50");
        assertThat(BinaryStringDataUtil.toDecimal(bs("-1.5"), 5, 2).toBigDecimal())
                .isEqualByComparingTo("-1.50");
        // Exponential notation.
        assertThat(BinaryStringDataUtil.toDecimal(bs("1e2"), 5, 2).toBigDecimal())
                .isEqualByComparingTo("100.00");
        // Large precision uses the BigDecimal code path.
        assertThat(
                        BinaryStringDataUtil.toDecimal(bs("123456789012345678.99"), 20, 2)
                                .toBigDecimal())
                .isEqualByComparingTo("123456789012345678.99");

        assertThatThrownBy(() -> BinaryStringDataUtil.toDecimal(bs("12345"), 2, 0))
                .isInstanceOf(NumberFormatException.class);
        assertThatThrownBy(() -> BinaryStringDataUtil.toDecimal(bs("   "), 5, 2))
                .isInstanceOf(NumberFormatException.class);
        assertThatThrownBy(() -> BinaryStringDataUtil.toDecimal(bs("+"), 5, 2))
                .isInstanceOf(NumberFormatException.class);
        assertThatThrownBy(() -> BinaryStringDataUtil.toDecimal(bs("1.2.3"), 5, 2))
                .isInstanceOf(NumberFormatException.class);
    }

    @Test
    void testToLong() {
        assertThat(BinaryStringDataUtil.toLong(bs("0"))).isZero();
        assertThat(BinaryStringDataUtil.toLong(bs("123"))).isEqualTo(123L);
        assertThat(BinaryStringDataUtil.toLong(bs("+42"))).isEqualTo(42L);
        assertThat(BinaryStringDataUtil.toLong(bs("-9223372036854775808")))
                .isEqualTo(Long.MIN_VALUE);
        assertThat(BinaryStringDataUtil.toLong(bs("9223372036854775807")))
                .isEqualTo(Long.MAX_VALUE);
        // The fractional part is only validated and then truncated.
        assertThat(BinaryStringDataUtil.toLong(bs("123.99"))).isEqualTo(123L);
        assertThat(BinaryStringDataUtil.toLong(bs("-123.99"))).isEqualTo(-123L);

        assertThatThrownBy(() -> BinaryStringDataUtil.toLong(bs("")))
                .isInstanceOf(NumberFormatException.class);
        assertThatThrownBy(() -> BinaryStringDataUtil.toLong(bs("+")))
                .isInstanceOf(NumberFormatException.class);
        assertThatThrownBy(() -> BinaryStringDataUtil.toLong(bs("12a")))
                .isInstanceOf(NumberFormatException.class);
        assertThatThrownBy(() -> BinaryStringDataUtil.toLong(bs("9223372036854775808")))
                .isInstanceOf(NumberFormatException.class);
        assertThatThrownBy(() -> BinaryStringDataUtil.toLong(bs("1.2.3")))
                .isInstanceOf(NumberFormatException.class);
    }

    @Test
    void testToIntShortAndByte() {
        assertThat(BinaryStringDataUtil.toInt(bs("2147483647"))).isEqualTo(Integer.MAX_VALUE);
        assertThat(BinaryStringDataUtil.toInt(bs("-2147483648"))).isEqualTo(Integer.MIN_VALUE);
        assertThat(BinaryStringDataUtil.toInt(bs("123.9"))).isEqualTo(123);
        assertThatThrownBy(() -> BinaryStringDataUtil.toInt(bs("2147483648")))
                .isInstanceOf(NumberFormatException.class);
        assertThatThrownBy(() -> BinaryStringDataUtil.toInt(bs("12x")))
                .isInstanceOf(NumberFormatException.class);

        assertThat(BinaryStringDataUtil.toShort(bs("32767"))).isEqualTo(Short.MAX_VALUE);
        assertThat(BinaryStringDataUtil.toShort(bs("-32768"))).isEqualTo(Short.MIN_VALUE);
        assertThatThrownBy(() -> BinaryStringDataUtil.toShort(bs("32768")))
                .isInstanceOf(NumberFormatException.class);

        assertThat(BinaryStringDataUtil.toByte(bs("127"))).isEqualTo(Byte.MAX_VALUE);
        assertThat(BinaryStringDataUtil.toByte(bs("-128"))).isEqualTo(Byte.MIN_VALUE);
        assertThatThrownBy(() -> BinaryStringDataUtil.toByte(bs("128")))
                .isInstanceOf(NumberFormatException.class);
    }

    @Test
    void testToDoubleAndFloat() {
        assertThat(BinaryStringDataUtil.toDouble(bs("1.5"))).isEqualTo(1.5d);
        assertThat(BinaryStringDataUtil.toDouble(bs("1e3"))).isEqualTo(1000d);
        assertThat(BinaryStringDataUtil.toDouble(bs("inf"))).isEqualTo(Double.POSITIVE_INFINITY);
        assertThat(BinaryStringDataUtil.toDouble(bs("-Infinity")))
                .isEqualTo(Double.NEGATIVE_INFINITY);
        assertThat(BinaryStringDataUtil.toDouble(bs("nan"))).isNaN();
        assertThatThrownBy(() -> BinaryStringDataUtil.toDouble(bs("abc")))
                .isInstanceOf(NumberFormatException.class);

        assertThat(BinaryStringDataUtil.toFloat(bs("1.5"))).isEqualTo(1.5f);
        assertThat(BinaryStringDataUtil.toFloat(bs("nan"))).isNaN();
        assertThatThrownBy(() -> BinaryStringDataUtil.toFloat(bs("abc")))
                .isInstanceOf(NumberFormatException.class);
    }

    @Test
    void testToDate() {
        assertThat(BinaryStringDataUtil.toDate(bs("1970-01-01"))).isZero();
        assertThat(BinaryStringDataUtil.toDate(bs("2021-01-01"))).isEqualTo(18628);
        assertThatThrownBy(() -> BinaryStringDataUtil.toDate(bs("not-a-date")))
                .isInstanceOf(DateTimeException.class);
    }

    @Test
    void testToTime() {
        assertThat(BinaryStringDataUtil.toTime(bs("12:34:56"), 3)).isEqualTo(45_296_000);
        assertThat(BinaryStringDataUtil.toTime(bs("12:34:56.789"), 3)).isEqualTo(45_296_789);
        assertThat(BinaryStringDataUtil.toTime(bs("12:34:56.789"), 0)).isEqualTo(45_296_000);
        assertThatThrownBy(() -> BinaryStringDataUtil.toTime(bs("not-a-time"), 3))
                .isInstanceOf(DateTimeException.class);
    }

    @Test
    void testToTimestamp() {
        TimestampData timestamp =
                BinaryStringDataUtil.toTimestamp(bs("2021-01-01 12:34:56.123456"), 6);
        assertThat(timestamp.toLocalDateTime())
                .isEqualTo(LocalDateTime.of(2021, 1, 1, 12, 34, 56, 123_456_000));

        TimestampData withZone =
                BinaryStringDataUtil.toTimestamp(
                        bs("2021-01-01 12:34:56"), 3, TimeZone.getTimeZone("UTC"));
        assertThat(withZone.toInstant())
                .isEqualTo(LocalDateTime.of(2021, 1, 1, 12, 34, 56).toInstant(ZoneOffset.UTC));
    }

    @Test
    void testSubstringSql() {
        assertThat(BinaryStringDataUtil.substringSQL(bs("hello"), 2).toString()).isEqualTo("ello");
        assertThat(BinaryStringDataUtil.substringSQL(bs("hello"), -2).toString()).isEqualTo("lo");
        assertThat(BinaryStringDataUtil.substringSQL(bs("hello"), 0).toString()).isEqualTo("hello");
        assertThat(BinaryStringDataUtil.substringSQL(bs("hello"), 10).toString()).isEmpty();
        assertThat(BinaryStringDataUtil.substringSQL(bs("hello"), 2, 2).toString()).isEqualTo("el");
        assertThat(BinaryStringDataUtil.substringSQL(bs("hello"), 2, 0).toString()).isEmpty();
        assertThat(BinaryStringDataUtil.substringSQL(bs("hello"), 2, -1)).isNull();
        assertThat(BinaryStringDataUtil.substringSQL(bs(""), 1).toString()).isEmpty();
        // Positions and lengths are expressed in characters, not bytes.
        assertThat(BinaryStringDataUtil.substringSQL(bs("你好世界"), 2, 2).toString()).isEqualTo("好世");
        assertThat(BinaryStringDataUtil.substringSQL(bs("你好世界"), -2).toString()).isEqualTo("世界");
    }

    @Test
    void testConcat() {
        assertThat(BinaryStringDataUtil.concat(bs("a"), bs("b"), bs("c")).toString())
                .isEqualTo("abc");
        assertThat(BinaryStringDataUtil.concat().toString()).isEmpty();
        assertThat(BinaryStringDataUtil.concat(bs("a"), null, bs("c"))).isNull();
        assertThat(BinaryStringDataUtil.concat(Arrays.asList(bs("a"), bs("b"))).toString())
                .isEqualTo("ab");
    }

    @Test
    void testConcatWs() {
        assertThat(BinaryStringDataUtil.concatWs(bs(","), bs("a"), null, bs("c")).toString())
                .isEqualTo("a,c");
        assertThat(BinaryStringDataUtil.concatWs(bs(","), null, null).toString()).isEmpty();
        assertThat(BinaryStringDataUtil.concatWs(bs(",")).toString()).isEmpty();
        assertThat(BinaryStringDataUtil.concatWs(null, bs("a"), bs("b"))).isNull();
        assertThat(BinaryStringDataUtil.concatWs(bs("--"), bs("a"), bs("b")).toString())
                .isEqualTo("a--b");
        // Empty strings are not skipped.
        assertThat(BinaryStringDataUtil.concatWs(bs(","), bs(""), bs("a")).toString())
                .isEqualTo(",a");
    }

    @Test
    void testReverse() {
        assertThat(BinaryStringDataUtil.reverse(bs("abc")).toString()).isEqualTo("cba");
        assertThat(BinaryStringDataUtil.reverse(bs("")).toString()).isEmpty();
        assertThat(BinaryStringDataUtil.reverse(bs("你好")).toString()).isEqualTo("好你");
    }

    @Test
    void testTrim() {
        assertThat(BinaryStringDataUtil.trim(bs("  hello  "), bs(" ")).toString())
                .isEqualTo("hello");
        assertThat(BinaryStringDataUtil.trim(bs("xxhelloxx"), bs("x")).toString())
                .isEqualTo("hello");
        assertThat(BinaryStringDataUtil.trim(bs("xxxx"), bs("x")).toString()).isEmpty();
        assertThat(BinaryStringDataUtil.trim(bs("  hello  "), null)).isNull();

        assertThat(BinaryStringDataUtil.trimLeft(bs("  hello  ")).toString()).isEqualTo("hello  ");
        assertThat(BinaryStringDataUtil.trimRight(bs("  hello  ")).toString()).isEqualTo("  hello");
        assertThat(BinaryStringDataUtil.trimLeft(bs("xxhelloxx"), bs("x")).toString())
                .isEqualTo("helloxx");
        assertThat(BinaryStringDataUtil.trimRight(bs("xxhelloxx"), bs("x")).toString())
                .isEqualTo("xxhello");
        assertThat(BinaryStringDataUtil.trimLeft(bs("  hello  "), null)).isNull();
        assertThat(BinaryStringDataUtil.trimRight(bs("  hello  "), null)).isNull();
    }

    @Test
    void testTrimWithLeadingAndTrailingFlags() {
        BinaryStringData value = bs("xhellox");
        BinaryStringData seek = bs("x");

        assertThat(BinaryStringDataUtil.trim(value, true, false, seek).toString())
                .isEqualTo("hellox");
        assertThat(BinaryStringDataUtil.trim(value, false, true, seek).toString())
                .isEqualTo("xhello");
        assertThat(BinaryStringDataUtil.trim(value, true, true, seek).toString())
                .isEqualTo("hello");
        assertThat(BinaryStringDataUtil.trim(value, false, false, seek)).isSameAs(value);
        assertThat(BinaryStringDataUtil.trim(value, true, true, null)).isNull();
    }

    @Test
    void testIsEmptyIsSpaceStringAndSafeToString() {
        assertThat(BinaryStringDataUtil.isEmpty(bs(""))).isTrue();
        assertThat(BinaryStringDataUtil.isEmpty(bs(" "))).isFalse();
        assertThat(BinaryStringDataUtil.isEmpty(bs("x"))).isFalse();

        assertThat(BinaryStringDataUtil.isSpaceString(bs(" "))).isTrue();
        assertThat(BinaryStringDataUtil.isSpaceString(bs("x"))).isFalse();

        assertThat(BinaryStringDataUtil.safeToString(null)).isNull();
        assertThat(BinaryStringDataUtil.safeToString(bs("x"))).isEqualTo("x");
    }

    private static String[] toStrings(BinaryStringData[] values) {
        String[] result = new String[values.length];
        for (int i = 0; i < values.length; i++) {
            result[i] = values[i].toString();
        }
        return result;
    }
}
