/** Tests for {@link DataFormatConverters}. */
class DataFormatConvertersTest {

    @SuppressWarnings("unchecked")
    private static <I, E> DataFormatConverter<I, E> converter(DataType dataType) {
        return (DataFormatConverter<I, E>) DataFormatConverters.getConverterForDataType(dataType);
    }

    @Test
    void testResolverReturnsExpectedConvertersForSimpleTypes() {
        assertThat(DataFormatConverters.getConverterForDataType(DataTypes.BOOLEAN()))
                .isSameAs(BooleanConverter.INSTANCE);
        assertThat(DataFormatConverters.getConverterForDataType(DataTypes.TINYINT()))
                .isSameAs(ByteConverter.INSTANCE);
        assertThat(DataFormatConverters.getConverterForDataType(DataTypes.SMALLINT()))
                .isSameAs(ShortConverter.INSTANCE);
        assertThat(DataFormatConverters.getConverterForDataType(DataTypes.INT()))
                .isSameAs(IntConverter.INSTANCE);
        assertThat(DataFormatConverters.getConverterForDataType(DataTypes.BIGINT()))
                .isSameAs(LongConverter.INSTANCE);
        assertThat(DataFormatConverters.getConverterForDataType(DataTypes.FLOAT()))
                .isSameAs(FloatConverter.INSTANCE);
        assertThat(DataFormatConverters.getConverterForDataType(DataTypes.DOUBLE()))
                .isSameAs(DoubleConverter.INSTANCE);
        assertThat(DataFormatConverters.getConverterForDataType(DataTypes.STRING()))
                .isSameAs(StringConverter.INSTANCE);
        assertThat(
                        DataFormatConverters.getConverterForDataType(
                                DataTypes.STRING().bridgedTo(StringData.class)))
                .isSameAs(StringDataConverter.INSTANCE);
        assertThat(DataFormatConverters.getConverterForDataType(DataTypes.BINARY(10)))
                .isSameAs(PrimitiveByteArrayConverter.INSTANCE);
        assertThat(DataFormatConverters.getConverterForDataType(DataTypes.VARBINARY(10)))
                .isSameAs(PrimitiveByteArrayConverter.INSTANCE);
        assertThat(DataFormatConverters.getConverterForDataType(DataTypes.DATE()))
                .isSameAs(LocalDateConverter.INSTANCE);
        assertThat(DataFormatConverters.getConverterForDataType(DataTypes.TIME()))
                .isSameAs(LocalTimeConverter.INSTANCE);
        assertThat(DataFormatConverters.getConverterForDataType(DataTypes.TIMESTAMP(3)))
                .isInstanceOf(LocalDateTimeConverter.class);
        assertThat(DataFormatConverters.getConverterForDataType(DataTypes.TIMESTAMP_LTZ(3)))
                .isInstanceOf(InstantConverter.class);
        assertThat(DataFormatConverters.getConverterForDataType(DataTypes.BITMAP()))
                .isSameAs(BitmapConverter.INSTANCE);
    }

    @Test
    void testResolverForLegacyJavaTypes() {
        assertThat(
                        DataFormatConverters.getConverterForDataType(
                                DataTypes.DATE().bridgedTo(java.sql.Date.class)))
                .isSameAs(DateConverter.INSTANCE);
        assertThat(
                        DataFormatConverters.getConverterForDataType(
                                DataTypes.DATE().bridgedTo(Integer.class)))
                .isSameAs(IntConverter.INSTANCE);
        assertThat(
                        DataFormatConverters.getConverterForDataType(
                                DataTypes.TIMESTAMP(3).bridgedTo(Timestamp.class)))
                .isInstanceOf(DataFormatConverters.TimestampConverter.class);
        assertThat(
                        DataFormatConverters.getConverterForDataType(
                                DataTypes.TIMESTAMP(3).bridgedTo(TimestampData.class)))
                .isInstanceOf(TimestampDataConverter.class);
        assertThat(
                        DataFormatConverters.getConverterForDataType(
                                DataTypes.TIMESTAMP_LTZ(3).bridgedTo(Long.class)))
                .isInstanceOf(LongTimestampDataConverter.class);
        assertThat(
                        DataFormatConverters.getConverterForDataType(
                                DataTypes.TIMESTAMP_LTZ(3).bridgedTo(Timestamp.class)))
                .isInstanceOf(DataFormatConverters.TimestampLtzConverter.class);
    }

    @Test
    void testResolverForContainers() {
        assertThat(
                        DataFormatConverters.getConverterForDataType(
                                DataTypes.ARRAY(DataTypes.INT()).bridgedTo(int[].class)))
                .isSameAs(PrimitiveIntArrayConverter.INSTANCE);
        assertThat(
                        DataFormatConverters.getConverterForDataType(
                                DataTypes.ARRAY(DataTypes.BOOLEAN()).bridgedTo(boolean[].class)))
                .isSameAs(PrimitiveBooleanArrayConverter.INSTANCE);
        assertThat(
                        DataFormatConverters.getConverterForDataType(
                                DataTypes.ARRAY(DataTypes.SMALLINT()).bridgedTo(short[].class)))
                .isSameAs(PrimitiveShortArrayConverter.INSTANCE);
        assertThat(
                        DataFormatConverters.getConverterForDataType(
                                DataTypes.ARRAY(DataTypes.BIGINT()).bridgedTo(long[].class)))
                .isSameAs(PrimitiveLongArrayConverter.INSTANCE);
        assertThat(
                        DataFormatConverters.getConverterForDataType(
                                DataTypes.ARRAY(DataTypes.FLOAT()).bridgedTo(float[].class)))
                .isSameAs(PrimitiveFloatArrayConverter.INSTANCE);
        assertThat(
                        DataFormatConverters.getConverterForDataType(
                                DataTypes.ARRAY(DataTypes.DOUBLE()).bridgedTo(double[].class)))
                .isSameAs(PrimitiveDoubleArrayConverter.INSTANCE);
        assertThat(
                        DataFormatConverters.getConverterForDataType(
                                DataTypes.ARRAY(DataTypes.STRING()).bridgedTo(ArrayData.class)))
                .isSameAs(ArrayDataConverter.INSTANCE);
        assertThat(
                        DataFormatConverters.getConverterForDataType(
                                DataTypes.MAP(DataTypes.STRING(), DataTypes.INT())
                                        .bridgedTo(MapData.class)))
                .isSameAs(MapDataConverter.INSTANCE);
        assertThat(
                        DataFormatConverters.getConverterForDataType(
                                DataTypes.ROW(DataTypes.FIELD("a", DataTypes.INT()))
                                        .bridgedTo(RowData.class)))
                .isInstanceOf(RowDataConverter.class);
        assertThat(
                        DataFormatConverters.getConverterForDataType(
                                DataTypes.ROW(DataTypes.FIELD("a", DataTypes.INT()))))
                .isInstanceOf(RowConverter.class);
        assertThat(
                        DataFormatConverters.getConverterForDataType(
                                DataTypes.MAP(DataTypes.STRING(), DataTypes.INT())))
                .isInstanceOf(DataFormatConverters.MapConverter.class);
        assertThat(DataFormatConverters.getConverterForDataType(DataTypes.DECIMAL(10, 2)))
                .isInstanceOf(BigDecimalConverter.class);
        assertThat(
                        DataFormatConverters.getConverterForDataType(
                                DataTypes.DECIMAL(10, 2).bridgedTo(DecimalData.class)))
                .isInstanceOf(DecimalDataConverter.class);
    }

    @Test
    void testUnsupportedDataTypeThrows() {
        assertThatThrownBy(() -> DataFormatConverters.getConverterForDataType(DataTypes.NULL()))
                .isInstanceOf(RuntimeException.class)
                .hasMessageContaining("Not support dataType");
        assertThatThrownBy(
                        () ->
                                DataFormatConverters.getConverterForDataType(
                                        DataTypes.INTERVAL(DataTypes.YEAR())))
                .isInstanceOf(RuntimeException.class)
                .hasMessageContaining("Not support dataType");
    }

    @Test
    void testStringConversion() {
        DataFormatConverter<StringData, String> converter = converter(DataTypes.STRING());

        StringData internal = converter.toInternal("hello");
        assertThat(internal.toString()).isEqualTo("hello");
        assertThat(converter.toExternal(internal)).isEqualTo("hello");

        GenericRowData row = GenericRowData.of(internal);
        assertThat(converter.toExternal(row, 0)).isEqualTo("hello");

        assertThat(converter.toInternal(null)).isNull();
        assertThat(converter.toExternal((StringData) null)).isNull();
        assertThat(converter.toExternal(GenericRowData.of((Object) null), 0)).isNull();
    }

    @Test
    void testDecimalConversion() {
        DataFormatConverter<DecimalData, BigDecimal> converter = converter(DataTypes.DECIMAL(5, 2));

        BigDecimal value = new BigDecimal("1.23");
        DecimalData internal = converter.toInternal(value);
        assertThat(internal.toBigDecimal()).isEqualByComparingTo("1.23");
        assertThat(converter.toExternal(internal)).isEqualByComparingTo("1.23");

        GenericRowData row = GenericRowData.of(internal);
        assertThat(converter.toExternal(row, 0)).isEqualByComparingTo("1.23");
        assertThat(converter.toInternal(null)).isNull();
        assertThat(converter.toExternal((DecimalData) null)).isNull();
    }

    @Test
    void testIdentityConvertersForInternalTypes() {
        DataFormatConverter<StringData, StringData> stringDataConverter =
                converter(DataTypes.STRING().bridgedTo(StringData.class));
        StringData value = StringData.fromString("x");
        assertThat(stringDataConverter.toInternal(value)).isSameAs(value);
        assertThat(stringDataConverter.toExternal(value)).isSameAs(value);

        DataFormatConverter<DecimalData, DecimalData> decimalConverter =
                converter(DataTypes.DECIMAL(5, 2).bridgedTo(DecimalData.class));
        DecimalData decimal = DecimalData.fromBigDecimal(new BigDecimal("1.50"), 5, 2);
        assertThat(decimalConverter.toInternal(decimal)).isSameAs(decimal);
        assertThat(decimalConverter.toExternal(decimal)).isSameAs(decimal);

        Bitmap bitmap = RoaringBitmapData.fromArray(new int[] {1, 2});
        DataFormatConverter<Bitmap, Bitmap> bitmapConverter = converter(DataTypes.BITMAP());
        assertThat(bitmapConverter.toInternal(bitmap)).isSameAs(bitmap);
        assertThat(bitmapConverter.toExternal(bitmap)).isSameAs(bitmap);
    }

    @Test
    void testDateAndTimeConversions() {
        LocalDate date = LocalDate.of(2021, 1, 1);
        DataFormatConverter<Integer, LocalDate> dateConverter = converter(DataTypes.DATE());
        Integer internalDate = dateConverter.toInternal(date);
        assertThat(dateConverter.toExternal(internalDate)).isEqualTo(date);
        assertThat(dateConverter.toExternal(GenericRowData.of(internalDate), 0)).isEqualTo(date);

        LocalTime time = LocalTime.of(12, 34, 56, 123_000_000);
        DataFormatConverter<Integer, LocalTime> timeConverter = converter(DataTypes.TIME());
        Integer internalTime = timeConverter.toInternal(time);
        assertThat(timeConverter.toExternal(internalTime)).isEqualTo(time);

        LocalDateTime dateTime = LocalDateTime.of(2021, 1, 1, 12, 34, 56, 123_456_000);
        DataFormatConverter<TimestampData, LocalDateTime> dateTimeConverter =
                converter(DataTypes.TIMESTAMP(6));
        TimestampData internalDateTime = dateTimeConverter.toInternal(dateTime);
        assertThat(dateTimeConverter.toExternal(internalDateTime)).isEqualTo(dateTime);

        Instant instant = Instant.ofEpochMilli(1_600_000_000_123L);
        DataFormatConverter<TimestampData, Instant> instantConverter =
                converter(DataTypes.TIMESTAMP_LTZ(3));
        TimestampData internalInstant = instantConverter.toInternal(instant);
        assertThat(instantConverter.toExternal(internalInstant)).isEqualTo(instant);

        Timestamp timestamp = Timestamp.valueOf("2021-01-01 12:34:56.123");
        DataFormatConverter<TimestampData, Timestamp> timestampConverter =
                converter(DataTypes.TIMESTAMP(3).bridgedTo(Timestamp.class));
        assertThat(timestampConverter.toExternal(timestampConverter.toInternal(timestamp)))
                .isEqualTo(timestamp);

        DataFormatConverter<TimestampData, Long> longConverter =
                converter(DataTypes.TIMESTAMP_LTZ(3).bridgedTo(Long.class));
        assertThat(longConverter.toExternal(longConverter.toInternal(1_600_000_000_123L)))
                .isEqualTo(1_600_000_000_123L);
    }

    @Test
    void testPrimitiveArrayConversions() {
        DataFormatConverter<ArrayData, int[]> intConverter =
                converter(DataTypes.ARRAY(DataTypes.INT()).bridgedTo(int[].class));
        int[] ints = new int[] {1, 2, 3};
        ArrayData intArray = intConverter.toInternal(ints);
        assertThat(intArray.toIntArray()).containsExactly(1, 2, 3);
        assertThat(intConverter.toExternal(intArray)).containsExactly(1, 2, 3);
        assertThat(intConverter.toExternal(GenericRowData.of(intArray), 0))
                .containsExactly(1, 2, 3);

        DataFormatConverter<ArrayData, boolean[]> booleanConverter =
                converter(DataTypes.ARRAY(DataTypes.BOOLEAN()).bridgedTo(boolean[].class));
        ArrayData booleans = booleanConverter.toInternal(new boolean[] {true, false});
        assertThat(booleanConverter.toExternal(booleans)).containsExactly(true, false);

        DataFormatConverter<ArrayData, short[]> shortConverter =
                converter(DataTypes.ARRAY(DataTypes.SMALLINT()).bridgedTo(short[].class));
        ArrayData shorts = shortConverter.toInternal(new short[] {1, 2});
        assertThat(shortConverter.toExternal(shorts)).containsExactly((short) 1, (short) 2);

        DataFormatConverter<ArrayData, long[]> longConverter =
                converter(DataTypes.ARRAY(DataTypes.BIGINT()).bridgedTo(long[].class));
        ArrayData longs = longConverter.toInternal(new long[] {1L, 2L});
        assertThat(longConverter.toExternal(longs)).containsExactly(1L, 2L);

        DataFormatConverter<ArrayData, float[]> floatConverter =
                converter(DataTypes.ARRAY(DataTypes.FLOAT()).bridgedTo(float[].class));
        ArrayData floats = floatConverter.toInternal(new float[] {1.5f});
        assertThat(floatConverter.toExternal(floats)).containsExactly(1.5f);

        DataFormatConverter<ArrayData, double[]> doubleConverter =
                converter(DataTypes.ARRAY(DataTypes.DOUBLE()).bridgedTo(double[].class));
        ArrayData doubles = doubleConverter.toInternal(new double[] {1.5d});
        assertThat(doubleConverter.toExternal(doubles)).containsExactly(1.5d);
    }

    @Test
    void testByteArrayConversionIsIdentity() {
        DataFormatConverter<byte[], byte[]> converter = converter(DataTypes.BINARY(3));
        byte[] bytes = new byte[] {1, 2, 3};
        assertThat(converter.toInternal(bytes)).isSameAs(bytes);
        assertThat(converter.toExternal(bytes)).isSameAs(bytes);
        assertThat(converter.toExternal(GenericRowData.of(bytes), 0)).isSameAs(bytes);
    }

    @Test
    void testObjectArrayConversion() {
        DataFormatConverter<ArrayData, String[]> converter =
                converter(DataTypes.ARRAY(DataTypes.STRING()));

        String[] values = new String[] {"a", null, "c"};
        ArrayData internal = converter.toInternal(values);
        assertThat(converter.toExternal(internal)).containsExactly("a", null, "c");
        assertThat(converter.toExternal(GenericRowData.of(internal), 0))
                .containsExactly("a", null, "c");
        assertThat(converter.toInternal(null)).isNull();
    }

    @Test
    void testMapAndMultisetConversion() {
        DataFormatConverter<MapData, Map> converter =
                converter(DataTypes.MAP(DataTypes.STRING(), DataTypes.INT()));

        Map<String, Integer> values = new HashMap<>();
        values.put("a", 1);
        values.put("b", 2);
        MapData internal = converter.toInternal(values);
        assertThat(internal.size()).isEqualTo(2);
        assertThat(converter.toExternal(internal)).isEqualTo(values);
        assertThat(converter.toExternal(GenericRowData.of(internal), 0)).isEqualTo(values);
        assertThat(converter.toInternal(null)).isNull();

        DataFormatConverter<MapData, Map> multisetConverter =
                converter(DataTypes.MULTISET(DataTypes.STRING()));
        Map<String, Integer> multiset = new HashMap<>();
        multiset.put("x", 3);
        MapData internalMultiset = multisetConverter.toInternal(multiset);
        assertThat(multisetConverter.toExternal(internalMultiset)).isEqualTo(multiset);
    }

    @Test
    void testRowConversion() {
        DataType rowType =
                DataTypes.ROW(
                        DataTypes.FIELD("id", DataTypes.INT()),
                        DataTypes.FIELD("name", DataTypes.STRING()));
        DataFormatConverter<RowData, Row> converter = converter(rowType);

        Row row = new Row(RowKind.UPDATE_AFTER, 2);
        row.setField(0, 7);
        row.setField(1, "seven");

        RowData internal = converter.toInternal(row);
        assertThat(internal.getRowKind()).isEqualTo(RowKind.UPDATE_AFTER);
        assertThat(internal.getInt(0)).isEqualTo(7);
        assertThat(internal.getString(1).toString()).isEqualTo("seven");

        Row external = converter.toExternal(internal);
        assertThat(external.getKind()).isEqualTo(RowKind.UPDATE_AFTER);
        assertThat(external.getField(0)).isEqualTo(7);
        assertThat(external.getField(1)).isEqualTo("seven");
        assertThat(converter.toInternal(null)).isNull();
    }

    @Test
    void testRowDataConversion() {
        DataType rowType =
                DataTypes.ROW(
                                DataTypes.FIELD("id", DataTypes.INT()),
                                DataTypes.FIELD("name", DataTypes.STRING()))
                        .bridgedTo(RowData.class);
        DataFormatConverter<RowData, RowData> converter = converter(rowType);

        RowData nested = GenericRowData.of(1, StringData.fromString("nested"));
        assertThat(converter.toInternal(nested)).isSameAs(nested);
        assertThat(converter.toExternal(nested)).isSameAs(nested);

        GenericRowData container = GenericRowData.of(nested);
        assertThat(converter.toExternal(container, 0)).isSameAs(nested);
        assertThat(converter.toExternal(GenericRowData.of((Object) null), 0)).isNull();
    }

    @Test
    void testNullHandlingForArraysAndMapsInRows() {
        DataFormatConverter<ArrayData, int[]> arrayConverter =
                converter(DataTypes.ARRAY(DataTypes.INT()).bridgedTo(int[].class));
        assertThat(arrayConverter.toExternal(GenericRowData.of((Object) null), 0)).isNull();
        assertThat(arrayConverter.toExternal((ArrayData) null)).isNull();

        DataFormatConverter<MapData, Map> mapConverter =
                converter(DataTypes.MAP(DataTypes.STRING(), DataTypes.INT()));
        assertThat(mapConverter.toExternal(GenericRowData.of((Object) null), 0)).isNull();
        assertThat(mapConverter.toExternal((MapData) null)).isNull();
    }
