package org.apache.flink.table.data;

import org.junit.jupiter.api.Test;

import java.math.BigDecimal;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

/** Tests for {@link DecimalDataUtils}. */
class DecimalDataUtilsTest {

    private static DecimalData dec(String value, int precision, int scale) {
        DecimalData result = DecimalData.fromBigDecimal(new BigDecimal(value), precision, scale);
        assertThat(result).as("test fixture must fit into precision/scale").isNotNull();
        return result;
    }

    @Test
    void testDecimalSystemDefault() {
        assertThat(DecimalDataUtils.DECIMAL_SYSTEM_DEFAULT.getPrecision()).isEqualTo(38);
        assertThat(DecimalDataUtils.DECIMAL_SYSTEM_DEFAULT.getScale()).isEqualTo(18);
    }

    @Test
    void testDoubleValue() {
        assertThat(DecimalDataUtils.doubleValue(dec("12.34", 5, 2))).isEqualTo(12.34d);
        assertThat(DecimalDataUtils.doubleValue(dec("-0.5", 5, 2))).isEqualTo(-0.5d);

        BigDecimal big = new BigDecimal("123456789012345678.99");
        DecimalData bigDecimal = dec(big.toPlainString(), 20, 2);
        assertThat(bigDecimal.isCompact()).isFalse();
        assertThat(DecimalDataUtils.doubleValue(bigDecimal)).isEqualTo(big.doubleValue());
    }

    @Test
    void testSignum() {
        assertThat(DecimalDataUtils.signum(dec("12.34", 5, 2))).isEqualTo(1);
        assertThat(DecimalDataUtils.signum(dec("-12.34", 5, 2))).isEqualTo(-1);
        assertThat(DecimalDataUtils.signum(dec("0.00", 5, 2))).isZero();

        assertThat(DecimalDataUtils.signum(dec("123456789012345678.99", 20, 2))).isEqualTo(1);
        assertThat(DecimalDataUtils.signum(dec("-123456789012345678.99", 20, 2))).isEqualTo(-1);
        assertThat(DecimalDataUtils.signum(dec("0.00", 20, 2))).isZero();
    }

    @Test
    void testNegateAndAbs() {
        DecimalData positive = dec("12.34", 5, 2);
        DecimalData negative = dec("-12.34", 5, 2);

        assertThat(DecimalDataUtils.negate(positive).toBigDecimal()).isEqualByComparingTo("-12.34");
        assertThat(DecimalDataUtils.negate(negative).toBigDecimal()).isEqualByComparingTo("12.34");
        assertThat(DecimalDataUtils.negate(positive).precision()).isEqualTo(5);
        assertThat(DecimalDataUtils.negate(positive).scale()).isEqualTo(2);

        assertThat(DecimalDataUtils.abs(negative).toBigDecimal()).isEqualByComparingTo("12.34");
        assertThat(DecimalDataUtils.abs(positive).toBigDecimal()).isEqualByComparingTo("12.34");
        assertThat(DecimalDataUtils.abs(positive)).isSameAs(positive);

        DecimalData bigNegative = dec("-123456789012345678.99", 20, 2);
        assertThat(DecimalDataUtils.negate(bigNegative).toBigDecimal())
                .isEqualByComparingTo("123456789012345678.99");
        assertThat(DecimalDataUtils.abs(bigNegative).toBigDecimal())
                .isEqualByComparingTo("123456789012345678.99");
    }

    @Test
    void testFloorAndCeil() {
        assertThat(DecimalDataUtils.floor(dec("2.9", 2, 1)).toBigDecimal())
                .isEqualByComparingTo("2");
        assertThat(DecimalDataUtils.floor(dec("-2.1", 2, 1)).toBigDecimal())
                .isEqualByComparingTo("-3");
        assertThat(DecimalDataUtils.floor(dec("-2.1", 2, 1)).scale()).isZero();

        assertThat(DecimalDataUtils.ceil(dec("2.1", 2, 1)).toBigDecimal())
                .isEqualByComparingTo("3");
        assertThat(DecimalDataUtils.ceil(dec("-2.9", 2, 1)).toBigDecimal())
                .isEqualByComparingTo("-2");
        assertThat(DecimalDataUtils.ceil(dec("2.1", 2, 1)).scale()).isZero();
    }

    @Test
    void testAddAndSubtract() {
        assertThat(DecimalDataUtils.add(dec("1.10", 5, 2), dec("2.20", 5, 2), 5, 2).toBigDecimal())
                .isEqualByComparingTo("3.30");
        assertThat(DecimalDataUtils.add(dec("1.10", 5, 2), dec("2.20", 5, 2), 5, 2).precision())
                .isEqualTo(5);

        assertThat(
                        DecimalDataUtils.subtract(dec("5.50", 5, 2), dec("2.25", 5, 2), 5, 2)
                                .toBigDecimal())
                .isEqualByComparingTo("3.25");

        // Values that do not fit in a long go through the BigDecimal path.
        DecimalData big = dec("123456789012345678.99", 20, 2);
        DecimalData added = DecimalDataUtils.add(big, dec("0.01", 5, 2), 20, 2);
        assertThat(added.toBigDecimal()).isEqualByComparingTo("123456789012345679.00");
        assertThat(added.isCompact()).isFalse();

        DecimalData subtracted = DecimalDataUtils.subtract(big, dec("0.99", 5, 2), 20, 2);
        assertThat(subtracted.toBigDecimal()).isEqualByComparingTo("123456789012345678.00");
    }

    @Test
    void testAddOverflowReturnsNullWhenPrecisionDoesNotFit() {
        DecimalData max = DecimalData.fromUnscaledLong(Long.MAX_VALUE, 18, 0);
        DecimalData one = DecimalData.fromUnscaledLong(1L, 18, 0);
        assertThat(DecimalDataUtils.add(max, one, 18, 0)).isNull();
    }

    @Test
    void testMultiplyDivideModAndDivideToIntegralValue() {
        assertThat(
                        DecimalDataUtils.multiply(dec("1.5", 3, 1), dec("2.0", 3, 1), 5, 2)
                                .toBigDecimal())
                .isEqualByComparingTo("3.00");

        assertThat(DecimalDataUtils.divide(dec("1", 5, 0), dec("3", 5, 0), 10, 4).toBigDecimal())
                .isEqualByComparingTo("0.3333");
        assertThat(DecimalDataUtils.divide(dec("10", 5, 0), dec("4", 5, 0), 10, 4).toBigDecimal())
                .isEqualByComparingTo("2.5000");

        assertThat(DecimalDataUtils.mod(dec("10", 5, 0), dec("3", 5, 0), 5, 0).toBigDecimal())
                .isEqualByComparingTo("1");
        assertThat(DecimalDataUtils.mod(dec("10.5", 5, 1), dec("3", 5, 0), 5, 1).toBigDecimal())
                .isEqualByComparingTo("1.5");

        assertThat(
                        DecimalDataUtils.divideToIntegralValue(
                                        dec("10", 5, 0), dec("3", 5, 0), 5, 0)
                                .toBigDecimal())
                .isEqualByComparingTo("3");
        assertThat(
                        DecimalDataUtils.divideToIntegralValue(
                                        dec("-10", 5, 0), dec("3", 5, 0), 5, 0)
                                .toBigDecimal())
                .isEqualByComparingTo("-3");

        assertThatThrownBy(() -> DecimalDataUtils.divide(dec("1", 5, 0), dec("0", 5, 0), 5, 0))
                .isInstanceOf(ArithmeticException.class);
        assertThatThrownBy(
                        () ->
                                DecimalDataUtils.divideToIntegralValue(
                                        dec("1", 5, 0), dec("0", 5, 0), 5, 0))
                .isInstanceOf(ArithmeticException.class);
    }

    @Test
    void testCasts() {
        assertThat(DecimalDataUtils.castToIntegral(dec("2.9", 2, 1))).isEqualTo(2L);
        assertThat(DecimalDataUtils.castToIntegral(dec("-2.9", 2, 1))).isEqualTo(-2L);
        assertThat(DecimalDataUtils.castToIntegral(dec("123456789012345678.99", 20, 2)))
                .isEqualTo(123456789012345678L);

        assertThat(DecimalDataUtils.castToDecimal(dec("1.234", 4, 3), 2, 1).toBigDecimal())
                .isEqualByComparingTo("1.2");
        assertThat(DecimalDataUtils.castToDecimal(dec("1.25", 3, 2), 2, 1).toBigDecimal())
                .isEqualByComparingTo("1.3");
        assertThat(DecimalDataUtils.castToDecimal(dec("999", 3, 0), 2, 0)).isNull();

        assertThat(DecimalDataUtils.castFrom(dec("1.234", 4, 3), 5, 2).toBigDecimal())
                .isEqualByComparingTo("1.23");
        assertThat(DecimalDataUtils.castFrom("12.34", 5, 2).toBigDecimal())
                .isEqualByComparingTo("12.34");
        assertThat(DecimalDataUtils.castFrom(1.5d, 5, 2).toBigDecimal())
                .isEqualByComparingTo("1.50");
        assertThat(DecimalDataUtils.castFrom(7L, 5, 2).toBigDecimal()).isEqualByComparingTo("7.00");
        assertThatThrownBy(() -> DecimalDataUtils.castFrom("not-a-number", 5, 2))
                .isInstanceOf(NumberFormatException.class);

        assertThat(DecimalDataUtils.castToBoolean(dec("0.00", 5, 2))).isFalse();
        assertThat(DecimalDataUtils.castToBoolean(dec("0.01", 5, 2))).isTrue();
        assertThat(DecimalDataUtils.castToBoolean(dec("-0.01", 5, 2))).isTrue();
    }

    @Test
    void testSign() {
        DecimalData positive = dec("12.34", 5, 2);
        DecimalData negative = dec("-12.34", 5, 2);
        DecimalData zero = dec("0.00", 5, 2);

        assertThat(DecimalDataUtils.sign(positive).toBigDecimal()).isEqualByComparingTo("1.00");
        assertThat(DecimalDataUtils.sign(negative).toBigDecimal()).isEqualByComparingTo("-1.00");
        assertThat(DecimalDataUtils.sign(zero).toBigDecimal()).isEqualByComparingTo("0.00");
        assertThat(DecimalDataUtils.sign(positive).precision()).isEqualTo(5);
        assertThat(DecimalDataUtils.sign(positive).scale()).isEqualTo(2);

        DecimalData bigNegative = dec("-123456789012345678.99", 20, 2);
        assertThat(DecimalDataUtils.sign(bigNegative).toBigDecimal()).isEqualByComparingTo("-1.00");
    }

    @Test
    void testCompare() {
        DecimalData a = dec("12.34", 5, 2);
        assertThat(DecimalDataUtils.compare(a, dec("12.34", 5, 2))).isZero();
        assertThat(DecimalDataUtils.compare(a, dec("12.35", 5, 2))).isNegative();
        assertThat(DecimalDataUtils.compare(a, dec("12.33", 5, 2))).isPositive();

        // DecimalData vs long, scale == 0.
        assertThat(DecimalDataUtils.compare(dec("5", 5, 0), 5L)).isZero();
        assertThat(DecimalDataUtils.compare(dec("5", 5, 0), 4L)).isPositive();
        assertThat(DecimalDataUtils.compare(dec("5", 5, 0), 6L)).isNegative();

        // DecimalData vs long, scale > 0.
        assertThat(DecimalDataUtils.compare(a, 12L)).isPositive();
        assertThat(DecimalDataUtils.compare(a, 13L)).isNegative();
        assertThat(DecimalDataUtils.compare(dec("-12.34", 5, 2), -13L)).isPositive();

        // DecimalData vs double.
        assertThat(DecimalDataUtils.compare(a, 12.34d)).isZero();
        assertThat(DecimalDataUtils.compare(a, 12.0d)).isPositive();

        // Non-compact decimal.
        DecimalData big = dec("123456789012345678.99", 20, 2);
        assertThat(DecimalDataUtils.compare(big, 123456789012345678L)).isPositive();
        assertThat(DecimalDataUtils.compare(big, 123456789012345679L)).isNegative();

        // Symmetric overloads.
        assertThat(DecimalDataUtils.compare(12L, a)).isNegative();
        assertThat(DecimalDataUtils.compare(13L, a)).isPositive();
        assertThat(DecimalDataUtils.compare(12.34d, a)).isZero();
        assertThat(DecimalDataUtils.compare(12.0d, a)).isNegative();
    }

    @Test
    void testSRound() {
        DecimalData value = dec("1.23", 5, 2);
        // Nothing to round.
        assertThat(DecimalDataUtils.sround(value, 2)).isSameAs(value);
        assertThat(DecimalDataUtils.sround(value, 5)).isSameAs(value);

        assertThat(DecimalDataUtils.sround(dec("1.23", 5, 2), 1).toBigDecimal())
                .isEqualByComparingTo("1.2");
        assertThat(DecimalDataUtils.sround(dec("1.25", 5, 2), 1).toBigDecimal())
                .isEqualByComparingTo("1.3");
        assertThat(DecimalDataUtils.sround(dec("1.26", 5, 2), 1).toBigDecimal())
                .isEqualByComparingTo("1.3");
        assertThat(DecimalDataUtils.sround(dec("-1.25", 5, 2), 1).toBigDecimal())
                .isEqualByComparingTo("-1.3");

        DecimalData rounded = DecimalDataUtils.sround(dec("123.456", 6, 3), -1);
        assertThat(rounded.toBigDecimal()).isEqualByComparingTo("120");
        assertThat(rounded.scale()).isZero();
    }

    @Test
    void testPower10AndSizeClassification() {
        assertThat(DecimalDataUtils.power10(0)).isEqualTo(1L);
        assertThat(DecimalDataUtils.power10(3)).isEqualTo(1000L);
        assertThat(DecimalDataUtils.power10(18)).isEqualTo(1_000_000_000_000_000_000L);

        assertThat(DecimalDataUtils.is32BitDecimal(0)).isTrue();
        assertThat(DecimalDataUtils.is32BitDecimal(9)).isTrue();
        assertThat(DecimalDataUtils.is32BitDecimal(10)).isFalse();

        assertThat(DecimalDataUtils.is64BitDecimal(9)).isFalse();
        assertThat(DecimalDataUtils.is64BitDecimal(10)).isTrue();
        assertThat(DecimalDataUtils.is64BitDecimal(18)).isTrue();
        assertThat(DecimalDataUtils.is64BitDecimal(19)).isFalse();

        assertThat(DecimalDataUtils.isByteArrayDecimal(18)).isFalse();
        assertThat(DecimalDataUtils.isByteArrayDecimal(19)).isTrue();
    }
}
