import org.junit.jupiter.api.Test;

import static org.assertj.core.api.Assertions.assertThat;

/** Tests for {@link org.apache.flink.table.data.util.RowDataUtil}. */
class RowDataUtilTest {

    @Test
    void testAccumulateMessages() {
        assertThat(
                        org.apache.flink.table.data.util.RowDataUtil.isAccumulateMsg(
                                row(RowKind.INSERT)))
                .isTrue();
        assertThat(
                        org.apache.flink.table.data.util.RowDataUtil.isAccumulateMsg(
                                row(RowKind.UPDATE_AFTER)))
                .isTrue();
        assertThat(
                        org.apache.flink.table.data.util.RowDataUtil.isAccumulateMsg(
                                row(RowKind.UPDATE_BEFORE)))
                .isFalse();
        assertThat(
                        org.apache.flink.table.data.util.RowDataUtil.isAccumulateMsg(
                                row(RowKind.DELETE)))
                .isFalse();
    }

    @Test
    void testRetractMessages() {
        assertThat(
                        org.apache.flink.table.data.util.RowDataUtil.isRetractMsg(
                                row(RowKind.UPDATE_BEFORE)))
                .isTrue();
        assertThat(org.apache.flink.table.data.util.RowDataUtil.isRetractMsg(row(RowKind.DELETE)))
                .isTrue();
        assertThat(org.apache.flink.table.data.util.RowDataUtil.isRetractMsg(row(RowKind.INSERT)))
                .isFalse();
        assertThat(
                        org.apache.flink.table.data.util.RowDataUtil.isRetractMsg(
                                row(RowKind.UPDATE_AFTER)))
                .isFalse();
    }

    @Test
    void testAccumulateAndRetractAreMutuallyExclusiveAndComplete() {
        for (RowKind kind : RowKind.values()) {
            RowData row = row(kind);
            boolean accumulate = org.apache.flink.table.data.util.RowDataUtil.isAccumulateMsg(row);
            boolean retract = org.apache.flink.table.data.util.RowDataUtil.isRetractMsg(row);
            assertThat(accumulate ^ retract)
                    .as("Exactly one of accumulate/retract must hold for %s", kind)
                    .isTrue();
        }
    }

    private static RowData row(RowKind kind) {
        return GenericRowData.ofKind(kind, 1, StringData.fromString("x"));
    }
