package org.apache.flink.table.data;

import org.apache.flink.types.RowKind;
import org.apache.flink.types.bitmap.Bitmap;
import org.apache.flink.types.bitmap.RoaringBitmapData;
import org.apache.flink.types.variant.Variant;

import org.junit.jupiter.api.Test;

import java.math.BigDecimal;
import java.util.HashMap;
import java.util.Map;

import static org.assertj.core.api.Assertions.assertThat;

/** Tests for {@link UpdatableRowData}. */
class UpdatableRowDataTest {

    private static DecimalData decimal(String value, int precision, int scale) {
        return DecimalData.fromBigDecimal(new BigDecimal(value), precision, scale);
    }

    @Test
    void testGetRowArityAndRowKindDelegation() {
        GenericRowData backing = GenericRowData.ofKind(RowKind.UPDATE_BEFORE, 1, 2);
        UpdatableRowData row = new UpdatableRowData(backing, 2);

        assertThat(row.getRow()).isSameAs(backing);
        assertThat(row.getArity()).isEqualTo(2);
        assertThat(row.getRowKind()).isEqualTo(RowKind.UPDATE_BEFORE);

        row.setRowKind(RowKind.DELETE);

        assertThat(row.getRowKind()).isEqualTo(RowKind.DELETE);
        // The row kind is delegated to (and stored in) the backing row.
        assertThat(backing.getRowKind()).isEqualTo(RowKind.DELETE);
    }

    @Test
    void testReadsFallBackToBackingRow() {
        DecimalData decimal = decimal("1.23", 5, 2);
        TimestampData timestamp = TimestampData.fromEpochMillis(1234L);
        byte[] binary = new byte[] {1, 2};
        StringData string = StringData.fromString("hello");
        RawValueData<String> raw = RawValueData.fromObject("raw");
        ArrayData array = new GenericArrayData(new int[] {3, 4});
        Map<Object, Object> javaMap = new HashMap<>();
        javaMap.put("k", "v");
        MapData map = new GenericMapData(javaMap);
        RowData nested = GenericRowData.of(7);
        Variant variant = Variant.newBuilder().of("variant");
        Bitmap bitmap = RoaringBitmapData.fromArray(new int[] {1, 2});

        GenericRowData backing = new GenericRowData(15);
        backing.setField(0, true);
        backing.setField(1, (byte) 1);
        backing.setField(2, (short) 2);
        backing.setField(3, 3);
        backing.setField(4, 4L);
        backing.setField(5, 5.5f);
        backing.setField(6, 6.5d);
        backing.setField(7, binary);
        backing.setField(8, string);
        backing.setField(9, decimal);
        backing.setField(10, timestamp);
        backing.setField(11, raw);
        backing.setField(12, nested);
        backing.setField(13, array);
        backing.setField(14, map);

        UpdatableRowData row = new UpdatableRowData(backing, 15);

        assertThat(row.isNullAt(0)).isFalse();
        assertThat(row.getBoolean(0)).isTrue();
        assertThat(row.getByte(1)).isEqualTo((byte) 1);
        assertThat(row.getShort(2)).isEqualTo((short) 2);
        assertThat(row.getInt(3)).isEqualTo(3);
        assertThat(row.getLong(4)).isEqualTo(4L);
        assertThat(row.getFloat(5)).isEqualTo(5.5f);
        assertThat(row.getDouble(6)).isEqualTo(6.5d);
        assertThat(row.getBinary(7)).isSameAs(binary);
        assertThat(row.getString(8)).isSameAs(string);
        assertThat(row.getDecimal(9, 5, 2)).isSameAs(decimal);
        assertThat(row.getTimestamp(10, 3)).isSameAs(timestamp);
        assertThat(row.<String>getRawValue(11)).isSameAs(raw);
        assertThat(row.getRow(12, 1)).isSameAs(nested);
        assertThat(row.getArray(13)).isSameAs(array);
        assertThat(row.getMap(14)).isSameAs(map);

        // Variant and bitmap are delegated as well (stored in different backing positions).
        GenericRowData extraBacking = new GenericRowData(2);
        extraBacking.setField(0, variant);
        extraBacking.setField(1, bitmap);
        UpdatableRowData extra = new UpdatableRowData(extraBacking, 2);
        assertThat(extra.getVariant(0)).isSameAs(variant);
        assertThat(extra.getBitmap(1)).isSameAs(bitmap);
    }

    @Test
    void testUpdatedValuesOverrideBackingRow() {
        DecimalData originalDecimal = decimal("1.23", 5, 2);
        TimestampData originalTimestamp = TimestampData.fromEpochMillis(1000L);
        byte[] originalBinary = new byte[] {1};

        GenericRowData backing = new GenericRowData(15);
        backing.setField(0, true);
        backing.setField(1, (byte) 1);
        backing.setField(2, (short) 2);
        backing.setField(3, 3);
        backing.setField(4, 4L);
        backing.setField(5, 5f);
        backing.setField(6, 6d);
        backing.setField(7, originalBinary);
        backing.setField(8, StringData.fromString("old"));
        backing.setField(9, originalDecimal);
        backing.setField(10, originalTimestamp);
        backing.setField(11, RawValueData.fromObject("old"));
        backing.setField(12, GenericRowData.of(1));
        backing.setField(13, new GenericArrayData(new int[] {1}));
        backing.setField(14, new GenericMapData(new HashMap<>()));

        UpdatableRowData row = new UpdatableRowData(backing, 15);

        TimestampData newTimestamp = TimestampData.fromEpochMillis(2000L);
        DecimalData newDecimal = decimal("9.99", 5, 2);
        byte[] newBinary = new byte[] {9};
        RawValueData<String> newRaw = RawValueData.fromObject("new");
        RowData newNested = GenericRowData.of(2);
        ArrayData newArray = new GenericArrayData(new int[] {8});
        Map<Object, Object> newJavaMap = new HashMap<>();
        newJavaMap.put("n", 1);
        MapData newMap = new GenericMapData(newJavaMap);
        StringData newString = StringData.fromString("new");

        row.setBoolean(0, false);
        row.setByte(1, (byte) 9);
        row.setShort(2, (short) 8);
        row.setInt(3, 7);
        row.setLong(4, 6L);
        row.setFloat(5, 5.5f);
        row.setDouble(6, 4.5d);
        row.setField(7, newBinary);
        row.setField(8, newString);
        row.setDecimal(9, newDecimal, 5);
        row.setTimestamp(10, newTimestamp, 3);
        row.setField(11, newRaw);
        row.setField(12, newNested);
        row.setField(13, newArray);
        row.setField(14, newMap);

        assertThat(row.getBoolean(0)).isFalse();
        assertThat(row.getByte(1)).isEqualTo((byte) 9);
        assertThat(row.getShort(2)).isEqualTo((short) 8);
        assertThat(row.getInt(3)).isEqualTo(7);
        assertThat(row.getLong(4)).isEqualTo(6L);
        assertThat(row.getFloat(5)).isEqualTo(5.5f);
        assertThat(row.getDouble(6)).isEqualTo(4.5d);
        assertThat(row.getBinary(7)).isSameAs(newBinary);
        assertThat(row.getString(8)).isSameAs(newString);
        assertThat(row.getDecimal(9, 5, 2)).isSameAs(newDecimal);
        assertThat(row.getTimestamp(10, 3)).isSameAs(newTimestamp);
        assertThat(row.<String>getRawValue(11)).isSameAs(newRaw);
        assertThat(row.getRow(12, 1)).isSameAs(newNested);
        assertThat(row.getArray(13)).isSameAs(newArray);
        assertThat(row.getMap(14)).isSameAs(newMap);

        // The backing row must not be mutated by the updatable view.
        assertThat(backing.getBoolean(0)).isTrue();
        assertThat(backing.getInt(3)).isEqualTo(3);
        assertThat(backing.getString(8)).isEqualTo(StringData.fromString("old"));
        assertThat(backing.getDecimal(9, 5, 2)).isSameAs(originalDecimal);
        assertThat(backing.getTimestamp(10, 3)).isSameAs(originalTimestamp);
    }

    @Test
    void testSetNullAtMarksFieldAsNull() {
        GenericRowData backing = GenericRowData.of(1, 2);
        UpdatableRowData row = new UpdatableRowData(backing, 2);

        assertThat(row.isNullAt(0)).isFalse();
        row.setNullAt(0);

        assertThat(row.isNullAt(0)).isTrue();
        // The backing row is unaffected.
        assertThat(backing.isNullAt(0)).isFalse();
        assertThat(backing.getInt(0)).isEqualTo(1);

        row.setInt(0, 5);
        assertThat(row.isNullAt(0)).isFalse();
        assertThat(row.getInt(0)).isEqualTo(5);
    }

    @Test
    void testNullInBackingRowIsVisibleBeforeUpdate() {
        GenericRowData backing = GenericRowData.of((Object) null, 2);
        UpdatableRowData row = new UpdatableRowData(backing, 2);

        assertThat(row.isNullAt(0)).isTrue();
        assertThat(row.isNullAt(1)).isFalse();

        row.setInt(0, 1);
        assertThat(row.isNullAt(0)).isFalse();
        assertThat(row.getInt(0)).isEqualTo(1);
    }
}

