import org.junit.jupiter.api.Test;

import static org.assertj.core.api.Assertions.assertThat;

/** Tests for {@link BinaryRowDataUtil}. */
class BinaryRowDataUtilTest {

    @Test
    void testEmptyRow() {
        assertThat(BinaryRowDataUtil.EMPTY_ROW.getArity()).isZero();
        assertThat(BinaryRowDataUtil.EMPTY_ROW.getFixedLengthPartSize()).isPositive();
        assertThat(BinaryRowDataUtil.EMPTY_ROW.getSizeInBytes())
                .isEqualTo(BinaryRowDataUtil.EMPTY_ROW.getFixedLengthPartSize());
    }

    @Test
    void testByteArrayEquals() {
        byte[] left = new byte[16];
        byte[] right = new byte[16];
        for (int i = 0; i < left.length; i++) {
            left[i] = (byte) i;
            right[i] = (byte) i;
        }

        assertThat(BinaryRowDataUtil.byteArrayEquals(left, right, left.length)).isTrue();
        assertThat(BinaryRowDataUtil.byteArrayEquals(left, right, 0)).isTrue();

        // Only the requested prefix is compared.
        right[15] = (byte) 99;
        assertThat(BinaryRowDataUtil.byteArrayEquals(left, right, 15)).isTrue();
        assertThat(BinaryRowDataUtil.byteArrayEquals(left, right, 16)).isFalse();

        // Mismatch in the first 8-byte chunk.
        right = left.clone();
        right[0] = (byte) 99;
        assertThat(BinaryRowDataUtil.byteArrayEquals(left, right, 16)).isFalse();

        // Mismatch in the tail handled byte by byte.
        right = left.clone();
        right[9] = (byte) 99;
        assertThat(BinaryRowDataUtil.byteArrayEquals(left, right, 16)).isFalse();
    }

    @Test
    void testByteArrayEqualsWithOffsets() {
        byte[] left = {9, 9, 1, 2, 3, 4, 9};
        byte[] right = {8, 8, 1, 2, 3, 4, 8};

        int base = BinaryRowDataUtil.BYTE_ARRAY_BASE_OFFSET;
        assertThat(BinaryRowDataUtil.byteArrayEquals(left, base + 2, right, base + 2, 4)).isTrue();

        right[5] = 7;
        assertThat(BinaryRowDataUtil.byteArrayEquals(left, base + 2, right, base + 2, 4)).isFalse();
    }
}

