        // Large precision uses the BigDecimal code path.
        assertThat(
                        BinaryStringDataUtil.toDecimal(bs("123456789012345678.99"), 20, 2)
                                .toBigDecimal())
                .isEqualByComparingTo("123456789012345678.99");

        assertThatThrownBy(() -> BinaryStringDataUtil.toDecimal(bs("12345"), 2, 0))
                .isInstanceOf(NumberFormatException.class);
        assertThatThrownBy(() -> BinaryStringDataUtil.toDecimal(bs("   "), 5, 2))
                .isInstanceOf(NumberFormatException.class);
        assertThatThrownBy(() -> BinaryStringDataUtil.toDecimal(bs("+"), 5, 2))
                .isInstanceOf(NumberFormatException.class);
        assertThatThrownBy(() -> BinaryStringDataUtil.toDecimal(bs("1.2.3"), 5, 2))
                .isInstanceOf(NumberFormatException.class);
    }

    @Test
    void testToLong() {
        assertThat(BinaryStringDataUtil.toLong(bs("0"))).isZero();
        assertThat(BinaryStringDataUtil.toLong(bs("123"))).isEqualTo(123L);
        assertThat(BinaryStringDataUtil.toLong(bs("+42"))).isEqualTo(42L);
        assertThat(BinaryStringDataUtil.toLong(bs("-9223372036854775808")))
