package org.apache.flink.table.data;

import org.apache.flink.types.RowKind;
import org.apache.flink.types.bitmap.Bitmap;
import org.apache.flink.types.bitmap.RoaringBitmapData;
import org.apache.flink.types.variant.Variant;

import org.junit.jupiter.api.Test;

import java.math.BigDecimal;
import java.util.HashMap;
import java.util.Map;

import static org.assertj.core.api.Assertions.assertThat;

/** Tests for {@link BoxedWrapperRowData}. */
class BoxedWrapperRowDataTest {

    @Test
    void testArityAndDefaultRowKind() {
        BoxedWrapperRowData row = new BoxedWrapperRowData(3);
        assertThat(row.getArity()).isEqualTo(3);
        assertThat(row.getRowKind()).isEqualTo(RowKind.INSERT);
        assertThat(row.isNullAt(0)).isTrue();
        assertThat(row.isNullAt(2)).isTrue();
    }

    @Test
    void testSetRowKind() {
        BoxedWrapperRowData row = new BoxedWrapperRowData(1);
        for (RowKind kind : RowKind.values()) {
            row.setRowKind(kind);
            assertThat(row.getRowKind()).isSameAs(kind);
        }
    }

    @Test
    void testPrimitiveTypedSettersAndGetters() {
        BoxedWrapperRowData row = new BoxedWrapperRowData(7);

        row.setBoolean(0, true);
        row.setByte(1, (byte) 12);
        row.setShort(2, (short) 345);
        row.setInt(3, 6789);
        row.setLong(4, 10_000_000_000L);
        row.setFloat(5, 1.5f);
        row.setDouble(6, 2.25d);

        for (int i = 0; i < 7; i++) {
            assertThat(row.isNullAt(i)).isFalse();
        }
        assertThat(row.getBoolean(0)).isTrue();
        assertThat(row.getByte(1)).isEqualTo((byte) 12);
        assertThat(row.getShort(2)).isEqualTo((short) 345);
        assertThat(row.getInt(3)).isEqualTo(6789);
        assertThat(row.getLong(4)).isEqualTo(10_000_000_000L);
        assertThat(row.getFloat(5)).isEqualTo(1.5f);
        assertThat(row.getDouble(6)).isEqualTo(2.25d);
    }

    @Test
    void testRepeatedSetterReusesWrapperAndUpdatesValue() {
        BoxedWrapperRowData row = new BoxedWrapperRowData(1);
        row.setInt(0, 1);
        row.setInt(0, 2);
        assertThat(row.getInt(0)).isEqualTo(2);
    }

    @Test
    void testSetNullAt() {
        BoxedWrapperRowData row = new BoxedWrapperRowData(2);
        row.setInt(0, 42);
        row.setBoolean(1, true);
        assertThat(row.isNullAt(0)).isFalse();

        row.setNullAt(0);
        row.setNullAt(1);
        assertThat(row.isNullAt(0)).isTrue();
        assertThat(row.isNullAt(1)).isTrue();

        row.setInt(0, 7);
        assertThat(row.isNullAt(0)).isFalse();
        assertThat(row.getInt(0)).isEqualTo(7);
    }

    @Test
    void testNonPrimitiveFields() {
        BoxedWrapperRowData row = new BoxedWrapperRowData(10);

        StringData string = StringData.fromString("hello");
        DecimalData decimal = DecimalData.fromBigDecimal(new BigDecimal("1.23"), 5, 2);
        TimestampData timestamp = TimestampData.fromEpochMillis(1234L);
        byte[] binary = new byte[] {1, 2, 3};
        ArrayData array = new GenericArrayData(new int[] {1, 2});
        Map<Object, Object> mapValues = new HashMap<>();
        mapValues.put("k", 1);
        MapData map = new GenericMapData(mapValues);
        RowData nested = GenericRowData.of(1, StringData.fromString("nested"));
        RawValueData<String> raw = RawValueData.fromObject("raw");
        Variant variant = Variant.newBuilder().of(7);
        Bitmap bitmap = RoaringBitmapData.fromArray(new int[] {1, 3, 5});

        row.setNonPrimitiveValue(0, string);
        row.setDecimal(1, decimal, 5);
        row.setTimestamp(2, timestamp, 3);
        row.setNonPrimitiveValue(3, binary);
        row.setNonPrimitiveValue(4, array);
        row.setNonPrimitiveValue(5, map);
        row.setNonPrimitiveValue(6, nested);
        row.setNonPrimitiveValue(7, raw);
        row.setNonPrimitiveValue(8, variant);
        row.setNonPrimitiveValue(9, bitmap);

        assertThat(row.getString(0)).isSameAs(string);
        assertThat(row.getDecimal(1, 5, 2)).isSameAs(decimal);
        assertThat(row.getTimestamp(2, 3)).isSameAs(timestamp);
        assertThat(row.getBinary(3)).isSameAs(binary);
        assertThat(row.getArray(4)).isSameAs(array);
        assertThat(row.getMap(5)).isSameAs(map);
        assertThat(row.getRow(6, 2)).isSameAs(nested);
        assertThat(row.<String>getRawValue(7)).isSameAs(raw);
        assertThat(row.getVariant(8)).isSameAs(variant);
        assertThat(row.getBitmap(9)).isSameAs(bitmap);
    }

    @Test
    void testToStringRendersBinaryArrayAware() {
        BoxedWrapperRowData row = new BoxedWrapperRowData(1);
        row.setNonPrimitiveValue(0, new byte[] {1, 2, 3});
        assertThat(row.toString()).isEqualTo("+I([1, 2, 3])");
    }

    @Test
    void testEqualsAndHashCode() {
        BoxedWrapperRowData first = new BoxedWrapperRowData(3);
        first.setInt(0, 1);
        first.setNonPrimitiveValue(1, StringData.fromString("a"));
        first.setBoolean(2, false);

        BoxedWrapperRowData second = new BoxedWrapperRowData(3);
        second.setInt(0, 1);
        second.setNonPrimitiveValue(1, StringData.fromString("a"));
        second.setBoolean(2, false);

        assertThat(first).isEqualTo(second);
        assertThat(first.hashCode()).isEqualTo(second.hashCode());

        second.setInt(0, 2);
        assertThat(first).isNotEqualTo(second);

        second.setInt(0, 1);
        second.setRowKind(RowKind.DELETE);
        assertThat(first).isNotEqualTo(second);

        assertThat(first).isNotEqualTo(GenericRowData.of(1, StringData.fromString("a"), false));
        assertThat(first).isNotEqualTo(null);
    }

    @Test
    void testToString() {
        BoxedWrapperRowData row = new BoxedWrapperRowData(3);
        row.setNonPrimitiveValue(0, StringData.fromString("a"));
        row.setInt(1, 1);
        row.setNullAt(2);

        assertThat(row.toString()).isEqualTo("+I(a,1,null)");

        row.setRowKind(RowKind.UPDATE_BEFORE);
        assertThat(row.toString()).isEqualTo("-U(a,1,null)");
    }
}

