                FlinkYarnSessionCli.getYarnPropertiesLocation(propertiesDirectory.toString());
        Files.write(propertiesFile.toPath(), Arrays.asList(lines), StandardCharsets.UTF_8);
    }

    private static Properties loadYarnProperties(java.nio.file.Path propertiesDirectory)
            throws Exception {
        final Properties properties = new Properties();
        try (InputStream input =
                new FileInputStream(
                        FlinkYarnSessionCli.getYarnPropertiesLocation(
                                propertiesDirectory.toString()))) {
            properties.load(input);
        }
        return properties;
    }

    @SuppressWarnings("unchecked")
    private static ClusterClient<ApplicationId> createClusterClient(
            ApplicationId applicationId, AtomicBoolean closed) {
        return (ClusterClient<ApplicationId>)
                Proxy.newProxyInstance(
                        FlinkYarnSessionCliTest.class.getClassLoader(),
                        new Class<?>[] {ClusterClient.class},
                        (proxy, method, args) -> {
                            switch (method.getName()) {
                                case "getClusterId":
                                    return applicationId;
                                case "getWebInterfaceURL":
                                    return "http://jobmanager:8081";
                                case "close":
                                    closed.set(true);
                                    return null;
                                case "toString":
                                    return "TestingClusterClient";
                                case "hashCode":
                                    return System.identityHashCode(proxy);
                                case "equals":
                                    return proxy == args[0];
                                default:
                                    throw new AssertionError(
                                            "Unexpected ClusterClient call: " + method.getName());
                            }
                        });
    }

