    private static final class TestingYarnClusterDescriptor extends YarnClusterDescriptor {

        private String clusterDescription;
        private ClusterClientProvider<ApplicationId> deploymentProvider;
        private ClusterClientProvider<ApplicationId> retrieveProvider;
        private ClusterSpecification deployedSpecification;
        private ApplicationId retrievedApplicationId;
        private ApplicationId killedApplicationId;
        private int descriptionCalls;
        private int deployCalls;
        private int retrieveCalls;
        private int closeCalls;

