                .isInstanceOf(IllegalStateException.class)
                .hasMessage(YarnDeploymentTarget.ERROR_MESSAGE);
    }

    @Test
    void testThrowsHelpfulErrorWhenApplicationIdIsGiven() throws CliArgsException {
        final FallbackYarnSessionCli cli = new FallbackYarnSessionCli(new Configuration());

