        final Configuration configuration = new Configuration();
        configuration.set(YarnConfigOptions.APPLICATION_ID, APPLICATION_ID);
        final FallbackYarnSessionCli cli = new FallbackYarnSessionCli(configuration);

        assertThatThrownBy(() -> cli.isActive(cli.parseCommandLineOptions(new String[0], true)))
                .isInstanceOf(IllegalStateException.class)
                .hasMessage(YarnDeploymentTarget.ERROR_MESSAGE);
    }

    @Test
    void testThrowsHelpfulErrorWhenYarnSessionTargetIsConfigured() throws CliArgsException {
        final Configuration configuration = new Configuration();
        configuration.set(DeploymentOptions.TARGET, YarnSessionClusterExecutor.NAME);
        final FallbackYarnSessionCli cli = new FallbackYarnSessionCli(configuration);

        assertThatThrownBy(() -> cli.isActive(cli.parseCommandLineOptions(new String[0], true)))
                .isInstanceOf(IllegalStateException.class)
                .hasMessage(YarnDeploymentTarget.ERROR_MESSAGE);
    }

    @Test
    void testInheritsYarnClusterIdentifier() {
        assertThat(new FallbackYarnSessionCli(new Configuration()).getId())
                .isEqualTo("yarn-cluster");
    }
