    @Test
    void testToConfigurationMapsAllProvidedSessionOptions() throws Exception {
        final FlinkYarnSessionCli cli = createCli(newConfiguration(temporaryDirectory));
        final java.nio.file.Path jar = Files.createFile(temporaryDirectory.resolve("flink.jar"));
        final java.nio.file.Path shipDirectory =
                Files.createDirectory(temporaryDirectory.resolve("ship-data"));

        final CommandLine commandLine =
                cli.parseCommandLineOptions(
                        new String[] {
                            "--queue",
                            "analytics",
                            "--jar",
                            jar.toString(),
                            "--jobManagerMemory",
                            "512",
                            "--taskManagerMemory",
                            "2g",
                            "--slots",
                            "6",
                            "--name",
                            "session-name",
                            "--applicationType",
                            "FLINK_SESSION",
                            "--zookeeperNamespace",
                            "zk-session",
                            "--nodeLabel",
                            "gpu",
                            "--ship",
                            shipDirectory.toString(),
                            "--applicationId",
                            APPLICATION_ID_STRING,
                            "-Dpipeline.name=custom-name",
                            "-Dcustom.option=custom-value",
                            "--detached"
                        },
                        true);

        final Configuration effectiveConfiguration = cli.toConfiguration(commandLine);

        assertThat(effectiveConfiguration.get(DeploymentOptions.TARGET))
                .isEqualTo(YarnSessionClusterExecutor.NAME);
        assertThat(effectiveConfiguration.get(DeploymentOptions.ATTACHED)).isFalse();
        assertThat(effectiveConfiguration.get(DeploymentOptionsInternal.CONF_DIR))
                .isEqualTo(temporaryDirectory.toString());
        assertThat(effectiveConfiguration.get(YarnConfigOptions.APPLICATION_QUEUE))
                .isEqualTo("analytics");
        assertThat(effectiveConfiguration.get(YarnConfigOptions.FLINK_DIST_JAR))
                .isEqualTo(new Path("file://" + jar).toString());
        assertThat(effectiveConfiguration.get(YarnConfigOptions.SHIP_FILES))
                .containsExactly(shipDirectory.toString());
        assertThat(effectiveConfiguration.get(JobManagerOptions.TOTAL_PROCESS_MEMORY))
                .isEqualTo(MemorySize.parse("512m"));
        assertThat(effectiveConfiguration.get(TaskManagerOptions.TOTAL_PROCESS_MEMORY))
                .isEqualTo(MemorySize.parse("2g"));
        assertThat(effectiveConfiguration.get(TaskManagerOptions.NUM_TASK_SLOTS)).isEqualTo(6);
        assertThat(effectiveConfiguration.get(YarnConfigOptions.APPLICATION_NAME))
                .isEqualTo("session-name");
        assertThat(effectiveConfiguration.get(YarnConfigOptions.APPLICATION_TYPE))
                .isEqualTo("FLINK_SESSION");
        assertThat(effectiveConfiguration.get(YarnConfigOptions.NODE_LABEL)).isEqualTo("gpu");
        assertThat(effectiveConfiguration.get(YarnConfigOptions.APPLICATION_ID))
                .isEqualTo(APPLICATION_ID_STRING);
        assertThat(effectiveConfiguration.get(HighAvailabilityOptions.HA_CLUSTER_ID))
                .isEqualTo("zk-session");
        assertThat(effectiveConfiguration.getString("pipeline.name", null))
                .isEqualTo("custom-name");
        assertThat(effectiveConfiguration.getString("custom.option", null))
                .isEqualTo("custom-value");
    }

