        final FlinkYarnSessionCli cli = createCli(newConfiguration(temporaryDirectory));

        assertThatThrownBy(() -> cli.run(new String[] {"--slots"}))
                .isInstanceOf(CliArgsException.class);
    }

    private FlinkYarnSessionCli createCli(Configuration configuration) throws FlinkException {
        return new FlinkYarnSessionCli(configuration, temporaryDirectory.toString(), "", "", false);
    }

    private FlinkYarnSessionCli createCli(
            Configuration configuration, ClusterClientServiceLoader serviceLoader)
            throws FlinkException {
        return new FlinkYarnSessionCli(
                configuration, serviceLoader, temporaryDirectory.toString(), "", "", false);
    }

    private Configuration newConfiguration(java.nio.file.Path propertiesDirectory) {
        final Configuration configuration = new Configuration();
        configuration.set(
                YarnConfigOptions.PROPERTIES_FILE_LOCATION, propertiesDirectory.toString());
        return configuration;
    }

    private static void writeYarnPropertiesFile(
            java.nio.file.Path propertiesDirectory, String... lines) throws Exception {
        final File propertiesFile =
                FlinkYarnSessionCli.getYarnPropertiesLocation(propertiesDirectory.toString());
        Files.write(propertiesFile.toPath(), Arrays.asList(lines), StandardCharsets.UTF_8);
    }

    private static Properties loadYarnProperties(java.nio.file.Path propertiesDirectory)
            throws Exception {
        final Properties properties = new Properties();
        try (InputStream input =
                new FileInputStream(
                        FlinkYarnSessionCli.getYarnPropertiesLocation(
                                propertiesDirectory.toString()))) {
            properties.load(input);
        }
        return properties;
    }

    @SuppressWarnings("unchecked")
    private static ClusterClient<ApplicationId> createClusterClient(
            ApplicationId applicationId, AtomicBoolean closed) {
        return (ClusterClient<ApplicationId>)
                Proxy.newProxyInstance(
                        FlinkYarnSessionCliTest.class.getClassLoader(),
                        new Class<?>[] {ClusterClient.class},
                        (proxy, method, args) -> {
                            switch (method.getName()) {
                                case "getClusterId":
                                    return applicationId;
                                case "getWebInterfaceURL":
                                    return "http://jobmanager:8081";
                                case "close":
                                    closed.set(true);
                                    return null;
                                case "toString":
                                    return "TestingClusterClient";
                                case "hashCode":
                                    return System.identityHashCode(proxy);
                                case "equals":
                                    return proxy == args[0];
                                default:
                                    throw new AssertionError(
                                            "Unexpected ClusterClient call: " + method.getName());
                            }
                        });
    }

    /** Service loader backed by a single in-memory factory. */
    private static final class TestingClusterClientServiceLoader
            implements ClusterClientServiceLoader {

        private final ClusterClientFactory<ApplicationId> factory;
        private int getFactoryCalls;

        private TestingClusterClientServiceLoader(ClusterClientFactory<ApplicationId> factory) {
            this.factory = factory;
        }

        @Override
        @SuppressWarnings("unchecked")
        public <ClusterID> ClusterClientFactory<ClusterID> getClusterClientFactory(
                Configuration configuration) {
            getFactoryCalls++;
            return (ClusterClientFactory<ClusterID>) factory;
        }

        @Override
        public Stream<String> getApplicationModeTargetNames() {
            return Stream.empty();
        }
    }

    /** In-memory cluster client factory which records specification requests. */
    private static final class TestingClusterClientFactory
            implements ClusterClientFactory<ApplicationId> {

        private final TestingYarnClusterDescriptor descriptor;
        private final ClusterSpecification specification =
                new ClusterSpecification.ClusterSpecificationBuilder()
                        .setMasterMemoryMB(1024)
                        .setTaskManagerMemoryMB(2048)
                        .setSlotsPerTaskManager(2)
                        .createClusterSpecification();
        private int specificationCalls;

        private TestingClusterClientFactory(TestingYarnClusterDescriptor descriptor) {
            this.descriptor = descriptor;
        }

        @Override
        public boolean isCompatibleWith(Configuration configuration) {
            return true;
        }

        @Override
        public YarnClusterDescriptor createClusterDescriptor(Configuration configuration) {
            return descriptor;
        }

        @Override
        public ApplicationId getClusterId(Configuration configuration) {
            return null;
        }

        @Override
        public ClusterSpecification getClusterSpecification(Configuration configuration) {
            specificationCalls++;
            return specification;
        }
    }

    /** Descriptor double which avoids creating or contacting an actual YARN cluster. */
    private static final class TestingYarnClusterDescriptor extends YarnClusterDescriptor {

        private String clusterDescription;
        private ClusterClientProvider<ApplicationId> deploymentProvider;
        private ClusterClientProvider<ApplicationId> retrieveProvider;
        private ClusterSpecification deployedSpecification;
        private ApplicationId retrievedApplicationId;
        private ApplicationId killedApplicationId;
        private int descriptionCalls;
        private int deployCalls;
        private int retrieveCalls;
        private int closeCalls;

        private TestingYarnClusterDescriptor() {
            super(
                    new Configuration(),
                    new YarnConfiguration(),
                    YarnClient.createYarnClient(),
                    () -> 1,
                    true);
        }

        @Override
        public String getClusterDescription() {
            descriptionCalls++;
            return clusterDescription;
        }

        @Override
        public ClusterClientProvider<ApplicationId> deploySessionCluster(
                ClusterSpecification clusterSpecification) throws ClusterDeploymentException {
            deployCalls++;
            deployedSpecification = clusterSpecification;
            return deploymentProvider;
        }

        @Override
        public ClusterClientProvider<ApplicationId> retrieve(ApplicationId applicationId)
                throws ClusterRetrieveException {
            retrieveCalls++;
            retrievedApplicationId = applicationId;
            return retrieveProvider;
        }

        @Override
        public void killCluster(ApplicationId applicationId) throws FlinkException {
            killedApplicationId = applicationId;
        }

        @Override
        public void close() {
            closeCalls++;
        }
    }
